INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9ca6eb0d-a5de-e970-da3d-a5b4b34f26c2', 1, 'When it''s time for bed, it''s important to have a good night''s sleep. Sleep helps our bodies and brains grow strong and healthy.', 'tiempo', '⏰'),
  ('9ca6eb0d-a5de-e970-da3d-a5b4b34f26c2', 2, 'At bedtime, we do certain things to help us get ready for sleep. First, we change into our cozy pajamas. Next, we brush our teeth to keep them clean and healthy. Then, we choose a favorite stuffed animal or blanket to snuggle with. We can also listen to calming music or read a book to relax our minds.', 'vestirse', '👕'),
  ('9ca6eb0d-a5de-e970-da3d-a5b4b34f26c2', 3, 'Once we''re in bed, we close our eyes and take deep breaths. We imagine ourselves in a peaceful place, like floating on a cloud or sitting by the ocean. This helps us feel calm and sleepy.', 'respirar', '🫁'),
  ('9ca6eb0d-a5de-e970-da3d-a5b4b34f26c2', 4, 'Sometimes, it may be hard to fall asleep right away. If that happens, we can try counting sheep or thinking of happy thoughts. It''s okay if it takes a little while to fall asleep. Our bodies will rest and recharge when they are ready.', 'a veces', '⏳'),
  ('9ca6eb0d-a5de-e970-da3d-a5b4b34f26c2', 5, 'Having a good night''s sleep is important for our health and well-being. When we follow our bedtime routine and relax our minds, we can have sweet dreams and wake up feeling refreshed in the morning.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('05769a14-3c11-b062-89cf-9a78c0b2cceb', 1, 'Seeing happy faces makes me feel good inside. When I see someone smiling, it warms my heart.', 'feliz', '😊'),
  ('05769a14-3c11-b062-89cf-9a78c0b2cceb', 2, 'Happy faces can look different. Some people smile with their mouths, some with their eyes, and some with both. A smile means someone is feeling happy or friendly.', 'feliz', '😊'),
  ('05769a14-3c11-b062-89cf-9a78c0b2cceb', 3, 'When I see a happy face, I can say, "Hi!" or "How are you?" to show that I notice their happiness. It''s nice to share in someone else''s joy.', 'ver', '👀'),
  ('05769a14-3c11-b062-89cf-9a78c0b2cceb', 4, 'If someone looks sad, they might have a frown on their face or tears in their eyes. That means they are feeling upset or unhappy. I can ask if they need help or offer a kind word to comfort them.', 'alguien', '✨'),
  ('05769a14-3c11-b062-89cf-9a78c0b2cceb', 5, 'Understanding how others feel helps me connect with them and be a caring friend. Just like how seeing happy faces brightens my day, I can also bring smiles to others by being kind and supportive.', 'sentir', '💓'),
  ('05769a14-3c11-b062-89cf-9a78c0b2cceb', 6, 'Happy faces, happy hearts. When I see someone happy, I can greet them warmly. And when someone seems sad, I can offer comfort and kindness. Happy faces make the world a brighter place.', 'feliz', '😊');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('07e30205-ffa7-b740-5424-f8423224a38f', 1, 'The feelings wheel is a tool that helps us understand our emotions. It has different words for different feelings, and it can help us express how we are feeling.', 'sentimientos', '💗'),
  ('07e30205-ffa7-b740-5424-f8423224a38f', 2, 'When I am happy, the feelings wheel says I might feel joyful, content, or cheerful. When I am sad, I might feel downhearted, gloomy, or melancholy. If I am angry, I could be furious, annoyed, or frustrated. The feelings wheel also shows that feeling scared might make me anxious, worried, or fearful. Sometimes, I may feel surprised, curious, or amazed.', 'feliz', '😊'),
  ('07e30205-ffa7-b740-5424-f8423224a38f', 3, 'It''s okay to have all these feelings. Everyone feels them sometimes. We can use the feelings wheel to talk about our emotions with others and find ways to feel better when we''re upset.', 'todo', '🌐'),
  ('07e30205-ffa7-b740-5424-f8423224a38f', 4, 'The feelings wheel helps us understand and express our emotions. It''s okay to have different feelings, and using the feelings wheel can help us communicate how we feel to others.', 'sentimientos', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7b08ff59-84c4-6c52-93dc-344ddfd25611', 1, 'My space, your space.', 'feliz', '😊'),
  ('7b08ff59-84c4-6c52-93dc-344ddfd25611', 2, 'Everyone has their own personal space bubble. It''s like having an invisible shield around us that keeps us feeling safe and comfortable. When someone comes too close into our personal space, it can make us feel uneasy or anxious.', 'espacio personal', '↔️'),
  ('7b08ff59-84c4-6c52-93dc-344ddfd25611', 3, 'Just like we have our own personal space, others have theirs too. We need to respect other people''s personal space by not standing too close or touching them without permission. If we''re unsure, we can always ask if it''s okay to give a hug or high-five.', 'espacio personal', '↔️'),
  ('7b08ff59-84c4-6c52-93dc-344ddfd25611', 4, 'If someone is in our personal space and it makes us uncomfortable, we can politely say, "Please step back" or "I need some space." It''s important to communicate our boundaries in a kind and clear way.', 'espacio personal', '↔️'),
  ('7b08ff59-84c4-6c52-93dc-344ddfd25611', 5, 'Respecting personal space helps everyone feel comfortable and safe. Remember, my space, your space.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('10d6d8e2-0efa-9a23-4938-eb0b46974080', 1, 'Sometimes, I feel overwhelmed or upset. When this happens, it''s important to have a safe place where I can go to calm down and feel better. My safe place is a special spot that helps me relax and find peace.', 'respirar', '🫁'),
  ('10d6d8e2-0efa-9a23-4938-eb0b46974080', 2, 'My safe place can be anywhere that makes me feel comfortable and secure. It could be my bedroom, a cozy corner with pillows and blankets, or even outside in nature. In my safe place, I can take deep breaths and let go of any negative feelings.', 'respirar', '🫁'),
  ('10d6d8e2-0efa-9a23-4938-eb0b46974080', 3, 'When I''m feeling stressed or anxious, I can go to my safe place and do things that help me feel better. I might listen to calming music, read a favorite book, or cuddle with a soft toy. Sometimes, just being alone in my safe place is enough to make me feel calm and peaceful.', 'escuchar', '👂'),
  ('10d6d8e2-0efa-9a23-4938-eb0b46974080', 4, 'It''s important to remember that everyone''s safe place is different. What works for me may not work for someone else. That''s okay! The most important thing is finding a safe place that makes me feel good and helps me manage my emotions.', 'importante', '❗'),
  ('10d6d8e2-0efa-9a23-4938-eb0b46974080', 5, 'Having a safe place is like having a superpower. It gives me the ability to take control of my emotions and find peace when I need it most. I will always have my safe place to turn to whenever I feel overwhelmed or upset.', 'seguro', '🛡️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('92e5bd4d-b07a-fbcc-f03f-37b3b9801b12', 1, 'Celebrating diversity means recognizing and appreciating how we are all unique in our own special ways.', 'todo', '🌐'),
  ('92e5bd4d-b07a-fbcc-f03f-37b3b9801b12', 2, 'Some people speak different languages, eat different foods, or wear different clothes. These differences make the world interesting and colorful.', 'algunos', '✨'),
  ('92e5bd4d-b07a-fbcc-f03f-37b3b9801b12', 3, 'It''s important to treat everyone with kindness and respect, no matter how they may be different from us. We can learn so much from each other!', 'importante', '❗'),
  ('92e5bd4d-b07a-fbcc-f03f-37b3b9801b12', 4, 'When we celebrate diversity together, we create a world where everyone feels valued and included. Let''s embrace our differences and make the world a better place for all of us.', 'celebrar', '🎊');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('95fde0ab-94fb-4dca-efb2-0eee494f75e3', 1, 'I am learning to floss my teeth every day. Flossing is an important part of keeping my teeth healthy and strong.', 'aprender', '📖'),
  ('95fde0ab-94fb-4dca-efb2-0eee494f75e3', 2, 'Flossing helps to remove food and plaque from between my teeth, where my toothbrush can''t reach. Plaque is a sticky film that has germs in it, and if I don''t remove it, it can cause cavities and gum disease. By flossing every day, I am helping to keep my teeth clean and prevent problems with my gums and teeth.', 'cepillarse', '🪥'),
  ('95fde0ab-94fb-4dca-efb2-0eee494f75e3', 3, 'When I floss, I take a piece of dental floss and gently guide it between each of my teeth. Then, I move the floss up and down against the side of each tooth to remove any food or plaque. It''s important to be gentle so that I don''t hurt my gums.', 'dientes', '🦷'),
  ('95fde0ab-94fb-4dca-efb2-0eee494f75e3', 4, 'By flossing every day, I am taking care of my teeth and making sure they stay healthy. My dentist will be proud of me for doing such a good job at keeping my teeth clean.', 'dia', '☀️'),
  ('95fde0ab-94fb-4dca-efb2-0eee494f75e3', 5, 'Learning to floss daily is an important step in taking care of my teeth. By flossing every day, I am helping to keep my teeth and gums healthy. I will feel proud of myself for taking good care of my teeth, and my dentist will be happy to see how well I am looking after them.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f1d784b3-0d7c-de1d-56d1-820c52d48f01', 1, 'Celebrating in our own way is special and fun. It''s a time to share joy and create happy memories with the people we care about.', 'propio', '✨'),
  ('f1d784b3-0d7c-de1d-56d1-820c52d48f01', 2, 'Sometimes, celebrations may look different for each person. For example, some people like big parties with lots of decorations and music. Others prefer quiet gatherings with just a few close friends or family members. There are also those who enjoy celebrating by doing something they love, like going for a nature walk or watching their favorite movie.', 'a veces', '⏳'),
  ('f1d784b3-0d7c-de1d-56d1-820c52d48f01', 3, 'No matter how we choose to celebrate, what matters most is that we feel happy and connected during these special moments. We can express our feelings through laughter, hugs, or even a simple smile. Each celebration is a chance to show appreciation for the people around us and the good times we share together.', 'elegir', '✅'),
  ('f1d784b3-0d7c-de1d-56d1-820c52d48f01', 4, 'Celebrating in our own way allows us to express ourselves uniquely and authentically. Whether it''s a birthday, holiday, or any other occasion, let''s remember that the best celebrations are the ones where we feel loved, valued, and truly ourselves. Let''s embrace our individuality and make every moment special in our own way. Celebrating in our own way brings happiness and warmth to our hearts.', 'propio', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('96f97afe-6e51-02ff-6a94-666595b6fb33', 1, 'Celebrating happiness is about recognizing joyful moments. It''s important to notice when we feel happy and understand what makes us feel that way.', 'alegria', '🎉'),
  ('96f97afe-6e51-02ff-6a94-666595b6fb33', 2, 'When something makes me smile or laugh, it means I am feeling happy. Maybe it''s playing with my favorite toy, spending time with a friend, or doing something fun. When I feel happy, my body feels light and my heart feels warm. I might even want to dance or sing because I''m so happy!', 'sentimiento', '💗'),
  ('96f97afe-6e51-02ff-6a94-666595b6fb33', 3, 'It''s also important to notice when others are happy. I can tell if someone else is happy by looking at their face. Their eyes might sparkle, and they might have a big smile. If I see someone else feeling happy, I can share in their joy by smiling back or saying kind words.', 'importante', '❗'),
  ('96f97afe-6e51-02ff-6a94-666595b6fb33', 4, 'Recognizing joyful moments helps me appreciate the good things in life. I will try to notice when I feel happy and remember what made me feel that way. I can also celebrate happiness by sharing in other people''s joy and spreading kindness.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f1358c23-d495-bfa8-37a8-ec0eeda69707', 1, 'Using the bathroom independently is an important skill. It means I can take care of my own needs and feel proud of myself.', 'bano', '🚽'),
  ('f1358c23-d495-bfa8-37a8-ec0eeda69707', 2, 'When I need to use the bathroom, I can go by myself. First, I pull down my pants and sit on the toilet. Then, I wipe myself and flush the toilet. After that, I wash my hands with soap and water. If I need help, I can ask an adult nearby.', 'lavarse', '🧼'),
  ('f1358c23-d495-bfa8-37a8-ec0eeda69707', 3, 'Sometimes accidents happen, but it''s okay. I can clean up the mess and try again next time. Practice makes perfect!', 'a veces', '⏳'),
  ('f1358c23-d495-bfa8-37a8-ec0eeda69707', 4, 'Using the bathroom independently helps me feel confident and grown-up. It shows that I am responsible for taking care of myself.', 'bano', '🚽'),
  ('f1358c23-d495-bfa8-37a8-ec0eeda69707', 5, 'Using the bathroom independently is a big step towards growing up. I will keep practicing and getting better at it each day.', 'bano', '🚽');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6b2342b8-de36-1690-cc79-401c9b2c9f5e', 1, 'Using technology can be a lot of fun! It can also help me with my homework and learning new things.', 'divertido', '😄'),
  ('6b2342b8-de36-1690-cc79-401c9b2c9f5e', 2, 'When I use technology for homework, it''s important to stay focused and not get distracted by games or videos. I can set a timer to remind myself to take breaks and stretch my legs.', 'deberes', '📋'),
  ('6b2342b8-de36-1690-cc79-401c9b2c9f5e', 3, 'I should always ask an adult before downloading any apps or visiting new websites. They can make sure it''s safe and appropriate for me.', 'deber', '📋'),
  ('6b2342b8-de36-1690-cc79-401c9b2c9f5e', 4, 'If someone sends me a message or wants to chat online, I need to remember to be kind and respectful. I shouldn''t share personal information like my address or phone number with anyone online.', 'alguien', '✨'),
  ('6b2342b8-de36-1690-cc79-401c9b2c9f5e', 5, 'It''s also important to remember that not everything I see online is true. Sometimes people pretend to be someone they''re not. If something doesn''t seem right, I can talk to a trusted adult about it.', 'importante', '❗'),
  ('6b2342b8-de36-1690-cc79-401c9b2c9f5e', 6, 'Using technology can be a great tool for learning and having fun. By being responsible and following these guidelines, I can enjoy all the benefits while staying safe online.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('adc684e0-5c46-f5c1-fccb-ac044b16ce3a', 1, 'Being a good audience member is important when we are in public places like parks, restaurants, and libraries. It helps us show respect to others.', 'bien', '👍'),
  ('adc684e0-5c46-f5c1-fccb-ac044b16ce3a', 2, 'When we are at the park watching a play or performance, it''s important to sit quietly and listen. We can clap our hands after the performance to show that we enjoyed it.', 'parque', '🌳'),
  ('adc684e0-5c46-f5c1-fccb-ac044b16ce3a', 3, 'In a restaurant, when someone is speaking or performing music, we should pay attention and try to keep quiet so others can enjoy too. We can smile and nod if we like what we hear.', 'atencion', '📢'),
  ('adc684e0-5c46-f5c1-fccb-ac044b16ce3a', 4, 'At the library during storytime, we need to sit nicely and listen to the storyteller. We can raise our hand if we want to ask a question or share something.', 'escuchar', '👂'),
  ('adc684e0-5c46-f5c1-fccb-ac044b16ce3a', 5, 'Being a good audience member means being respectful and attentive when others are sharing something with us. I will try my best to be a good audience member in different places and show respect to those around me.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c4d0134f-293f-6159-fd61-2d4fc3238a9c', 1, 'Hi, my name is Ethan. I go to school every day and sometimes things can get a little overwhelming for me. But guess what? My teacher, Mrs. Johnson, has created a special place called the quiet corner just for moments like these.', 'saludar', '👋'),
  ('c4d0134f-293f-6159-fd61-2d4fc3238a9c', 2, 'The quiet corner is a cozy spot in our classroom where I can go when I need some calm time. It''s filled with soft pillows, a comfy chair, and even some calming sensory toys. When I feel overwhelmed or upset, I can ask Mrs. Johnson if I can take a break in the quiet corner.', 'silencio', '🔇'),
  ('c4d0134f-293f-6159-fd61-2d4fc3238a9c', 3, 'Sometimes, I might feel frustrated because I''m having trouble understanding something or maybe I didn''t do as well on a task as I wanted to. That''s okay! The quiet corner is there to help me relax and gather my thoughts. Taking a few deep breaths and spending some time in the quiet corner helps me feel better and ready to try again.', 'respirar', '🫁'),
  ('c4d0134f-293f-6159-fd61-2d4fc3238a9c', 4, 'Mrs. Johnson understands that everyone needs different amounts of quiet time, so she lets me decide how long I want to stay in the quiet corner. Some days, I only need a few minutes, while other times I might need a bit longer. And guess what? That''s perfectly fine!', 'todos', '🌐'),
  ('c4d0134f-293f-6159-fd61-2d4fc3238a9c', 5, 'Having the quiet corner in our classroom makes me feel safe and supported. It reminds me that it''s okay to take breaks and recharge when I need to. So, whenever I feel overwhelmed or upset, I will remember to ask Mrs. Johnson if I can spend some time in the quiet corner. It''s a special place just for me, and it helps me feel calm and ready to tackle whatever comes my way at school.', 'silencio', '🔇');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2e86bbaf-97b5-2465-81d3-6c00cb619a27', 1, 'Sometimes, I feel frustrated or angry. Frustration and anger are strong emotions that everyone feels sometimes. It’s important to know how to manage these feelings in a safe and healthy way.', 'a veces', '⏳'),
  ('2e86bbaf-97b5-2465-81d3-6c00cb619a27', 2, 'When I start feeling frustrated or angry, it can be helpful to take deep breaths. Deep breaths help me calm down and think more clearly. I can also try counting to ten or taking a break from the situation. This gives me time to cool down and find a solution.', 'respirar', '🫁'),
  ('2e86bbaf-97b5-2465-81d3-6c00cb619a27', 3, 'It’s okay to feel frustrated or angry, but it’s not okay to hurt myself or others. Instead of hitting or yelling, I can use my words to express how I feel. I can say, “I am feeling frustrated right now” or “I need some space.”', 'sentir', '💓'),
  ('2e86bbaf-97b5-2465-81d3-6c00cb619a27', 4, 'If I need help managing my frustration or anger, I can talk to a trusted adult. They can give me guidance and support. They may have strategies that can help me cope with these emotions.', 'necesitar', '❗'),
  ('2e86bbaf-97b5-2465-81d3-6c00cb619a27', 5, 'Everyone gets frustrated or angry sometimes. It’s a normal part of life. By using calming techniques and expressing our feelings in a safe way, we can learn to manage our frustration and anger in a positive way.', 'todos', '🌐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fabffda8-e6f6-4541-b808-fdc1b629105d', 1, 'Sometimes in life, we have to say goodbye. Saying goodbye means that we won''t see someone for a while or maybe ever again. It can be sad and hard, but it''s a part of life.', 'despedirse', '👋'),
  ('fabffda8-e6f6-4541-b808-fdc1b629105d', 2, 'When we say goodbye to old friends, it might feel like our heart is heavy. We may miss them and the fun times we had together. It''s okay to feel sad about saying goodbye. Remembering the good memories we shared can help us feel better.', 'despedirse', '👋'),
  ('fabffda8-e6f6-4541-b808-fdc1b629105d', 3, 'It''s important to know that even though we are saying goodbye, we can still keep in touch with our old friends. We can call them, send them messages, or even plan to meet again in the future. Just because they are far away doesn''t mean we have to forget about them.', 'importante', '❗'),
  ('fabffda8-e6f6-4541-b808-fdc1b629105d', 4, 'Saying goodbye can also bring new opportunities to make new friends. We can open our hearts to new people and create new memories with them. Each person we meet adds something special to our lives.', 'despedirse', '👋'),
  ('fabffda8-e6f6-4541-b808-fdc1b629105d', 5, 'Saying goodbye is a way of showing love and appreciation for the time we spent together. It''s a chance to cherish the moments we had and look forward to new experiences ahead. I will remember my old friends fondly and welcome new friendships with an open heart.', 'despedirse', '👋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8f87a616-be80-cdf6-0b58-ebd363c8c974', 1, 'Sometimes, I see something that I really want. It might be a toy in the store or a treat at home. But sometimes, I can''t have it right away.', 'a veces', '⏳'),
  ('8f87a616-be80-cdf6-0b58-ebd363c8c974', 2, 'When I can''t have something, I feel disappointed. That''s okay. It''s normal to feel that way. I can take deep breaths and tell myself that it''s okay to wait for things. Waiting is part of life.', 'respirar', '🫁'),
  ('8f87a616-be80-cdf6-0b58-ebd363c8c974', 3, 'I can also talk to an adult about how I''m feeling. They can help me understand why I need to wait and find ways to make waiting easier. Maybe we can come up with a plan together to earn what I want or find something else fun to do while I wait.', 'hablar', '🗣️'),
  ('8f87a616-be80-cdf6-0b58-ebd363c8c974', 4, 'It''s hard when I can''t have something right away, but I can cope with my feelings by taking deep breaths, talking to an adult, and finding other fun things to do while I wait.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 1, 'Staying hydrated is important for our bodies. Water helps us stay healthy and strong.', 'importante', '❗'),
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 2, 'Water is a special drink that we need every day. It doesn''t have any sugar or colors in it, just like juice or soda does. When we drink water, it helps our bodies work well.', 'agua', '💧'),
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 3, 'Our bodies are made up of lots of water. Just like plants need water to grow, our bodies need water to keep working properly. Water helps our muscles move, our brains think, and our skin stay nice and soft.', 'agua', '💧'),
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 4, 'When we play outside or run around, we can get thirsty. That''s our body telling us it needs more water. We should listen to our bodies and drink some water to feel better.', 'escuchar', '👂'),
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 5, 'Sometimes, when we eat food, our bodies also need water to help digest the food. Drinking water with meals can make eating easier and healthier.', 'a veces', '⏳'),
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 6, 'We can drink water from a cup, a bottle, or even a straw. Some people like their water cold with ice, while others prefer it at room temperature. It''s okay to choose how we like to drink our water!', 'beber', '🥤'),
  ('1a10ca0a-0d0f-902f-1d5f-a4156442dbb4', 7, 'Drinking water is good for me. I will try to drink water every day to keep my body happy and healthy.', 'agua', '💧');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('93381500-1e14-263f-5164-2c35284a3d3a', 1, 'Embracing our unique talents and passions', 'feliz', '😊'),
  ('93381500-1e14-263f-5164-2c35284a3d3a', 2, 'Everyone has something special that they enjoy doing. It could be drawing, playing sports, singing, or collecting things. These are called hobbies and interests. They make us unique and interesting.', 'todos', '🌐'),
  ('93381500-1e14-263f-5164-2c35284a3d3a', 3, 'When we share our hobbies with others, it helps them understand us better. We can also learn about new things from each other. Sharing our talents and passions can create connections and friendships.', 'compartir', '🤲'),
  ('93381500-1e14-263f-5164-2c35284a3d3a', 4, 'Sometimes, people may not have the same hobbies as us, and that''s okay. It''s important to respect each other''s interests even if they are different from ours. We can still find common ground and appreciate each other''s uniqueness.', 'a veces', '⏳'),
  ('93381500-1e14-263f-5164-2c35284a3d3a', 5, 'Exploring our hobbies and interests is a way to express ourselves and connect with others who share similar passions. It''s like finding a piece of a puzzle that fits perfectly with someone else''s piece.', 'forma', '📐'),
  ('93381500-1e14-263f-5164-2c35284a3d3a', 6, 'Embracing our unique talents and passions is a wonderful journey. By sharing what makes us happy and connecting with others through our hobbies, we can build meaningful relationships and celebrate the diversity of interests around us.', 'compartir', '🤲');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0c96767c-0464-bc0d-d5ec-f3d6adbd08ed', 1, 'Our friends have many different experiences. Sometimes, they feel happy, and sometimes, they feel sad or worried. We can learn a lot by listening to their stories.', 'amigos', '🤝'),
  ('0c96767c-0464-bc0d-d5ec-f3d6adbd08ed', 2, 'When we listen to our friends, we can understand how they are feeling. We can ask questions to show that we care about them. When we do this, we are being good friends.', 'escuchar', '👂'),
  ('0c96767c-0464-bc0d-d5ec-f3d6adbd08ed', 3, 'Sometimes, our friends may tell us about something that made them feel upset. It''s important for us to listen and try to understand why they feel that way. We can offer support and comfort to our friends when they need it.', 'a veces', '⏳'),
  ('0c96767c-0464-bc0d-d5ec-f3d6adbd08ed', 4, 'We can also share our own experiences with our friends. This helps us build stronger friendships and creates a bond of understanding between us.', 'compartir', '🤲'),
  ('0c96767c-0464-bc0d-d5ec-f3d6adbd08ed', 5, 'By learning from our friends'' experiences, we become better friends and develop empathy. Listening and understanding each other''s feelings is an important part of being a good friend.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a1345622-a574-516d-237f-7ce8bebd9b72', 1, 'Why can I only touch some things? Personal space is important. It''s like having an invisible bubble around us that keeps us feeling comfortable and safe.', 'espacio personal', '↔️'),
  ('a1345622-a574-516d-237f-7ce8bebd9b72', 2, 'When we respect personal space, we show others that we care about their feelings. Imagine if someone was standing too close to me all the time or touching my things without asking. That might make me feel uncomfortable, right?', 'espacio personal', '↔️'),
  ('a1345622-a574-516d-237f-7ce8bebd9b72', 3, 'Just like how we have our own personal space, other people have theirs too. We need to ask before touching someone else''s belongings or getting too close to them. This shows that we are being respectful and considerate of their boundaries.', 'espacio personal', '↔️'),
  ('a1345622-a574-516d-237f-7ce8bebd9b72', 4, 'If we accidentally invade someone''s personal space, it''s okay to apologize and give them some space. Everyone makes mistakes, but learning from them helps us grow and become better at respecting personal boundaries.', 'espacio personal', '↔️'),
  ('a1345622-a574-516d-237f-7ce8bebd9b72', 5, 'Why can I only touch some things? Respecting personal space is important for everyone. By understanding and honoring each other''s boundaries, we create a harmonious environment where everyone feels valued and respected.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1844b9a0-1751-62a9-54a7-6113801ad40f', 1, 'Supporting each other''s goals and dreams is an important part of being a family. We all have things we want to achieve, and it feels good when our family members cheer us on.', 'otro', '🔄'),
  ('1844b9a0-1751-62a9-54a7-6113801ad40f', 2, 'In our family, we all have different dreams and goals. Mom wants to finish her painting, Dad wants to run a marathon, and I want to learn how to ride my bike without training wheels.', 'familia', '👨‍👩‍👧‍👦'),
  ('1844b9a0-1751-62a9-54a7-6113801ad40f', 3, 'When Mom works on her painting, she likes it when we watch and ask questions about her art. Dad practices running every day, and we can help by giving him high-fives and cheering for him. When I practice riding my bike, I feel happy when they encourage me and celebrate my progress.', 'montar', '✨'),
  ('1844b9a0-1751-62a9-54a7-6113801ad40f', 4, 'Sometimes, we might need help or support to reach our goals. It''s okay to ask for help from each other. Mom helps Dad stretch after his runs, Dad holds the bike steady while I pedal, and I help Mom clean her brushes after painting.', 'ayuda', '🆘'),
  ('1844b9a0-1751-62a9-54a7-6113801ad40f', 5, 'By supporting each other''s goals and dreams, we show love, respect, and cooperation in our family.', 'otro', '🔄'),
  ('1844b9a0-1751-62a9-54a7-6113801ad40f', 6, 'Remember, supporting each other''s goals and dreams makes our family stronger and happier. Let''s continue to cheer each other on as we work towards achieving our dreams together!', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a9af1b7e-3018-6297-e725-70003997cd1f', 1, 'Bedtime is an important part of our day. It''s the time when we get ready to rest and recharge for a new day ahead.', 'vestirse', '👕'),
  ('a9af1b7e-3018-6297-e725-70003997cd1f', 2, 'At bedtime, we follow a routine to help us relax and prepare for sleep. First, we change into our cozy pajamas. Then, we brush our teeth to keep them clean and healthy. Next, we read a story or listen to calming music to help our minds unwind. We can cuddle with a favorite stuffed animal or blanket for comfort. Finally, we turn off the lights and close our eyes, imagining peaceful dreams.', 'escuchar', '👂'),
  ('a9af1b7e-3018-6297-e725-70003997cd1f', 3, 'Sleep is important because it helps our bodies grow and gives us energy for the next day. When we have enough sleep, we feel better and can focus more easily. Sometimes, falling asleep may take some time, but that''s okay. We can try deep breathing or counting sheep to help us relax.', 'respirar', '🫁'),
  ('a9af1b7e-3018-6297-e725-70003997cd1f', 4, 'It''s also important to have a consistent bedtime routine. This means doing the same things in the same order every night. Our bodies like routines because they know what to expect. When we stick to our bedtime routine, it signals to our brain that it''s time to wind down and get ready for sleep.', 'vestirse', '👕'),
  ('a9af1b7e-3018-6297-e725-70003997cd1f', 5, 'Bedtime is a special time to take care of ourselves and end the day right. By following our bedtime routine, we can have a good night''s sleep and wake up feeling refreshed and ready for a brand new day.', 'dormir', '🌙');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('21d2df8e-3aa4-79e2-d167-5c65b251d7a2', 1, 'On weekdays, I have a routine. I wake up, eat breakfast, go to school, come home, and do my homework. But on weekends, things are different.', 'rutina', '🔄'),
  ('21d2df8e-3aa4-79e2-d167-5c65b251d7a2', 2, 'During the weekend, I don''t have to go to school. I can sleep in a little later if I want to. I can play with my toys or watch my favorite shows. Sometimes, we might go out for a special activity like going to the park or visiting family. It''s fun to have some extra time to relax and do things I enjoy.', 'ir', '🚶'),
  ('21d2df8e-3aa4-79e2-d167-5c65b251d7a2', 3, 'Weekends are different from weekdays. I can use this time to have fun and do things that make me happy.', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('961bcae0-3e9c-70e7-5f24-6218405b5d69', 1, 'Telling people how I feel is important. It helps me to share my emotions with others and allows them to understand me better.', 'personas', '👥'),
  ('961bcae0-3e9c-70e7-5f24-6218405b5d69', 2, 'When I am happy, I can tell someone by smiling or laughing. If I am excited, I might jump up and down or clap my hands. When I am sad, I may have tears in my eyes or want a hug. Sometimes, I might feel angry, and it''s okay to say that I need some space or time alone.', 'feliz', '😊'),
  ('961bcae0-3e9c-70e7-5f24-6218405b5d69', 3, 'It''s important for me to use words to express my feelings too. I can say, "I''m happy," "I''m sad," "I''m scared," or "I''m mad." This way, the people around me will know what I am feeling and can help me if I need it.', 'importante', '❗'),
  ('961bcae0-3e9c-70e7-5f24-6218405b5d69', 4, 'If I don''t feel like talking, I can also use pictures or drawings to show how I feel. This can be helpful when words are hard to find.', 'sentir', '💓'),
  ('961bcae0-3e9c-70e7-5f24-6218405b5d69', 5, 'Telling people how I feel is a good way to communicate. Whether I use words, actions, or pictures, expressing my feelings helps me and the people around me to understand each other better.', 'personas', '👥');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7efab555-706c-d1ea-4672-9e51ad2e8bb0', 1, 'Protecting my personal information is important when I use the computer or other devices.', 'importante', '❗'),
  ('7efab555-706c-d1ea-4672-9e51ad2e8bb0', 2, 'I should never share my full name, address, phone number, or any other personal information with people online unless my mom or dad says it''s okay. It''s like keeping a secret that only trusted adults can know. If someone asks for my personal information, I will tell my mom or dad right away.', 'deber', '📋'),
  ('7efab555-706c-d1ea-4672-9e51ad2e8bb0', 3, 'When I play games or use apps, I will always ask my mom or dad before downloading anything. Some things on the internet are not safe for me to see or do, so it''s important to have their help and permission.', 'jugar', '🎮'),
  ('7efab555-706c-d1ea-4672-9e51ad2e8bb0', 4, 'Protecting my personal information helps keep me safe while using technology. I will always talk to my mom or dad if I''m not sure about something online.', 'seguro', '🛡️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 1, 'This is my story about using social media. Social media are websites and applications that allow people to create and share content or to participate in social networking. I am learning how to use social media safely.', 'personas', '👥'),
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 2, 'I will remember to always ask an adult before using social media. They can help me understand what is safe and appropriate.', 'recordar', '📝'),
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 3, 'When I see something on social media that makes me feel uncomfortable, I will tell a trusted adult right away. It''s important to talk about things that bother me.', 'ver', '👀'),
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 4, 'I will never share personal information like my address, phone number, or school name on social media. This keeps me safe from strangers who might try to contact me.', 'nunca', '🚫'),
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 5, 'If someone is mean to me on social media, I will not respond. I will block them and tell a trusted adult about it. It''s okay to ignore unkind messages.', 'alguien', '✨'),
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 6, 'It''s fun to connect with friends and family on social media. I can share positive things and support others by being kind and respectful online.', 'divertido', '😄'),
  ('8cccaa2b-115e-b1ac-59df-c7e6db48a911', 7, 'Using social media can be enjoyable when done safely and responsibly. I will always ask for help if I''m unsure about anything. Staying safe and respectful online is important!', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6d6bc954-85eb-f2bd-6ff9-e55412ba4d03', 1, 'Saying sorry is a way to show that I understand when someone feels upset or hurt. It''s important to know how to say sorry and mean it.', 'perdon', '😔'),
  ('6d6bc954-85eb-f2bd-6ff9-e55412ba4d03', 2, 'Sometimes, I might do something that upsets someone else without meaning to. Maybe I accidentally bump into them, or I forget to share a toy. When this happens, the other person might feel sad or angry. It''s okay for people to have those feelings, and it''s important for me to recognize that my actions caused those feelings.', 'a veces', '⏳'),
  ('6d6bc954-85eb-f2bd-6ff9-e55412ba4d03', 3, 'When I realize that I''ve upset someone, I can say sorry. Saying sorry means using kind words to let the person know that I understand their feelings and that I didn''t mean to upset them. I can say, "I''m sorry," or "I apologize," in a calm and gentle voice.', 'alguien', '✨'),
  ('6d6bc954-85eb-f2bd-6ff9-e55412ba4d03', 4, 'It''s also important to think about what I can do to make things better. If I accidentally broke something of theirs, I can offer to help fix it or replace it. If I forgot to share a toy, I can invite them to play with me next time. This shows that I care about their feelings and want to make things right.', 'importante', '❗'),
  ('6d6bc954-85eb-f2bd-6ff9-e55412ba4d03', 5, 'Saying sorry and meaning it helps me show empathy and kindness towards others. It''s a way to repair mistakes and strengthen relationships.', 'perdon', '😔');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9f986ceb-a6b7-59e0-4878-1246a2973957', 1, 'Once upon a time, in the heart of a lush forest, there was a group of friends who embarked on an exciting adventure together. They were all different animals but shared a common goal: to explore the wonders of their magical home.', 'tiempo', '⏰'),
  ('9f986ceb-a6b7-59e0-4878-1246a2973957', 2, 'The friends gathered under the towering trees, each bringing their unique skills and strengths to the expedition. The wise owl led the way with her keen eyesight, guiding the group through the dense foliage. The energetic squirrel scurried ahead, scouting for delicious nuts and berries to share. The gentle deer walked gracefully, alerting the others to any signs of danger with her sensitive ears.', 'amigos', '🤝'),
  ('9f986ceb-a6b7-59e0-4878-1246a2973957', 3, 'As they journeyed deeper into the forest, they encountered challenges that required teamwork to overcome. When a fallen tree blocked their path, the strong bear used his mighty strength to move it aside while the clever fox found a hidden trail around. Together, they supported and encouraged each other, knowing that by working as a team, they could achieve anything.', 'arbol', '🌳'),
  ('9f986ceb-a6b7-59e0-4878-1246a2973957', 4, 'Through cooperation and understanding, the friends successfully reached a magnificent waterfall hidden deep within the forest. They marveled at its beauty, feeling proud of what they had accomplished together. Each member of the group played a vital role, showing respect for one another''s abilities and contributions.', 'amigos', '🤝'),
  ('9f986ceb-a6b7-59e0-4878-1246a2973957', 5, 'In the end, the fantastic forest expedition taught the friends the power of teamwork. By collaborating, respecting each other''s differences, and combining their strengths, they discovered that they could conquer any challenge that came their way. Just like the diverse animals in the forest, we too can achieve great things when we work together as a team.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('cd87c6ae-0bd3-9bab-f44c-8a452c9d0509', 1, 'Making friends is like tying knots together. It takes time and effort, but it creates something beautiful.', 'amigos', '🤝'),
  ('cd87c6ae-0bd3-9bab-f44c-8a452c9d0509', 2, 'When I want to make a friend, I can start by showing kindness. Kindness is like the first knot in a friendship bracelet. It holds everything together. I can smile, say hello, or offer help when someone needs it. These small acts of kindness show that I care.', 'querer', '💕'),
  ('cd87c6ae-0bd3-9bab-f44c-8a452c9d0509', 3, 'Next, I can listen and ask questions. Listening is like adding colorful beads to the friendship bracelet. It adds depth and meaning. When I listen, I show that I value what my friend has to say. Asking questions helps me learn more about them and shows that I am interested in their thoughts and feelings.', 'escuchar', '👂'),
  ('cd87c6ae-0bd3-9bab-f44c-8a452c9d0509', 4, 'Sometimes, conflicts may arise in friendships. It''s important to handle these conflicts with respect and understanding. Resolving conflicts is like untangling a knot in the friendship bracelet. I can use calm words to express how I feel and listen to my friend''s perspective. Together, we can find a solution that works for both of us.', 'escuchar', '👂'),
  ('cd87c6ae-0bd3-9bab-f44c-8a452c9d0509', 5, 'Friendship bracelets are made up of many knots, just like friendships are built on many moments of kindness, listening, and resolving conflicts. By practicing these skills, I can create strong and beautiful friendships that last.', 'amistad', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 1, 'Mindful eating means paying attention to the food we eat and how it tastes. It''s important to be present during mealtime.', 'comer', '🍽️'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 2, 'When I sit down to eat, I can look at my plate and see all the different colors of food. Each color represents different nutrients that are good for my body.', 'sentarse', '🪑'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 3, 'I can smell the food on my plate. The aroma tells me what flavors to expect when I take a bite.', 'comida', '🍽️'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 4, 'When I take a bite, I can chew slowly and feel the texture of the food in my mouth. This helps me enjoy the taste more.', 'sentir', '💓'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 5, 'Sometimes, I may not like a certain food, and that''s okay. I can politely say, "No thank you" or "I''ll try it next time."', 'gracias', '🙏'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 6, 'It''s important to listen to my body and stop eating when I''m full. I can save the rest for later if I want.', 'escuchar', '👂'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 7, 'Mealtime is also a chance to talk with my family or friends. We can share stories and enjoy each other''s company while we eat.', 'hablar', '🗣️'),
  ('ea458ad6-c6cd-1526-5ffb-523bd4bb92e0', 8, 'Mindful eating moments help me appreciate the food I have and enjoy mealtime with others. I will try to pay attention to my food, savor each bite, and listen to my body''s signals during meals.', 'atencion', '📢');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e827487a-08a9-5232-272d-38d6c3d066f3', 1, 'I am learning about using technology and being safe online. Sometimes, people may say unkind things or try to hurt others on the internet. This is called cyberbullying. It''s important to know how to deal with cyberbullying if it happens.', 'aprender', '📖'),
  ('e827487a-08a9-5232-272d-38d6c3d066f3', 2, 'Cyberbullying can happen through mean messages, spreading rumors, or posting hurtful comments online. If someone says something unkind to me online, I will tell a trusted adult right away. They can help me handle the situation in the best way.', 'alguien', '✨'),
  ('e827487a-08a9-5232-272d-38d6c3d066f3', 3, 'It''s also important not to respond to the person who is cyberbullying. Responding may make the situation worse. Instead, I can block or unfriend them, so they can''t contact me anymore. I can also save evidence of the cyberbullying, like screenshots, to show to an adult.', 'importante', '❗'),
  ('e827487a-08a9-5232-272d-38d6c3d066f3', 4, 'If I experience cyberbullying, I will remember that it''s not my fault and that I deserve to be treated with kindness and respect. I will seek help from a trusted adult and take steps to protect myself online.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5f351a7e-f809-120e-bbab-7f62efb09032', 1, 'Being an ally means being a friend who stands up for others when they need help. It''s like having a superhero power to make things better for someone else.', 'amigo', '🤝'),
  ('5f351a7e-f809-120e-bbab-7f62efb09032', 2, 'When I see someone being bullied, I can be an ally by speaking up and telling an adult. I can say, "Stop it! That''s not nice!" or "Leave them alone!"', 'ver', '👀'),
  ('5f351a7e-f809-120e-bbab-7f62efb09032', 3, 'I can also support the person being bullied by being kind to them. I can sit with them at lunch, play with them at recess, or simply ask how they are doing.', 'persona', '🧑'),
  ('5f351a7e-f809-120e-bbab-7f62efb09032', 4, 'If I feel scared or unsure about what to do, I can always find a teacher, parent, or another grown-up to help. They will know what to do to keep everyone safe.', 'sentir', '💓'),
  ('5f351a7e-f809-120e-bbab-7f62efb09032', 5, 'Being an ally is important because it shows that I care about others and want to make sure everyone feels happy and safe.', 'importante', '❗'),
  ('5f351a7e-f809-120e-bbab-7f62efb09032', 6, 'Being an ally means standing up for friends and classmates. I will try my best to be an ally and support others facing bullying.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7f809caa-39e9-a043-544d-c38929417bcf', 1, 'Disappointment can feel like a storm inside me.', 'sentir', '💓'),
  ('7f809caa-39e9-a043-544d-c38929417bcf', 2, 'Disappointment happens when things don’t go the way I hoped or expected. It’s like planning to play outside, but then it rains. Disappointment can make my heart heavy and my eyes watery. Three things that can lead to disappointment are: ()', 'cosas', '📦'),
  ('7f809caa-39e9-a043-544d-c38929417bcf', 3, 'When I am disappointed, I may want to cry, shout, or hide. These are natural reactions. Taking deep breaths or talking about how I feel can help calm the storm of disappointment. Three ways I can cope with disappointment are: ()', 'respirar', '🫁'),
  ('7f809caa-39e9-a043-544d-c38929417bcf', 4, 'Sometimes, adults may not understand why I’m disappointed. They might say, “It’s okay,” but it doesn’t feel okay to me. It’s important for me to express my feelings in a safe way. Talking about my disappointment can help me feel better. A time when I felt disappointed was: ()', 'a veces', '⏳'),
  ('7f809caa-39e9-a043-544d-c38929417bcf', 5, 'Navigating the storms of disappointment is challenging, but expressing my feelings and finding healthy ways to cope can help calm the storm inside me.', 'sentimientos', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('53d23bfd-a207-f510-f50b-ad65416fad98', 1, 'Change can be hard, but it helps us grow. Feedback is like a guide that shows us the way.', 'cambio', '🔄'),
  ('53d23bfd-a207-f510-f50b-ad65416fad98', 2, 'When someone gives feedback, they are sharing their thoughts to help us improve. It''s like having a map when we''re lost. We may feel unsure or even upset at first, and that''s okay. Remember, mistakes are part of learning.', 'alguien', '✨'),
  ('53d23bfd-a207-f510-f50b-ad65416fad98', 3, 'We can listen carefully to what is said, take a deep breath, and think about how we can use this information to do better next time. Just like a caterpillar transforms into a butterfly, we too can change and become stronger through feedback.', 'respirar', '🫁'),
  ('53d23bfd-a207-f510-f50b-ad65416fad98', 4, 'Embracing change through feedback is a journey we all take. Each step forward brings us closer to our best selves. Let''s embrace feedback as a tool for growth and improvement.', 'cambio', '🔄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f0b7ed8d-1a84-9d06-0fd1-30e67d8f28f0', 1, 'Every morning, I make my bed. Making my bed helps me start the day feeling organized and ready for whatever comes next.', 'manana', '✨'),
  ('f0b7ed8d-1a84-9d06-0fd1-30e67d8f28f0', 2, 'When I wake up, I straighten out my sheets and fluff my pillows. I pull up the covers to make sure everything looks neat and tidy. It only takes a few minutes, but it makes a big difference in how my room looks and feels.', 'feliz', '😊'),
  ('f0b7ed8d-1a84-9d06-0fd1-30e67d8f28f0', 3, 'My mom says that making my bed is like giving myself a fresh start each day. She tells me that when my bed is made, it''s easier to find things in my room and it helps me feel proud of taking care of my space.', 'cama', '🛏️'),
  ('f0b7ed8d-1a84-9d06-0fd1-30e67d8f28f0', 4, 'Sometimes I forget or feel too tired to make my bed, but then I remember how nice it is to come back to a tidy room later in the day. It''s a small task that makes a big impact on how I feel.', 'a veces', '⏳'),
  ('f0b7ed8d-1a84-9d06-0fd1-30e67d8f28f0', 5, 'Making my bed every morning is a simple way to show respect for my space and myself. I will try to make my bed each day to start off on the right foot.', 'cama', '🛏️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('962fe9c1-2b51-acc2-b4d0-ba8923184b4d', 1, 'Starting at a new school can be exciting and a little scary. It’s like starting a new adventure! I get to meet new friends, learn new things, and explore a different place.', 'nuevo', '🆕'),
  ('962fe9c1-2b51-acc2-b4d0-ba8923184b4d', 2, 'When I first went to my new school, I felt nervous. Everything was unfamiliar, and I didn’t know anyone. But then I remembered that everyone feels this way when they start something new. My teacher, Mrs. Thompson, noticed I was feeling unsure. She told me a story about how she moved to a new town when she was young. She said it was hard at first, but she made new friends by smiling and saying hello.', 'nuevo', '🆕'),
  ('962fe9c1-2b51-acc2-b4d0-ba8923184b4d', 3, 'I decided to try what Mrs. Thompson suggested. I smiled at the girl sitting next to me in class and said hi. Her name is Lily, and she smiled back! We started talking about our favorite books, and before I knew it, we were friends.', 'intentar', '💪'),
  ('962fe9c1-2b51-acc2-b4d0-ba8923184b4d', 4, 'During lunchtime, I wasn’t sure where to sit. Mrs. Thompson came over and shared another story with me. She said that sometimes it helps to look for someone who seems friendly and ask if I can join them. So, I looked around and saw a group of kids playing tag. I asked if I could play too, and they happily welcomed me into their game.', 'sentarse', '🪑'),
  ('962fe9c1-2b51-acc2-b4d0-ba8923184b4d', 5, 'By the end of the day, I had met several new friends and learned my way around the school. It turned out to be a fun day after all!', 'dia', '☀️'),
  ('962fe9c1-2b51-acc2-b4d0-ba8923184b4d', 6, 'Adjusting to a new environment takes time, but it can lead to wonderful experiences and friendships. I am excited to see what other adventures await me at my new school.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4645f73b-cba3-a869-fdfc-cf83bf3b3425', 1, 'Playing games online can be a lot of fun. There are many different games to choose from, and I can play with people from all over the world.', 'jugar', '🎮'),
  ('4645f73b-cba3-a869-fdfc-cf83bf3b3425', 2, 'When I play games online, it''s important to remember some rules to stay safe. I should never share my personal information, like my name, address, or phone number, with anyone I meet in the game. If someone asks for this information, I should tell an adult right away.', 'jugar', '🎮'),
  ('4645f73b-cba3-a869-fdfc-cf83bf3b3425', 3, 'I should also be careful about who I talk to in the game. Not everyone is nice, so I should only chat with people I know in real life or trust. If someone says something that makes me feel uncomfortable, I can mute them or leave the game.', 'deber', '📋'),
  ('4645f73b-cba3-a869-fdfc-cf83bf3b3425', 4, 'It''s also important to take regular breaks from playing and not spend too much time in front of the screen. This helps me stay healthy and balanced.', 'importante', '❗'),
  ('4645f73b-cba3-a869-fdfc-cf83bf3b3425', 5, 'By following these rules, I can have a great time playing games online while staying safe and having fun.', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5c53f4af-44f3-7736-7d00-a60a8d7d3e9a', 1, 'Feeling happy is a good feeling. It''s like when I see my favorite toy or have a fun day at the park.', 'sentimiento', '💗'),
  ('5c53f4af-44f3-7736-7d00-a60a8d7d3e9a', 2, 'Happy feelings can happen when something nice happens, like getting a hug from someone I love, playing with my favorite toy, or eating my favorite snack. Sometimes, happy feelings come when I think about something that makes me smile, like remembering a fun time with friends or family.', 'feliz', '😊'),
  ('5c53f4af-44f3-7736-7d00-a60a8d7d3e9a', 3, 'When I feel happy, it might show on my face. I might smile, laugh, or jump up and down. My body might feel light and full of energy. I might want to share my happiness with others by giving hugs, high-fives, or telling jokes.', 'sentir', '💓'),
  ('5c53f4af-44f3-7736-7d00-a60a8d7d3e9a', 4, 'Feeling happy is wonderful! When I feel happy, it''s okay to show it. I can share my happiness with others and make them feel happy too.', 'sentimiento', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('268879f0-3436-026f-6be1-6117a4763c14', 1, 'Sometimes, we want to play with someone, but they may not want to play with us. It''s important to understand that everyone has their own preferences and feelings, and it''s okay if someone doesn''t want to play at a certain time.', 'a veces', '⏳'),
  ('268879f0-3436-026f-6be1-6117a4763c14', 2, 'When someone doesn''t want to play, it doesn''t mean they don''t like us or that we did something wrong. They might be busy, tired, or just not in the mood to play. We should respect their decision and give them space.', 'alguien', '✨'),
  ('268879f0-3436-026f-6be1-6117a4763c14', 3, 'If someone says they don''t want to play, we can try to find someone else who does want to play. There are usually many other friends around who would love to join in our games. We can also find something fun to do on our own, like reading a book or playing with toys.', 'alguien', '✨'),
  ('268879f0-3436-026f-6be1-6117a4763c14', 4, 'It''s important to remember that friendships are built on mutual respect and understanding. Just like how we sometimes don''t feel like playing, others may feel the same way too. It''s okay to have different interests and preferences.', 'importante', '❗'),
  ('268879f0-3436-026f-6be1-6117a4763c14', 5, 'If someone doesn''t want to play, it''s not personal. We should respect their choice and find other ways to have fun. Remember, there are always new opportunities to make friends and enjoy different activities together.', 'alguien', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e28be762-c4e3-3e38-be25-2c415207b480', 1, 'Creating a routine is important. A routine helps me know what to expect and feel more comfortable.', 'rutina', '🔄'),
  ('e28be762-c4e3-3e38-be25-2c415207b480', 2, 'First, I can think about the things I need to do every day, like waking up, eating meals, going to school, doing homework, and going to bed. These are important parts of my day.', 'pensar', '🤔'),
  ('e28be762-c4e3-3e38-be25-2c415207b480', 3, 'Next, I can decide in which order I want to do these things. For example, I might brush my teeth before getting dressed or after breakfast. I can also choose specific times for each activity if that helps me stay on track.', 'cepillarse', '🪥'),
  ('e28be762-c4e3-3e38-be25-2c415207b480', 4, 'I can use pictures or words to make a visual schedule to help me remember my routine. This could be a chart on the wall or a small booklet I carry with me.', 'horario', '📅'),
  ('e28be762-c4e3-3e38-be25-2c415207b480', 5, 'Sometimes, unexpected things happen, and it''s okay to adjust my routine when needed. If something changes, I can ask for help to figure out how to adapt my schedule.', 'ayuda', '🆘'),
  ('e28be762-c4e3-3e38-be25-2c415207b480', 6, 'Creating my own routine will help me feel more organized and prepared for each day. It''s okay to make changes when necessary, and having a routine will make it easier to handle those changes.', 'propio', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('860a32aa-281b-8aab-e199-b8b0d8a2446b', 1, 'Building bridges means fixing things that are broken. When we have an argument with someone, it can feel like our friendship is broken. But just like a bridge connects two places, we can connect back to each other after an argument by using kind words and actions.', 'cosas', '📦'),
  ('860a32aa-281b-8aab-e199-b8b0d8a2446b', 2, 'Sometimes, disagreements happen between friends. It''s normal for people to have different opinions or feelings about things. If I have an argument with my friend, I can take a deep breath and calm down first. Then, I can try to talk calmly about how I feel and listen to what my friend has to say too.', 'respirar', '🫁'),
  ('860a32aa-281b-8aab-e199-b8b0d8a2446b', 3, 'Apologizing is like building the first part of the bridge. Saying sorry shows that I care about my friend''s feelings and want to make things right. It''s important to use gentle words and not blame anyone when apologizing.', 'gustar', '👍'),
  ('860a32aa-281b-8aab-e199-b8b0d8a2446b', 4, 'After saying sorry, I can ask my friend how they feel and if there''s anything we can do to make things better. We can work together to find a solution that makes both of us happy. This way, we build the second part of the bridge towards reconnecting.', 'perdon', '😔'),
  ('860a32aa-281b-8aab-e199-b8b0d8a2446b', 5, 'Just like a bridge brings two sides together, using kind words, listening, and finding solutions can help repair any rifts in our friendships. Building bridges after an argument shows that we value our friends and care about keeping our relationships strong.', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('481b5ab2-ff71-43c1-761b-dfddf6bab9d1', 1, 'Making memories is a special way to celebrate. We can create our own celebrations with the people we love.', 'especial', '⭐'),
  ('481b5ab2-ff71-43c1-761b-dfddf6bab9d1', 2, 'We can plan a celebration for someone''s birthday, like making a card or baking a cake together. We can also have a celebration just because we want to spend time together and make happy memories. It''s important to think about what makes us happy and how we can share that happiness with others. When we celebrate, we are creating special moments that we will remember and cherish.', 'celebracion', '🎊'),
  ('481b5ab2-ff71-43c1-761b-dfddf6bab9d1', 3, 'Creating our own celebrations allows us to make happy memories and share joy with the people we care about.', 'propio', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b8c76e5d-165b-5441-fdec-d925a4149706', 1, 'Coping with change and uncertainty can be challenging. What does it mean to cope with change and uncertainty?', 'cambio', '🔄'),
  ('b8c76e5d-165b-5441-fdec-d925a4149706', 2, 'Change is when things are different from how they were before. Uncertainty is when we don''t know what will happen next. Sometimes, changes can make us feel unsure or worried. It''s okay to feel this way.', 'cambio', '🔄'),
  ('b8c76e5d-165b-5441-fdec-d925a4149706', 3, 'When I face a change, I can take deep breaths to help me calm down. I can talk to someone I trust about my feelings. Change can bring new opportunities and adventures too!', 'respirar', '🫁'),
  ('b8c76e5d-165b-5441-fdec-d925a4149706', 4, 'Uncertainty may make me feel nervous, but I can remind myself that not everything has to be known right away. I can focus on the present moment and try to find joy in small things around me.', 'sentir', '💓'),
  ('b8c76e5d-165b-5441-fdec-d925a4149706', 5, 'Remember, change and uncertainty are a part of life, and I can learn to adapt and grow stronger through them.', 'recordar', '📝'),
  ('b8c76e5d-165b-5441-fdec-d925a4149706', 6, 'Facing change and uncertainty can be tough, but I am capable of handling them. I can take one step at a time and remember that challenges can lead to growth and new experiences.', 'cambio', '🔄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7decb9da-f5dd-adc8-aaae-2d72508129db', 1, 'Change can be scary sometimes. It''s okay to feel unsure when things are different. We all face changes in our lives, and it''s normal to feel a little uneasy about them.', 'cambio', '🔄'),
  ('7decb9da-f5dd-adc8-aaae-2d72508129db', 2, 'When something new happens, like going to a new place or trying a new activity, it might make us feel nervous. That''s because we''re not sure what to expect. But remember, change can also bring exciting opportunities and adventures.', 'nuevo', '🆕'),
  ('7decb9da-f5dd-adc8-aaae-2d72508129db', 3, 'It''s important to remember that even though things may seem unfamiliar at first, we can find comfort in knowing that we have the ability to adapt and learn new things. Just like how we learned to do things we enjoy now, we can learn to enjoy new experiences too.', 'importante', '❗'),
  ('7decb9da-f5dd-adc8-aaae-2d72508129db', 4, 'Finding comfort in the unknown means being open to new possibilities and embracing change as a chance to grow. Even if it feels challenging at first, with time and practice, we can become more confident in facing the unknown. So, let''s take each new experience as an opportunity to discover something wonderful and exciting.', 'abrir', '🔓');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e5be86df-f839-3693-de7a-6a99c1037a66', 1, 'I am learning to communicate with different people. It''s important to understand how to talk and listen to others.', 'escuchar', '👂'),
  ('e5be86df-f839-3693-de7a-6a99c1037a66', 2, 'Sometimes, I need to speak differently when talking to different people. When I talk to my friends, I use friendly words and share things we both like. When I talk to my teacher, I use respectful words and ask questions about what we are learning. If I talk to someone new, I can start by saying hello and introducing myself.', 'a veces', '⏳'),
  ('e5be86df-f839-3693-de7a-6a99c1037a66', 3, 'Listening is also important. When someone talks to me, I look at them and pay attention to their words. This helps me understand what they are saying. If I don''t understand, it''s okay to ask for clarification or help.', 'atencion', '📢'),
  ('e5be86df-f839-3693-de7a-6a99c1037a66', 4, 'Learning to communicate with different people is a valuable skill. By using the right words and listening carefully, I can build positive connections with others.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('bb1a298a-33a6-5065-7c2b-ff2d4cd2acaf', 1, 'Drinking water is important for our bodies. Our bodies need water to stay healthy and strong.', 'agua', '💧'),
  ('bb1a298a-33a6-5065-7c2b-ff2d4cd2acaf', 2, 'Water helps us in many ways. It keeps our bodies hydrated, which means it helps us have enough water inside of us. When we drink water, it goes into our stomachs and then travels all around our bodies through our blood. Water helps our organs work properly and keeps our skin looking good too!', 'agua', '💧'),
  ('bb1a298a-33a6-5065-7c2b-ff2d4cd2acaf', 3, 'When we don''t drink enough water, our bodies can get dehydrated. This means that we don''t have enough water inside of us. Dehydration can make us feel tired, dizzy, or even sick. That''s why it''s important to drink water throughout the day, especially when it''s hot outside or when we''re playing sports or being active.', 'beber', '🥤'),
  ('bb1a298a-33a6-5065-7c2b-ff2d4cd2acaf', 4, 'Remember, drinking water is important for our bodies. Let''s try to drink water every day to keep ourselves healthy and strong.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8a021cdf-c55c-753f-e6f4-156d4651d412', 1, 'The internet is a place where people can share and find information, play games, watch videos, and talk to friends. It''s like a big library and playground all in one.', 'lugar', '📍'),
  ('8a021cdf-c55c-753f-e6f4-156d4651d412', 2, 'When we use the internet, it’s important to remember that what we do or say can stay there forever. Even if we delete something, it might still be saved somewhere else.', 'importante', '❗'),
  ('8a021cdf-c55c-753f-e6f4-156d4651d412', 3, 'We should always be kind and respectful when talking to others online. Just like in real life, our words and actions can affect how others feel.', 'deber', '📋'),
  ('8a021cdf-c55c-753f-e6f4-156d4651d412', 4, 'It’s also important to keep personal information private. We shouldn’t share our full name, address, phone number, or passwords with anyone online unless a parent says it’s okay.', 'importante', '❗'),
  ('8a021cdf-c55c-753f-e6f4-156d4651d412', 5, 'If we see something that makes us uncomfortable or worried while using the internet, we should tell a trusted adult right away.', 'ver', '👀'),
  ('8a021cdf-c55c-753f-e6f4-156d4651d412', 6, 'Remember, the internet is a powerful tool, but we need to use it wisely. Let’s have fun and learn new things while being safe and responsible online.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f930678f-0378-3084-6293-1490f64905e1', 1, 'Transitions are when we move from one activity to another. It’s important to stay calm during transitions, even if they can be a little bit tricky.', 'mover', '🏃'),
  ('f930678f-0378-3084-6293-1490f64905e1', 2, 'When it’s time to stop doing something and start something new, I might feel a little unsure or worried. That’s okay. Lots of kids feel that way sometimes.', 'tiempo', '⏰'),
  ('f930678f-0378-3084-6293-1490f64905e1', 3, 'I can take deep breaths to help me stay calm. I can also think about the fun things I will do next. This helps me feel better about the change.', 'respirar', '🫁'),
  ('f930678f-0378-3084-6293-1490f64905e1', 4, 'If I need help with the transition, I can ask an adult for support. They understand that transitions can be hard for me, and they want to help me feel comfortable.', 'necesitar', '❗'),
  ('f930678f-0378-3084-6293-1490f64905e1', 5, 'Staying calm during transitions is important. It helps me feel more relaxed and ready for what comes next. Taking deep breaths and thinking positively can make transitions easier for me.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b626967d-b32a-dd1c-7cfe-94a9fbf7f9f6', 1, 'Playing games is fun! We can play with friends and have a good time. It''s important to remember that games are not just about winning, but also about having fun together.', 'jugar', '🎮'),
  ('b626967d-b32a-dd1c-7cfe-94a9fbf7f9f6', 2, 'When we play games, sometimes we win and sometimes we lose. Winning feels great because we did our best and things went our way. Losing can be tough because we wanted to win, but it''s okay. Everyone loses sometimes.', 'jugar', '🎮'),
  ('b626967d-b32a-dd1c-7cfe-94a9fbf7f9f6', 3, 'It''s important to celebrate both wins and losses. When we win, we can cheer for ourselves and our friends. When we lose, we can congratulate the winner and try again next time. Being a good sport means being happy for others when they win and showing kindness when we win.', 'importante', '❗'),
  ('b626967d-b32a-dd1c-7cfe-94a9fbf7f9f6', 4, 'Whether we win or lose, what matters most is that we had fun playing together. Let''s always remember to celebrate each other''s successes and support one another, making every game a positive experience for everyone involved.', 'divertido', '😄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('98982d54-8615-0625-de05-3391e15f1604', 1, 'Listening and sharing are important when working in a team. A team is a group of people who work together to achieve a common goal.', 'compartir', '🤲'),
  ('98982d54-8615-0625-de05-3391e15f1604', 2, 'When I listen to my teammates, I can understand their ideas and feelings better. This helps us work together smoothly. Sharing my thoughts and ideas with the team also lets them know what I''m thinking.', 'escuchar', '👂'),
  ('98982d54-8615-0625-de05-3391e15f1604', 3, 'Sometimes, different team members may have different opinions or ideas. It''s okay! We can talk about it respectfully and find a solution that works for everyone. By listening and sharing, we can learn from each other and make our teamwork stronger.', 'a veces', '⏳'),
  ('98982d54-8615-0625-de05-3391e15f1604', 4, 'In a team, everyone has a role to play. Each person''s contribution is valuable, and when we all work together, we can accomplish great things. When we share tasks and responsibilities, we can support each other and succeed as a team.', 'equipo', '👥'),
  ('98982d54-8615-0625-de05-3391e15f1604', 5, 'Listening and sharing help us build trust and respect within our team. When we work together and appreciate each other''s strengths, we can achieve our goals effectively. Remember, in a team, we all play an important part in reaching success.', 'compartir', '🤲');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('545843f7-d927-9be0-f6ac-a5ea49bc832c', 1, 'My name is Sarah. At school, it''s important to know how to handle bullying situations.', 'escuela', '🏫'),
  ('545843f7-d927-9be0-f6ac-a5ea49bc832c', 2, 'Bullying is when someone hurts me on purpose, over and over again. It can be with words or actions that make me feel sad or scared. If I am being bullied, I should tell a teacher or an adult I trust. They will help me stay safe and happy.', 'acoso', '🚫'),
  ('545843f7-d927-9be0-f6ac-a5ea49bc832c', 3, 'Sometimes, bullies might try to make me feel small or unimportant. But I am strong and brave. I can walk away from the bully and find a friend or a teacher for support. It''s okay to ask for help when I need it.', 'ayuda', '🆘'),
  ('545843f7-d927-9be0-f6ac-a5ea49bc832c', 4, 'Handling bullying at school means standing up for myself in a kind and respectful way. I will always remember that I am valuable and deserving of kindness.', 'acoso', '🚫');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c26b5123-f5ac-0296-7e67-de5800a01df4', 1, 'Learning to follow a recipe is an important skill. It helps us make delicious food and have fun in the kitchen.', 'aprender', '📖'),
  ('c26b5123-f5ac-0296-7e67-de5800a01df4', 2, 'When we follow a recipe, we read the instructions carefully. We gather all the ingredients and tools we need before we start. Then, we follow each step one by one. This way, we can make something yummy!', 'instrucciones', '📋'),
  ('c26b5123-f5ac-0296-7e67-de5800a01df4', 3, 'Sometimes, following a recipe might seem tricky, but it''s okay to ask for help if we don''t understand something. We can also take our time and go through the steps slowly.', 'ayuda', '🆘'),
  ('c26b5123-f5ac-0296-7e67-de5800a01df4', 4, 'Following a recipe helps us create tasty dishes and enjoy cooking together!', 'feliz', '😊');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('cc36f8e4-0651-5295-0c59-7e2f7037a5ad', 1, 'I love playing games and learning on the screen. It''s fun to explore new things and have adventures in different worlds.', 'jugar', '🎮'),
  ('cc36f8e4-0651-5295-0c59-7e2f7037a5ad', 2, 'When I play games or learn on the screen, it''s important to remember a few things. First, it''s good to take breaks and look away from the screen every now and then. This helps my eyes stay healthy and keeps me feeling good. Second, if someone sends me a message or asks me questions while I''m playing, I should always check with an adult before responding. And third, when I''m done using the screen, I need to remember to turn it off and put it away properly.', 'jugar', '🎮'),
  ('cc36f8e4-0651-5295-0c59-7e2f7037a5ad', 3, 'Sometimes, I might get so focused on what I''m doing that I forget these things. But it''s okay because I can always try again next time. Learning how to use the screen responsibly is something I can practice and get better at over time.', 'a veces', '⏳'),
  ('cc36f8e4-0651-5295-0c59-7e2f7037a5ad', 4, 'Using the screen for games and learning is lots of fun! I will remember to take breaks, ask an adult for help, and put the screen away when I''m finished.', 'juegos', '🎲');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5270aeff-5667-7e19-1b39-4c90132c14f7', 1, 'Knowing when to ask for help with my feelings is important.', 'ayuda', '🆘'),
  ('5270aeff-5667-7e19-1b39-4c90132c14f7', 2, 'Sometimes, I feel upset or confused about my emotions. It''s okay to not understand everything all the time.', 'a veces', '⏳'),
  ('5270aeff-5667-7e19-1b39-4c90132c14f7', 3, 'When I have big feelings that are hard to handle, like feeling very sad or angry, it''s a good idea to talk to someone I trust. This could be a parent, teacher, or counselor.', 'sentimientos', '💗'),
  ('5270aeff-5667-7e19-1b39-4c90132c14f7', 4, 'If I''m feeling overwhelmed and don''t know what to do, asking for help can make things better. It''s brave to reach out for support.', 'sentimiento', '💗'),
  ('5270aeff-5667-7e19-1b39-4c90132c14f7', 5, 'Remembering that everyone needs help sometimes can make it easier to ask for help with my feelings.', 'ayuda', '🆘'),
  ('5270aeff-5667-7e19-1b39-4c90132c14f7', 6, 'Asking for help with my feelings is a positive choice. When I ask for help, I show that I am strong and taking care of myself.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 1, 'Hi, my name is Emma. I am an amazing learner at Sunshine School. Sometimes things change and we have to try new experiences. It''s important to be open-minded and embrace these changes.', 'saludar', '👋'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 2, 'CHANGE CAN BE SCARY', 'cambio', '🔄'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 3, 'Change can make us feel nervous or worried because it''s something different from what we are used to. But guess what? Change can also be exciting and fun!', 'cambio', '🔄'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 4, 'TRYING NEW THINGS', 'nuevo', '🆕'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 5, 'When we try new things, we get the chance to learn and grow. We might discover something we really enjoy or find a new friend. It''s like going on an adventure!', 'intentar', '💪'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 6, 'PREPARING FOR CHANGE', 'cambio', '🔄'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 7, 'Sometimes we know in advance that a change is coming. This gives us time to prepare ourselves mentally. We can talk to our teachers or parents about any concerns we have and ask questions to understand better what will happen.', 'a veces', '⏳'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 8, 'TAKING SMALL STEPS', 'feliz', '😊'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 9, 'If trying something completely new feels overwhelming, we can start by taking small steps. For example, if we''re going to a new park, we can explore one area at a time until we feel comfortable exploring the whole place.', 'nuevo', '🆕'),
  ('0b04cc40-c6b4-d82a-86b4-4a7ef8e14b0a', 10, 'Remember, change is a part of life, and learning to love new experiences can bring us joy and excitement. Let''s stay positive and open-minded as we face new challenges and embrace the opportunities they bring.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b7eac7dc-91ba-23b6-3b86-80254e7e1c96', 1, 'Listening and doing are important skills. When we listen carefully and follow instructions, we can do many things successfully.', 'escuchar', '👂'),
  ('b7eac7dc-91ba-23b6-3b86-80254e7e1c96', 2, 'Instructions help us know what to do. They tell us how to complete a task step by step. For example, when Mom says, "Put your toys in the toy box," she is giving an instruction. I need to listen and then put my toys away neatly.', 'instrucciones', '📋'),
  ('b7eac7dc-91ba-23b6-3b86-80254e7e1c96', 3, 'Sometimes, instructions come with more than one step. It''s essential to pay attention to each step so that we can finish the task correctly. If Dad says, "First brush your teeth, then put on your pajamas," I must remember both steps to get ready for bed.', 'atencion', '📢'),
  ('b7eac7dc-91ba-23b6-3b86-80254e7e1c96', 4, 'When someone gives me an instruction, it''s good to look at them and nod to show that I understand. This way, they know I am listening and ready to do as asked.', 'alguien', '✨'),
  ('b7eac7dc-91ba-23b6-3b86-80254e7e1c96', 5, 'By listening carefully and following instructions, I can show others that I am responsible and capable of completing tasks.', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8d673793-23dc-06f5-d1a6-2c9af480636d', 1, 'In our family, we work together as a team. Each person in our family has a special role to play. We all have responsibilities that help our family run smoothly and happily.', 'familia', '👨‍👩‍👧‍👦'),
  ('8d673793-23dc-06f5-d1a6-2c9af480636d', 2, 'Mom takes care of cooking delicious meals for us every day. Dad goes to work to earn money so we can buy things we need. My big sister helps me with my homework when I find it difficult. Even I have a role too! I keep my toys organized and put away after playing with them.', 'dia', '☀️'),
  ('8d673793-23dc-06f5-d1a6-2c9af480636d', 3, 'When we all do our part, our family works like a well-oiled machine. Mom''s meals are ready on time, Dad comes home from work happy, and my sister and I get along better because she helps me with my schoolwork. When everyone contributes, our family is strong and loving.', 'todo', '🌐'),
  ('8d673793-23dc-06f5-d1a6-2c9af480636d', 4, 'Being part of our family means being a valuable member of the team. By doing our part and helping each other out, we create a warm and supportive environment where everyone feels loved and appreciated. Let''s continue working together as a team to make our family even stronger!', 'familia', '👨‍👩‍👧‍👦');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6f3356be-048e-4005-1673-244adecdaa2b', 1, 'Inclusion means being friends with everyone, no matter how they look or what they can do. Making friends is fun and important!', 'inclusion', '🤗'),
  ('6f3356be-048e-4005-1673-244adecdaa2b', 2, 'Some people have different skin colors, speak different languages, or use wheelchairs to move around. It''s okay! We can all be friends.', 'algunos', '✨'),
  ('6f3356be-048e-4005-1673-244adecdaa2b', 3, 'When we make friends with someone who looks different from us, we learn new things and have more fun together. We can play games, share toys, and laugh together.', 'amigos', '🤝'),
  ('6f3356be-048e-4005-1673-244adecdaa2b', 4, 'If someone needs help because they are different, we can offer a hand. Maybe they need help reaching something high, or understanding a game. Helping others makes us good friends.', 'alguien', '✨'),
  ('6f3356be-048e-4005-1673-244adecdaa2b', 5, 'Being kind and friendly to everyone, even if they seem different, helps us create a happy and inclusive world where everyone feels accepted and valued.', 'amable', '💝'),
  ('6f3356be-048e-4005-1673-244adecdaa2b', 6, 'Inclusion is about making friends with everyone, no matter their differences. Let''s be kind, helpful, and open to new friendships. Inclusion makes our world brighter and happier for everyone!', 'inclusion', '🤗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2cd9e646-f645-7c92-d4cf-b4a38f5fba3c', 1, 'Empathy is like a superpower. It helps us understand how other people feel and see things from their perspective. Just like superheroes, we all have the power of empathy inside us.', 'gustar', '👍'),
  ('2cd9e646-f645-7c92-d4cf-b4a38f5fba3c', 2, 'When someone is sad or upset, we can use our superpower to show them kindness and support. We can listen to them, offer a hug, or say kind words to make them feel better. When we put ourselves in their shoes, we can understand why they might be feeling the way they do.', 'escuchar', '👂'),
  ('2cd9e646-f645-7c92-d4cf-b4a38f5fba3c', 3, 'Sometimes, it''s hard for us to know how someone else feels because we can''t see their thoughts or emotions. But we can still use our superpower by paying attention to their facial expressions, body language, and tone of voice. These clues can help us understand what they might be going through.', 'a veces', '⏳'),
  ('2cd9e646-f645-7c92-d4cf-b4a38f5fba3c', 4, 'Empathy also helps us build strong friendships. When we understand how our friends feel, we can be there for them when they need us. We can celebrate their successes and support them during tough times. Our superpower of empathy makes us great friends!', 'construir', '🔨'),
  ('2cd9e646-f645-7c92-d4cf-b4a38f5fba3c', 5, 'Remember, empathy is a superpower we all have. By using our superpower, we can show kindness, understanding, and support to others. Let''s embrace our superpower and make the world a better place one act of empathy at a time.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fbc98015-2224-b328-5065-f12c714baf44', 1, 'During school, there are times when everyone gathers together in one place. This is called assembly time. What happens during assembly time? Let''s find out!', 'escuela', '🏫'),
  ('fbc98015-2224-b328-5065-f12c714baf44', 2, 'At assembly time, students sit quietly and listen to announcements or songs. Sometimes, teachers may talk about important things happening at school.', 'escuchar', '👂'),
  ('fbc98015-2224-b328-5065-f12c714baf44', 3, 'When it''s time to stand up or move to a different location, I can follow my teacher''s directions. It''s important to be respectful and quiet during assembly time so that everyone can hear what''s being said.', 'instrucciones', '📋'),
  ('fbc98015-2224-b328-5065-f12c714baf44', 4, 'If I have trouble understanding something during assembly time, I can raise my hand and ask my teacher for help. Teachers are there to support us and make sure we understand what''s going on.', 'tiempo', '⏰'),
  ('fbc98015-2224-b328-5065-f12c714baf44', 5, 'Assembly time is a special part of our school day. I will try my best to listen carefully, follow instructions, and show respect during assembly time.', 'escuchar', '👂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('68806c9d-e247-dced-3cd0-72ff7e59f9be', 1, 'Celebrations are special times when people come together to have fun and share happiness. Understanding different celebrations can be exciting!', 'especial', '⭐'),
  ('68806c9d-e247-dced-3cd0-72ff7e59f9be', 2, 'Different celebrations happen throughout the year, like birthdays, holidays, or cultural events. Each celebration has its own traditions and ways of celebrating. For example, on birthdays, we sing songs, eat cake, and give gifts to show love and appreciation.', 'diferente', '🌈'),
  ('68806c9d-e247-dced-3cd0-72ff7e59f9be', 3, 'During holidays, families gather, decorate their homes, exchange gifts, and enjoy special meals together. It''s a time for joy, giving thanks, and creating lasting memories with loved ones.', 'especial', '⭐'),
  ('68806c9d-e247-dced-3cd0-72ff7e59f9be', 4, 'Cultural events celebrate traditions and customs unique to specific groups of people. They often involve music, dance, food, and colorful decorations that represent their heritage and values.', 'celebrar', '🎊'),
  ('68806c9d-e247-dced-3cd0-72ff7e59f9be', 5, 'Understanding different celebrations helps us appreciate diversity, respect others'' beliefs, and join in the spirit of unity and joy. It''s an opportunity to learn about new cultures, make friends, and create meaningful connections.', 'diferente', '🌈'),
  ('68806c9d-e247-dced-3cd0-72ff7e59f9be', 6, 'By understanding different celebrations, we open our hearts to the beauty of diversity and shared experiences. Embracing various traditions enriches our lives and brings us closer to one another. Let''s celebrate together with kindness and joy!', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5379b4f6-ba15-760c-dd09-edb592ed27e4', 1, 'Understanding gestures and movements can help me communicate better with others. When I pay attention to people''s body language, I can understand how they are feeling or what they want to say without using words.', 'atencion', '📢'),
  ('5379b4f6-ba15-760c-dd09-edb592ed27e4', 2, 'Gestures and movements are like a secret code that people use to express themselves. For example, if someone is smiling and nodding, it usually means they agree or feel happy. If someone is frowning and crossing their arms, it might mean they are upset or uncomfortable.', 'gustar', '👍'),
  ('5379b4f6-ba15-760c-dd09-edb592ed27e4', 3, 'When I see someone waving at me, I can wave back to show that I acknowledge them. If someone points to something, I can look in the direction they''re pointing to see what they want me to notice.', 'ver', '👀'),
  ('5379b4f6-ba15-760c-dd09-edb592ed27e4', 4, 'It''s important for me to remember that not everyone uses the same gestures and movements, so I should also pay attention to the context and the person''s individual habits to fully understand what they are trying to convey.', 'atencion', '📢'),
  ('5379b4f6-ba15-760c-dd09-edb592ed27e4', 5, 'By paying attention to gestures and movements, I can become better at understanding and communicating with others. It''s like learning a special language that helps me connect with people around me.', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('636e9cfe-8b8e-30b8-dbd6-2c1c87516c2a', 1, 'Recycling is a way to help our planet Earth stay healthy and clean. We can all do our part by recycling things we no longer need.', 'forma', '📐'),
  ('636e9cfe-8b8e-30b8-dbd6-2c1c87516c2a', 2, 'When we recycle, we sort items like paper, plastic, glass, and metal into different bins. These items are then taken to special places where they can be made into new things.', 'gustar', '👍'),
  ('636e9cfe-8b8e-30b8-dbd6-2c1c87516c2a', 3, 'By recycling, we save energy and reduce the amount of waste that goes into landfills. This helps protect animals and plants that live on our planet.', 'proteger', '🛡️'),
  ('636e9cfe-8b8e-30b8-dbd6-2c1c87516c2a', 4, 'Recycling is important for a better tomorrow. By recycling, we show that we care about our planet and want to keep it beautiful for everyone. Let''s remember to recycle every day!', 'importante', '❗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('17bbebc2-70dd-6d68-4331-21fd18759d60', 1, 'This is my story about connecting with others through shared emotions.', 'feliz', '😊'),
  ('17bbebc2-70dd-6d68-4331-21fd18759d60', 2, 'Sometimes, people feel the same way. When I am happy, someone else may be happy too. If I am sad, someone else might also feel sad.', 'a veces', '⏳'),
  ('17bbebc2-70dd-6d68-4331-21fd18759d60', 3, 'When I see someone feeling sad, I can try to comfort them. I can say kind words or give them a hug if they like hugs. This helps them feel better.', 'ver', '👀'),
  ('17bbebc2-70dd-6d68-4331-21fd18759d60', 4, 'If I am feeling upset, it''s okay to tell someone how I feel. They may understand and help me feel better. Sharing our feelings can make us feel closer to each other.', 'sentimiento', '💗'),
  ('17bbebc2-70dd-6d68-4331-21fd18759d60', 5, 'It''s important to listen when someone shares their feelings with me. I can show that I care by listening and offering support. This makes them feel valued and understood.', 'importante', '❗'),
  ('17bbebc2-70dd-6d68-4331-21fd18759d60', 6, 'Connecting through shared emotions is a special way to bond with others. When we share our feelings, we create stronger connections with those around us. Let''s remember that sharing our emotions can bring us closer together.', 'especial', '⭐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('71c217b2-c70a-3832-b107-9d1e32036aab', 1, 'Following a schedule helps me know what to expect throughout the day. It makes things easier and less confusing.', 'horario', '📅'),
  ('71c217b2-c70a-3832-b107-9d1e32036aab', 2, 'When I wake up, I can look at my schedule to see what comes next. First, I brush my teeth and get dressed. Then, it''s time for breakfast. After that, I go to school or start my activities at home. My schedule tells me when it''s time for lunch, playtime, and learning.', 'cepillarse', '🪥'),
  ('71c217b2-c70a-3832-b107-9d1e32036aab', 3, 'Sometimes, unexpected things happen, but that''s okay. I can ask for help if I need it. When I follow my schedule, I feel more in control and ready for each part of the day.', 'ayuda', '🆘'),
  ('71c217b2-c70a-3832-b107-9d1e32036aab', 4, 'Following my schedule helps me feel organized and prepared. I will try my best to follow it every day because it makes everything easier and less confusing.', 'horario', '📅');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2962e737-80e0-659a-9450-6fd3740a3926', 1, 'Understanding when to say no and yes is important in our daily lives.', 'decir', '💬'),
  ('2962e737-80e0-659a-9450-6fd3740a3926', 2, 'When someone asks me a question, I can answer with "yes" if I agree or want to do something. If I don''t agree or don''t want to do it, I can say "no." Saying "no" is okay when something makes me uncomfortable or if I need help.', 'alguien', '✨'),
  ('2962e737-80e0-659a-9450-6fd3740a3926', 3, 'If my friend wants to play a game that I don''t like, I can politely say, "No thank you, I prefer a different game." It''s important to be respectful and kind when saying no.', 'gracias', '🙏'),
  ('2962e737-80e0-659a-9450-6fd3740a3926', 4, 'Saying "yes" shows that I am happy to join in or help out. When mom asks if I want to read a book together, I can say "yes" because I enjoy reading with her.', 'feliz', '😊'),
  ('2962e737-80e0-659a-9450-6fd3740a3926', 5, 'It''s also good to listen when others say no or yes. If someone says no to playing tag, I should respect their choice and find another game to play.', 'bien', '👍'),
  ('2962e737-80e0-659a-9450-6fd3740a3926', 6, 'Knowing when to say no and yes helps me communicate effectively with others and shows that I respect their feelings and choices.', 'decir', '💬');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('214cb5ab-1216-535a-9220-5cfa356f8596', 1, 'Emotions are like colors that paint our day.', 'gustar', '👍'),
  ('214cb5ab-1216-535a-9220-5cfa356f8596', 2, 'Each feeling has a color. When I am happy, it''s like the sun shining bright yellow. Sadness feels like a rainy day with gray clouds. Anger is fiery red, and calmness is a soothing blue. Sometimes, I might feel a mix of colors, like when I''m excited and a little nervous at the same time.', 'sentimiento', '💗'),
  ('214cb5ab-1216-535a-9220-5cfa356f8596', 3, 'When I see someone smiling, they might be feeling yellow happiness. If someone looks upset, their color could be stormy gray sadness. It''s important to recognize these colors in myself and others so we can understand how we''re feeling.', 'ver', '👀'),
  ('214cb5ab-1216-535a-9220-5cfa356f8596', 4, 'Just like an artist uses different colors to create a masterpiece, we use our emotions to paint our lives. By understanding the colors of our feelings, we can express ourselves better and connect with those around us.', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2b719d27-5b81-fbd6-5373-a86ba77786a8', 1, 'Celebrating together, celebrating differently is something we do with our family and friends. It’s a way to share happiness and create special memories.', 'familia', '👨‍👩‍👧‍👦'),
  ('2b719d27-5b81-fbd6-5373-a86ba77786a8', 2, 'Different families celebrate in different ways. Some people have big parties, while others prefer quiet gatherings. My friend, Sarah, celebrates her birthday by going to the park with her family. They play games and have a picnic. Another friend, Alex, has a big party at his house with lots of decorations and music.', 'diferente', '🌈'),
  ('2b719d27-5b81-fbd6-5373-a86ba77786a8', 3, 'In my family, we celebrate birthdays by having a special dinner together. We also give each other gifts to show how much we care. Sometimes, we invite relatives over to join in the celebration. Everyone brings something delicious to eat.', 'familia', '👨‍👩‍👧‍👦'),
  ('2b719d27-5b81-fbd6-5373-a86ba77786a8', 4, 'During holidays like Christmas or Eid, some families exchange gifts, while others spend time volunteering to help those in need. Each family has its own traditions that make these celebrations unique and meaningful.', 'gustar', '👍'),
  ('2b719d27-5b81-fbd6-5373-a86ba77786a8', 5, 'It’s important to respect how others choose to celebrate. Even if it’s different from what we’re used to, we can learn new things and enjoy the diversity of traditions around us. By being open-minded and accepting, we can appreciate the beauty of various customs and come together in harmony.', 'importante', '❗'),
  ('2b719d27-5b81-fbd6-5373-a86ba77786a8', 6, 'Celebrating together, celebrating differently teaches us about the richness of cultural diversity. Whether it''s a small gathering or a grand event, every celebration is an opportunity to cherish moments with loved ones and embrace the uniqueness of each tradition.', 'celebracion', '🎊');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5fdccb0c-7d00-7a38-7f88-f5c64a9989f0', 1, 'Handling surprises at celebrations can be exciting and sometimes a little bit scary. It’s fun to have special days where we celebrate with our family and friends.', 'a veces', '⏳'),
  ('5fdccb0c-7d00-7a38-7f88-f5c64a9989f0', 2, 'Sometimes, people give me presents on these special days. I like getting presents, but it can also make me feel a little nervous because I don’t know what is inside the wrapping paper. Last year, I got a big surprise when I opened my present. It was something I really liked! This made me happy.', 'a veces', '⏳'),
  ('5fdccb0c-7d00-7a38-7f88-f5c64a9989f0', 3, 'I remember that Hunter felt the same way last year. He didn''t know what his gift would be, so he was a little worried. But when he opened it, he was very excited and thanked everyone for the wonderful gift. That made him feel proud!', 'recordar', '📝'),
  ('5fdccb0c-7d00-7a38-7f88-f5c64a9989f0', 4, 'When I get a surprise present, I will try to remember how happy I felt last time. Even if I feel a little nervous, I will open it and say thank you. I might even find something I really love inside!', 'gracias', '🙏');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0d612fff-c975-aec6-f7ea-17f7bb8d7eef', 1, 'Crossing the street is an important skill. Safety first!', 'calle', '🏙️'),
  ('0d612fff-c975-aec6-f7ea-17f7bb8d7eef', 2, 'When I want to cross the street, I need to stop and look both ways. I must wait for the cars to pass before crossing. It''s important to always use a crosswalk if there is one. If there isn''t a crosswalk, I should find a safe place with good visibility to cross.', 'semaforo', '🚦'),
  ('0d612fff-c975-aec6-f7ea-17f7bb8d7eef', 3, 'Sometimes, I may see a sign that shows me when it''s safe to walk. This sign has a picture of a person walking. When the light changes to this picture, it means I can cross safely.', 'a veces', '⏳'),
  ('0d612fff-c975-aec6-f7ea-17f7bb8d7eef', 4, 'Remember, safety comes first when crossing the street. Always stop, look both ways, and use a crosswalk if available. By following these rules, I can stay safe while crossing the street.', 'semaforo', '🚦');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8bcb19ee-3958-923b-b1d2-934e9e2c2c25', 1, 'Accepting different preferences and choices', 'diferente', '🌈'),
  ('8bcb19ee-3958-923b-b1d2-934e9e2c2c25', 2, 'Everyone is unique, just like a snowflake or a fingerprint. We all have our own likes and dislikes, which make us special. Some people may prefer things that are different from what I like, and that''s okay. It''s important to respect these differences.', 'todos', '🌐'),
  ('8bcb19ee-3958-923b-b1d2-934e9e2c2c25', 3, 'When we respect someone''s preferences, it shows that we care about them and value their feelings. For example, if a friend likes a certain game that I''m not interested in, I can still be supportive and understanding of their choice. This helps create a positive and inclusive environment where everyone feels accepted.', 'respetar', '🙇'),
  ('8bcb19ee-3958-923b-b1d2-934e9e2c2c25', 4, 'It''s natural to feel curious about why someone likes something that we don''t understand. Instead of judging or making fun of them, we can ask questions politely and try to learn more about their perspective. This way, we can broaden our own horizons and appreciate the diversity around us.', 'sentir', '💓'),
  ('8bcb19ee-3958-923b-b1d2-934e9e2c2c25', 5, 'Respecting different preferences also means being open-minded and flexible. Just as I enjoy having my own choices respected, I should extend the same courtesy to others. By embracing diversity and inclusion, we can build strong relationships based on mutual respect and understanding.', 'diferente', '🌈'),
  ('8bcb19ee-3958-923b-b1d2-934e9e2c2c25', 6, 'Accepting different preferences and choices makes our world colorful and exciting. Let''s celebrate the uniqueness in each of us and embrace the beauty of diversity.', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 1, 'At the playground, we have fun and play with friends. How can we make sure everyone has a good time?', 'columpio', '🎠'),
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 2, 'When we arrive at the playground, we can take turns on the swings and slides. It''s important to wait patiently for our turn.', 'esperar', '⏳'),
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 3, 'If someone is already using a toy or equipment, we can ask nicely if we can join in or use it next. Sharing is caring!', 'alguien', '✨'),
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 4, 'We should listen to the grown-ups at the playground. They are there to keep us safe and help us have fun.', 'escuchar', '👂'),
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 5, 'Running around and playing is great, but we need to be careful not to bump into others. We can watch where we''re going.', 'jugar', '🎮'),
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 6, 'If we see someone who looks sad or upset, we can ask them if they want to play with us. Being kind makes everyone feel happy.', 'ver', '👀'),
  ('8be06fe0-acb4-113b-4837-d5b76e73bd0a', 7, 'Playing at the playground is so much fun when we all show respect and kindness. Let''s remember to share, take turns, and play together happily.', 'esperar', '⏳');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 1, 'Reading faces: a guide to emotional expressions', 'leer', '📖'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 2, 'Understanding how people feel by looking at their faces is important.', 'personas', '👥'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 3, 'When someone feels happy, their face may show a smile. Their eyes might sparkle, and their mouth turns up at the corners.', 'alguien', '✨'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 4, 'If someone feels sad, their face might look droopy. They may frown, and their eyes could be watery.', 'alguien', '✨'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 5, 'Angry feelings can make a person''s face turn red. Their eyebrows might come together, and their lips press tightly.', 'enfadado', '😤'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 6, 'When someone is scared, their eyes widen, and their mouth might open in surprise. Their face may look pale or tense.', 'alguien', '✨'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 7, 'Confused feelings can make a person furrow their brow. They might tilt their head to the side, trying to understand.', 'sentimientos', '💗'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 8, 'Sometimes, people feel calm. Their face looks relaxed, with soft eyes and a gentle expression.', 'a veces', '⏳'),
  ('df2e1a1a-01e4-fa35-c12e-d86d6932fca4', 9, 'Reading faces helps me understand how others are feeling. When I see a smile, I know they''re happy. If I see a frown, they might be sad. Recognizing emotions on faces helps me connect with others and respond appropriately.', 'leer', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('44da7f8a-eeca-2e69-b1d4-c5fc79ab2c66', 1, 'Sometimes, we can encounter situations where people are mean or hurtful to us. This is called bullying. But don''t worry, there are ways we can handle it and protect ourselves.', 'a veces', '⏳'),
  ('44da7f8a-eeca-2e69-b1d4-c5fc79ab2c66', 2, 'Bullying can happen in different places like school, the playground, or even online. It''s important to remember that bullying is never okay, and it''s not my fault if someone bullies me. If someone says mean things or tries to hurt me physically, it''s important to stay calm and not let their words or actions affect me. Remember, I am strong and capable of handling this situation.', 'acoso', '🚫'),
  ('44da7f8a-eeca-2e69-b1d4-c5fc79ab2c66', 3, 'One way to deal with bullying is by using verbal strategies. I can assertively tell the person to stop and let them know that their behavior is not acceptable. For example, I can say, "Please stop saying mean things to me. I deserve to be treated with respect." It''s also helpful to find a trusted adult, like a teacher or parent, who can support me and help resolve the situation.', 'forma', '📐'),
  ('44da7f8a-eeca-2e69-b1d4-c5fc79ab2c66', 4, 'Another strategy is to ignore the bully and walk away. Sometimes, bullies want attention, so by not giving them a reaction, they may lose interest and move on. It''s important to remember that I have the power to choose how I respond to bullying.', 'otro', '🔄'),
  ('44da7f8a-eeca-2e69-b1d4-c5fc79ab2c66', 5, 'Lastly, practicing role-playing scenarios can be really helpful. By pretending to be in different situations and practicing what to say and do, I can build confidence and be prepared if bullying happens. I can practice with a friend, sibling, or even a stuffed animal. The more I practice, the better equipped I''ll be to handle these situations.', 'jugar', '🎮'),
  ('44da7f8a-eeca-2e69-b1d4-c5fc79ab2c66', 6, 'Remember, bullying is never my fault, and I deserve to be treated with kindness and respect. By using verbal strategies, walking away, and practicing role-playing scenarios, I can stand up against bullying and protect myself. I am strong, brave, and capable of handling any challenges that come my way.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('cbc0e2a2-bc39-bc30-a713-9317900803aa', 1, 'Understanding different personalities is an important part of making friends. Each person is unique and has their own way of thinking, feeling, and acting.', 'diferente', '🌈'),
  ('cbc0e2a2-bc39-bc30-a713-9317900803aa', 2, 'When I meet someone new, I notice that they may be different from me. They might like things that I don’t like, or they might do things in a way that I wouldn’t. That’s okay! It’s what makes each of us special.', 'alguien', '✨'),
  ('cbc0e2a2-bc39-bc30-a713-9317900803aa', 3, 'Some people are very outgoing and love to talk a lot. Others are more quiet and prefer to listen. Some people enjoy being around others all the time, while some need alone time to recharge.', 'algunos', '✨'),
  ('cbc0e2a2-bc39-bc30-a713-9317900803aa', 4, 'It’s important to remember that just because someone is different from me doesn’t mean they’re wrong. We can learn a lot from each other by respecting and appreciating our differences.', 'importante', '❗'),
  ('cbc0e2a2-bc39-bc30-a713-9317900803aa', 5, 'If I’m not sure how to interact with someone who has a different personality than mine, I can start by asking questions and showing interest in what they have to say. This helps me understand them better and shows that I care about getting to know them.', 'alguien', '✨'),
  ('cbc0e2a2-bc39-bc30-a713-9317900803aa', 6, 'Understanding different personalities is a key step in making friends. By accepting and embracing the uniqueness of others, I can build strong and meaningful relationships based on respect and appreciation.', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a02a84dd-5da8-41e7-e98d-55af84911cdf', 1, 'I have some favorite animals that I really love. Taking care of them is important to me.', 'algunos', '✨'),
  ('a02a84dd-5da8-41e7-e98d-55af84911cdf', 2, 'My favorite animals are my pets, and they rely on me for their food, water, and shelter. It''s essential to feed them the right amount of food each day and make sure they always have fresh water available. Cleaning their living space regularly helps keep them healthy and happy.', 'comida', '🍽️'),
  ('a02a84dd-5da8-41e7-e98d-55af84911cdf', 3, 'When my pets need medical attention or grooming, it''s crucial to take them to the veterinarian or groomer. This ensures they stay in good health and look their best.', 'necesitar', '❗'),
  ('a02a84dd-5da8-41e7-e98d-55af84911cdf', 4, 'Spending quality time with my pets by playing, petting, or talking to them strengthens our bond and makes us both feel happy and loved. Animals can understand when we care for them and show them affection.', 'tiempo', '⏰'),
  ('a02a84dd-5da8-41e7-e98d-55af84911cdf', 5, 'Caring for my favorite animals brings me joy and teaches me responsibility. They depend on me, and I enjoy being there for them every day. My pets are a special part of my life, and I will continue to care for them with love and dedication.', 'alegria', '🎉');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9f58bef9-3748-00cb-fd4d-a6ebdaf6b6bc', 1, 'I am learning about non-verbal communication. Non-verbal means without using words.', 'aprender', '📖'),
  ('9f58bef9-3748-00cb-fd4d-a6ebdaf6b6bc', 2, 'People use non-verbal communication to show how they feel or what they want, even if they don''t say it out loud. They might use their face, hands, or body to communicate. For example, when someone smiles, it usually means they are happy. When someone frowns, it can mean they are upset. I can also look at a person''s eyes and see if they are looking at me or somewhere else. This helps me understand if they are paying attention to me or something else.', 'personas', '👥'),
  ('9f58bef9-3748-00cb-fd4d-a6ebdaf6b6bc', 3, 'When I pay attention to people''s non-verbal signals, I can better understand how they are feeling and respond in a way that makes them comfortable. If someone looks sad, I can try to cheer them up. If someone looks angry, I can give them space until they feel better. It''s important to remember that not everyone shows their feelings in the same way, so I should always be patient and understanding.', 'atencion', '📢'),
  ('9f58bef9-3748-00cb-fd4d-a6ebdaf6b6bc', 4, 'Understanding non-verbal communication is like learning a new language. By paying attention to people''s expressions and body language, I can better understand how they feel and what they need. I will practice looking for these signals every day to become more skilled at understanding others without words.', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b6c00d1c-2ca7-6465-552b-dedfc053b582', 1, 'Giving and receiving gifts is a special part of celebrations and holidays. It''s a way to show love and appreciation for others.', 'especial', '⭐'),
  ('b6c00d1c-2ca7-6465-552b-dedfc053b582', 2, 'When I give someone a gift, it shows that I care about them. I can say, "Here''s a gift for you. I hope you like it." People often say "thank you" even before opening the gift because they appreciate the time and effort put into choosing and wrapping it.', 'gracias', '🙏'),
  ('b6c00d1c-2ca7-6465-552b-dedfc053b582', 3, 'Receiving a gift is exciting! Sometimes people open their gifts right away, while other times they wait. Either way, saying "thank you" is polite and shows gratitude.', 'gracias', '🙏'),
  ('b6c00d1c-2ca7-6465-552b-dedfc053b582', 4, 'Giving and receiving gifts is a wonderful way to spread joy and kindness during celebrations and holidays. It''s not just about the gift itself, but the thought and love behind it. So remember, giving and receiving gifts is a special way to connect with others and make memories together.', 'forma', '📐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('52f6aba1-64ce-5cb5-b977-6146fc48e3b1', 1, 'Story time is a special part of my day. I love listening to stories and looking at the pictures in the books.', 'tiempo', '⏰'),
  ('52f6aba1-64ce-5cb5-b977-6146fc48e3b1', 2, 'At story time, we sit together and listen quietly. The teacher reads us a story about animals, or friends, or adventures. Sometimes, she asks us questions about the story, and we can answer if we want to.', 'tiempo', '⏰'),
  ('52f6aba1-64ce-5cb5-b977-6146fc48e3b1', 3, 'I like when the teacher uses different voices for the characters in the story. It makes the story more fun to listen to.', 'escuchar', '👂'),
  ('52f6aba1-64ce-5cb5-b977-6146fc48e3b1', 4, 'After the story, we get to draw or play with toys. I like drawing pictures of the animals or things from the story.', 'dibujar', '🎨'),
  ('52f6aba1-64ce-5cb5-b977-6146fc48e3b1', 5, 'Story time is a happy time. I feel calm and happy when I listen to the stories. I look forward to story time every day.', 'escuchar', '👂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('64b3454f-3dea-7e0e-780e-15f3802e6e7e', 1, 'Navigating family disagreements is part of being in a family. It’s important to learn how to handle disagreements with kindness and respect.', 'familia', '👨‍👩‍👧‍👦'),
  ('64b3454f-3dea-7e0e-780e-15f3802e6e7e', 2, 'Sometimes, people in my family may have different opinions or feelings about something. That''s okay because everyone is unique and has their own thoughts and emotions. When we disagree, it''s important to listen to each other and try to understand why the other person feels that way. We can use calm voices and polite words to express our thoughts.', 'escuchar', '👂'),
  ('64b3454f-3dea-7e0e-780e-15f3802e6e7e', 3, 'It''s also helpful to remember that it''s okay to agree to disagree. This means that even if we don''t see eye-to-eye on something, we can still be kind and respectful towards each other. If things get too intense, taking a break and coming back to the conversation later can help us cool down and think more clearly.', 'recordar', '📝'),
  ('64b3454f-3dea-7e0e-780e-15f3802e6e7e', 4, 'When we work through disagreements together, we show love and understanding for one another. It''s like putting puzzle pieces together – when we communicate and compromise, we find solutions that fit for everyone.', 'trabajar', '💼'),
  ('64b3454f-3dea-7e0e-780e-15f3802e6e7e', 5, 'Navigating family disagreements is a normal part of being in a family. By listening, using kind words, and finding compromises, we can navigate disagreements with respect and love.', 'familia', '👨‍👩‍👧‍👦');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c8309b0f-08bc-70e1-8ca5-9701f50e55f8', 1, 'Making mistakes is a part of learning. Everyone makes mistakes sometimes, and that''s okay.', 'errores', '💪'),
  ('c8309b0f-08bc-70e1-8ca5-9701f50e55f8', 2, 'When we make mistakes, it helps us learn how to do things better next time. Making mistakes doesn''t mean we''re not smart or capable. It just means we''re still learning.', 'errores', '💪'),
  ('c8309b0f-08bc-70e1-8ca5-9701f50e55f8', 3, 'Sometimes, when I make a mistake, I can try again. Other times, I might need help from an adult to figure out what went wrong and how to fix it.', 'error', '💪'),
  ('c8309b0f-08bc-70e1-8ca5-9701f50e55f8', 4, 'It''s important to remember that making mistakes is normal and okay. We can learn from our mistakes and keep trying. Everyone makes mistakes, and it''s all a part of growing and learning.', 'importante', '❗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e54b4a97-e955-2f0b-5e1c-5810da5c78e3', 1, 'Sometimes, I feel different emotions. It''s like being a detective trying to solve a mystery! That''s why I have my very own Emotion Detective Kit.', 'a veces', '⏳'),
  ('e54b4a97-e955-2f0b-5e1c-5810da5c78e3', 2, 'Inside my kit, there are special tools to help me understand and manage my emotions. One tool is called "Identifying Emotions." It helps me recognize how I am feeling by looking at my facial expressions, body language, and the words I use. When I feel happy, my face might light up with a big smile. When I feel sad, my eyes might get watery and my shoulders droop down. By paying attention to these clues, I can figure out what emotion I am experiencing.', 'dentro', '🏠'),
  ('e54b4a97-e955-2f0b-5e1c-5810da5c78e3', 3, 'Another tool in my kit is called "Managing Emotions." This tool helps me handle my feelings in a positive way. For example, when I feel angry or frustrated, I can take deep breaths or count to ten to calm myself down. If I feel worried or anxious, I can talk to a trusted adult or do something that makes me feel relaxed, like listening to music or drawing.', 'respirar', '🫁'),
  ('e54b4a97-e955-2f0b-5e1c-5810da5c78e3', 4, 'My Emotion Detective Kit also includes a tool called "Expressing Emotions." Sometimes, it''s important to let others know how we''re feeling. I can use words to tell someone if I''m happy, sad, excited, or mad. I can also use my body language, like giving a high-five when I''m proud or hugging someone when I''m feeling loving.', 'a veces', '⏳'),
  ('e54b4a97-e955-2f0b-5e1c-5810da5c78e3', 5, 'Having my Emotion Detective Kit helps me understand and manage my emotions. It''s like having superpowers! With practice, I will become an expert at solving the mystery of my emotions and using my tools to stay calm and happy.', 'entender', '🧠');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3ba94b81-314a-8230-0799-4f239821e0d0', 1, 'Celebrations and traditions are special events that bring people together. They help us connect with others and learn about different cultures. It''s exciting to be part of these celebrations!', 'especial', '⭐'),
  ('3ba94b81-314a-8230-0799-4f239821e0d0', 2, 'People from all around the world have unique ways of celebrating. Some celebrate birthdays, while others celebrate holidays like Christmas or Diwali. Each celebration has its own customs and traditions.', 'personas', '👥'),
  ('3ba94b81-314a-8230-0799-4f239821e0d0', 3, 'During celebrations, families and friends come together to share food, stories, and laughter. They may sing songs, dance, or play games. These activities create a joyful atmosphere and make everyone feel happy.', 'amigos', '🤝'),
  ('3ba94b81-314a-8230-0799-4f239821e0d0', 4, 'Sometimes, celebrations involve special decorations. For example, during Chinese New Year, red lanterns are hung up to bring good luck. On Halloween, people carve pumpkins into funny faces called jack-o''-lanterns.', 'a veces', '⏳'),
  ('3ba94b81-314a-8230-0799-4f239821e0d0', 5, 'Food is an important part of celebrations too. Different cultures have their own traditional dishes. In Mexico, they eat tamales on Christmas Eve. In India, they enjoy sweets like ladoos during Diwali.', 'comida', '🍽️'),
  ('3ba94b81-314a-8230-0799-4f239821e0d0', 6, 'Celebrations and traditions are a wonderful way to connect with others and appreciate diversity. By participating in these communal activities, we can learn about different cultures and make new friends. Let''s embrace the joy and unity that celebrations bring!', 'forma', '📐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c8f62d36-b442-e548-be38-b0c0d152adb2', 1, 'Building skills and confidence in my hobbies is important. It helps me feel good about myself and connect with others who enjoy the same things.', 'importante', '❗'),
  ('c8f62d36-b442-e548-be38-b0c0d152adb2', 2, 'When I practice my hobbies, like painting or playing soccer, I get better at them. This makes me proud of what I can do. Sometimes, trying new things can be a little scary, but it''s okay to take small steps and ask for help if needed.', 'ayuda', '🆘'),
  ('c8f62d36-b442-e548-be38-b0c0d152adb2', 3, 'I can share my hobbies with my family and friends. They might enjoy learning about what I like to do and even join me sometimes. Sharing my hobbies can also help me make new friends who have similar interests.', 'compartir', '🤲'),
  ('c8f62d36-b442-e548-be38-b0c0d152adb2', 4, 'It''s important to remember that everyone has different hobbies, and that''s okay. What matters most is that we enjoy what we''re doing and feel happy while doing it.', 'importante', '❗'),
  ('c8f62d36-b442-e548-be38-b0c0d152adb2', 5, 'Building skills and confidence in my hobbies is fun and rewarding. I will keep practicing and sharing my hobbies with others. This way, I can grow as a person and create meaningful connections with those around me.', 'divertido', '😄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b777792d-f965-85f1-b3e0-68b3f66ce756', 1, 'Change can be exciting! It means new things are happening. When we welcome change, it helps us grow and learn.', 'cambio', '🔄'),
  ('b777792d-f965-85f1-b3e0-68b3f66ce756', 2, 'Sometimes, changes happen at school. A new student may join our class. We can say, “Welcome to our class!” and show them around. This will help them feel happy and comfortable in their new environment.', 'a veces', '⏳'),
  ('b777792d-f965-85f1-b3e0-68b3f66ce756', 3, 'We might have a new teacher or a different classroom. Even though it feels strange at first, we can remember that change is an opportunity for new experiences and learning. We can try to make the best of it by being open-minded and curious about what’s ahead.', 'nuevo', '🆕'),
  ('b777792d-f965-85f1-b3e0-68b3f66ce756', 4, 'Change can also happen outside of school. Maybe we move to a new house or a new neighborhood. It might seem unfamiliar at first, but we can think of it as an adventure. We can explore the new surroundings and look for interesting places and people to meet.', 'cambio', '🔄'),
  ('b777792d-f965-85f1-b3e0-68b3f66ce756', 5, 'Welcoming change with a positive attitude can lead to wonderful opportunities and experiences. Embracing new experiences allows us to grow and learn, making life more exciting and fulfilling.', 'cambio', '🔄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('56ffdf7d-c2ff-2a73-4011-975cc817a709', 1, 'Feeling overwhelmed is when I have a lot of emotions all at once. It can be hard to know what to do when this happens.', 'sentimiento', '💗'),
  ('56ffdf7d-c2ff-2a73-4011-975cc817a709', 2, 'When I feel overwhelmed, it''s important to take deep breaths. Deep breaths help me calm down and think more clearly. I can also try counting slowly to 10 or finding a quiet place to relax for a bit.', 'respirar', '🫁'),
  ('56ffdf7d-c2ff-2a73-4011-975cc817a709', 3, 'Sometimes, talking about my feelings with someone I trust can make me feel better. They might have ideas on how to help me feel less overwhelmed.', 'a veces', '⏳'),
  ('56ffdf7d-c2ff-2a73-4011-975cc817a709', 4, 'It''s okay to take a break from what I''m doing if I need to. Stepping away for a moment can give me time to regroup and come back feeling more in control.', 'necesitar', '❗'),
  ('56ffdf7d-c2ff-2a73-4011-975cc817a709', 5, 'Remember, everyone feels overwhelmed sometimes. It''s a normal feeling, and there are ways to manage it.', 'recordar', '📝'),
  ('56ffdf7d-c2ff-2a73-4011-975cc817a709', 6, 'When I feel overwhelmed, I will remember to breathe deeply, talk to someone I trust, and take breaks when needed. Managing overwhelming emotions is something I can learn to do.', 'sentir', '💓');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('62236891-5570-b894-2573-1bc82212bb1e', 1, 'Playing basketball is a fun and exciting game. It involves teamwork, coordination, and lots of movement on the court.', 'jugar', '🎮'),
  ('62236891-5570-b894-2573-1bc82212bb1e', 2, 'When playing basketball, each player has an important role to help their team score points. Passing the ball, dribbling, and shooting are skills that players practice to become better at the game.', 'jugar', '🎮'),
  ('62236891-5570-b894-2573-1bc82212bb1e', 3, 'Teamwork means working together with my teammates. Passing the ball to someone in a better position to score shows good teamwork. Listening to my coach''s instructions and following them also helps the team work well together.', 'instrucciones', '📋'),
  ('62236891-5570-b894-2573-1bc82212bb1e', 4, 'During a basketball game, players need to communicate with each other using words or hand signals. This helps everyone know where they should be on the court and what play to execute next.', 'juego', '🎲'),
  ('62236891-5570-b894-2573-1bc82212bb1e', 5, 'Remember, it''s not just about scoring points but also about supporting my teammates, encouraging each other, and having fun while playing the game.', 'recordar', '📝'),
  ('62236891-5570-b894-2573-1bc82212bb1e', 6, 'Teamwork is essential in basketball. By working together, listening to our coach, communicating effectively, and supporting our teammates, we can have a great time on the court. Let''s remember to enjoy the game and give our best effort as a team!', 'tiempo', '⏰');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8ee2a93f-1635-0c46-e131-ac74964733b8', 1, 'Saying hello is the first step to making new friends. It''s like opening a door to a conversation and starting a fun adventure.', 'saludar', '👋'),
  ('8ee2a93f-1635-0c46-e131-ac74964733b8', 2, 'When I see someone new, I can say "Hello" or "Hi." I can also smile to show that I am friendly and happy to meet them.', 'ver', '👀'),
  ('8ee2a93f-1635-0c46-e131-ac74964733b8', 3, 'If I want to make it more special, I can add something nice like "How are you?" or "Nice to meet you."', 'querer', '💕'),
  ('8ee2a93f-1635-0c46-e131-ac74964733b8', 4, 'Sometimes, I might feel a little shy, but that''s okay. I can take a deep breath and remind myself that saying hello is a good thing. Everyone likes to be greeted kindly.', 'respirar', '🫁'),
  ('8ee2a93f-1635-0c46-e131-ac74964733b8', 5, 'After saying hello, I can listen to what the other person says. This shows that I care about them and what they have to say. Listening helps me learn more about my new friend.', 'escuchar', '👂'),
  ('8ee2a93f-1635-0c46-e131-ac74964733b8', 6, 'Saying hello is a great way to start a friendship. When I say hello, I am being brave and friendly. My new friend will be happy to hear from me, and we can enjoy getting to know each other.', 'saludar', '👋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a587a41e-0574-e6c4-02aa-23ede3b3199c', 1, 'In our family, everyone has special jobs to do. I also have some special jobs that help our family run smoothly.', 'familia', '👨‍👩‍👧‍👦'),
  ('a587a41e-0574-e6c4-02aa-23ede3b3199c', 2, 'I can help set the table for dinner. This means putting out plates, utensils, and napkins for everyone. It makes me feel good to contribute to our mealtime together.', 'ayuda', '🆘'),
  ('a587a41e-0574-e6c4-02aa-23ede3b3199c', 3, 'Another job I can do is feeding our pet dog, Max. He gets so excited when it''s time to eat! Feeding him is important to keep him healthy and happy.', 'otro', '🔄'),
  ('a587a41e-0574-e6c4-02aa-23ede3b3199c', 4, 'Sometimes, I can help fold laundry with Mom or Dad. Folding clothes neatly and putting them away in the right place helps keep our home organized.', 'a veces', '⏳'),
  ('a587a41e-0574-e6c4-02aa-23ede3b3199c', 5, 'Everyone in our family has special jobs to do. When I help with setting the table, feeding Max, or folding laundry, I am being a helpful member of our family.', 'todos', '🌐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d973f2f6-4c18-e322-1b10-198e26f5465c', 1, 'Sometimes families change. A new baby brother or sister is coming to our family! This means there will be a new person in the house.', 'a veces', '⏳'),
  ('d973f2f6-4c18-e322-1b10-198e26f5465c', 2, 'A new baby needs lots of care and attention. Mom and Dad will spend time taking care of the baby, feeding, changing diapers, and making sure the baby feels loved and safe. They may seem very busy with the baby at first, but they still love me just as much as before. It''s important for everyone to help take care of the baby so that Mom and Dad can have some rest too. I might get to help by bringing diapers, singing songs, or playing quietly while the baby sleeps.', 'nuevo', '🆕'),
  ('d973f2f6-4c18-e322-1b10-198e26f5465c', 3, 'It’s okay if I feel different about having a new baby in the family. Sometimes I might feel happy, excited, curious, or even worried. These feelings are normal, and it’s okay to talk about them with my parents or another grown-up I trust. I can ask questions about the baby and share my feelings with someone who listens carefully.', 'sentir', '💓'),
  ('d973f2f6-4c18-e322-1b10-198e26f5465c', 4, 'Having a new baby brother or sister is a big change, but it also brings new opportunities for fun and learning. I can be a good helper and a great big brother or sister. Mom and Dad will make sure we all have special time together, and I will always be an important part of the family.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c65f2146-6adf-8d5b-610d-8aea44b07649', 1, 'I have many interests and things that I enjoy doing. It''s important for me to be able to talk about my interests with others.', 'muchos', '✨'),
  ('c65f2146-6adf-8d5b-610d-8aea44b07649', 2, 'When I talk about my interests, it helps other people understand what makes me happy. Sometimes, I might want to tell someone about a new game I like to play or a book I''ve been reading. When I share my interests, it can help me make friends who like the same things as me.', 'hablar', '🗣️'),
  ('c65f2146-6adf-8d5b-610d-8aea44b07649', 3, 'It''s okay if not everyone shares my interests, but talking about them can help others get to know me better. If I''m excited about something, I can use words to explain why I like it. This way, others can learn more about what I enjoy.', 'todos', '🌐'),
  ('c65f2146-6adf-8d5b-610d-8aea44b07649', 4, 'Sometimes, I might feel nervous about talking about my interests, but it''s good to practice sharing them with others. I can start by telling a family member or a friend about something I like, and then gradually become more comfortable talking about my interests with different people.', 'a veces', '⏳'),
  ('c65f2146-6adf-8d5b-610d-8aea44b07649', 5, 'Talking about my interests is a great way to connect with others and share what makes me happy. I will keep practicing and feel proud when I talk about the things I love.', 'forma', '📐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('bb50f577-e80d-fcb2-4dfa-9bab236af2ca', 1, 'Online learning platforms are places where I can learn new things using a computer or tablet. These platforms have special tools and activities to help me understand different subjects.', 'aprender', '📖'),
  ('bb50f577-e80d-fcb2-4dfa-9bab236af2ca', 2, 'When I use an online learning platform, it''s important to follow the instructions from my teacher or parent. They may ask me to watch videos, read stories, or answer questions. It''s also important to be patient and try my best, even if something is difficult. If I need help, I can ask my teacher or parent for assistance.', 'instrucciones', '📋'),
  ('bb50f577-e80d-fcb2-4dfa-9bab236af2ca', 3, 'Sometimes, there might be other students on the platform with me. I should always be kind and respectful to them, just like I would in a classroom. If someone is unkind to me, I can tell my teacher or parent so they can help.', 'a veces', '⏳'),
  ('bb50f577-e80d-fcb2-4dfa-9bab236af2ca', 4, 'I am excited to learn new things on online learning platforms. I will listen to my teacher or parent, be patient, and treat others with kindness and respect.', 'escuchar', '👂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5d7e9ba4-5944-7dba-fd57-4ca2e40c9488', 1, 'When I want to do exercise, it''s important to stretch and warm up my body.', 'querer', '💕'),
  ('5d7e9ba4-5944-7dba-fd57-4ca2e40c9488', 2, 'Before starting any exercise, I need to make sure my muscles are ready. I can start by stretching my arms, legs, and back. This helps my muscles get flexible and prevents them from getting hurt during the exercise. After stretching, I can do some light movements like jogging in place or jumping jacks. This will help my heart rate increase slowly and prepare my body for more intense activities.', 'ejercicio', '🏋️'),
  ('5d7e9ba4-5944-7dba-fd57-4ca2e40c9488', 3, 'It''s important to remember that warming up is not just for athletes. It''s for everyone who wants to keep their body safe and healthy while exercising. When I take care of my body, I can enjoy exercise even more!', 'importante', '❗'),
  ('5d7e9ba4-5944-7dba-fd57-4ca2e40c9488', 4, 'I will always remember to stretch and warm up before doing any exercise. It keeps me safe and makes my body feel great!', 'siempre', '♾️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 1, 'Handling criticism from adults is a skill that can be learned.', 'feliz', '😊'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 2, 'It''s important to stay calm and listen, even if at first it feels churned.', 'importante', '❗'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 3, 'Criticism is when someone tells me what they think could be improved.', 'alguien', '✨'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 4, 'It''s not always easy to hear, but it helps us grow, so it''s proved.', 'siempre', '♾️'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 5, 'When an adult gives feedback, take a deep breath and pause.', 'respirar', '🫁'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 6, 'Listen carefully to what they say, and consider it without any flaws.', 'escuchar', '👂'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 7, 'Handling criticism from adults is part of learning and growing each day.', 'aprender', '📖'),
  ('e0c9fe52-b627-ed79-eecb-d571707c0b75', 8, 'By staying calm and open-minded, I can take their words in a positive way.', 'tranquilo', '🧘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0f2be504-d9f6-a7d1-a652-78645d76fe3d', 1, 'There are times for play and times for work. This is important to understand.', 'jugar', '🎮'),
  ('0f2be504-d9f6-a7d1-a652-78645d76fe3d', 2, 'Playtime is when I can have fun, relax, and enjoy myself. It''s a time for toys, games, and laughter. Work time is when I need to focus, learn, and complete tasks. It''s a time for responsibility and getting things done.', 'divertido', '😄'),
  ('0f2be504-d9f6-a7d1-a652-78645d76fe3d', 3, 'When it''s playtime, I can choose my favorite toy or game. I can run around, draw pictures, or build with blocks. Playtime is a chance to let my imagination soar and have a good time.', 'elegir', '✅'),
  ('0f2be504-d9f6-a7d1-a652-78645d76fe3d', 4, 'During work time, I listen to my teacher or parents. I follow instructions, complete my schoolwork, and help out at home. Work time helps me learn new things, be responsible, and feel proud of my accomplishments.', 'escuchar', '👂'),
  ('0f2be504-d9f6-a7d1-a652-78645d76fe3d', 5, 'Understanding the difference between playtime and work time is important. Playtime is for fun, while work time is for learning and being responsible. I will remember that there is a time for play and a time for work.', 'trabajar', '💼');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a5f7df39-2e30-746b-68be-61229dc10bd8', 1, 'Respecting elders in the community is important. Elders are people who have lived longer and have a lot of wisdom to share with us.', 'importante', '❗'),
  ('a5f7df39-2e30-746b-68be-61229dc10bd8', 2, 'When we see an elder, we can greet them politely by saying "hello" or "good morning." If they need help carrying something or crossing the street, we can offer our assistance.', 'ver', '👀'),
  ('a5f7df39-2e30-746b-68be-61229dc10bd8', 3, 'Elders like to talk about their experiences and stories. We can listen attentively and show interest in what they have to say. Sometimes, they may tell us interesting things that we never knew before.', 'gustar', '👍'),
  ('a5f7df39-2e30-746b-68be-61229dc10bd8', 4, 'If we ever disagree with an elder, it''s important to express our thoughts respectfully and calmly. We can say, "I understand your point of view, but I see it differently."', 'importante', '❗'),
  ('a5f7df39-2e30-746b-68be-61229dc10bd8', 5, 'Respecting elders in the community shows kindness and consideration. It helps us build positive relationships and learn from the valuable experiences they have had.', 'construir', '🔨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2c0f108d-5ea6-2612-d72d-d4f3cbe0d6a9', 1, 'Friendship is a special bond between people. It''s about caring for each other and having fun together.', 'amistad', '🤝'),
  ('2c0f108d-5ea6-2612-d72d-d4f3cbe0d6a9', 2, 'When I have a friend, we can share toys, play games, or talk about things we like. Sometimes, friends may feel happy, sad, excited, or even upset. It''s okay to have different feelings; that''s what makes us unique.', 'amigo', '🤝'),
  ('2c0f108d-5ea6-2612-d72d-d4f3cbe0d6a9', 3, 'If my friend is feeling sad, I can try to cheer them up by being kind and listening to them. If I''m the one feeling down, it''s okay to tell my friend how I feel so they can help me feel better.', 'amigo', '🤝'),
  ('2c0f108d-5ea6-2612-d72d-d4f3cbe0d6a9', 4, 'Sometimes, friends may disagree or argue. It''s important to talk calmly and listen to each other''s feelings. We can find solutions together and make up after a disagreement.', 'escuchar', '👂'),
  ('2c0f108d-5ea6-2612-d72d-d4f3cbe0d6a9', 5, 'Having friends means sharing good times and supporting each other through challenges. I will be a good friend by showing kindness, understanding emotions, and working together to keep our friendship strong.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9ad396ef-86ae-07b3-a4bd-37662b0eee51', 1, 'Empathy means understanding how someone else feels. It''s important to practice empathy when there is a disagreement or conflict.', 'alguien', '✨'),
  ('9ad396ef-86ae-07b3-a4bd-37662b0eee51', 2, 'When my friend is upset, I can try to understand why. Maybe they wanted to play with the toy first, or maybe they are feeling sad about something else. I can listen and show that I care about their feelings.', 'amigo', '🤝'),
  ('9ad396ef-86ae-07b3-a4bd-37662b0eee51', 3, 'If I accidentally hurt someone''s feelings, I can say sorry and ask if they are okay. This shows that I care about them and want to make things better.', 'alguien', '✨'),
  ('9ad396ef-86ae-07b3-a4bd-37662b0eee51', 4, 'Sometimes, I might feel upset too. It''s okay to tell an adult if I need help to solve the problem. They can help us find a solution that makes everyone feel better.', 'a veces', '⏳'),
  ('9ad396ef-86ae-07b3-a4bd-37662b0eee51', 5, 'Practicing empathy helps me understand others and build good relationships. When we care about each other''s feelings, we can work together to solve problems peacefully.', 'entender', '🧠');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6238916a-514f-2171-1a6e-80595f8871bb', 1, 'When we face a problem, it''s like solving a puzzle. We need to think about different ways to find the best solution.', 'cara', '😐'),
  ('6238916a-514f-2171-1a6e-80595f8871bb', 2, 'There are many ways to solve problems. Some solutions work better than others. To figure out what works best, we can try different ideas and see which one helps us the most.', 'muchos', '✨'),
  ('6238916a-514f-2171-1a6e-80595f8871bb', 3, 'One way is to talk to someone we trust, like a parent or teacher. They can help us come up with good ideas.', 'forma', '📐'),
  ('6238916a-514f-2171-1a6e-80595f8871bb', 4, 'Another way is to think about similar problems we''ve solved before. What did we do then? Did it work?', 'otro', '🔄'),
  ('6238916a-514f-2171-1a6e-80595f8871bb', 5, 'We can also take a break if we feel stuck. Sometimes stepping away for a bit can give us new ideas.', 'sentir', '💓'),
  ('6238916a-514f-2171-1a6e-80595f8871bb', 6, 'Remember, it''s okay if the first solution doesn''t work. We can always try another one until we find what works best.', 'recordar', '📝'),
  ('6238916a-514f-2171-1a6e-80595f8871bb', 7, 'By trying different solutions and evaluating what works best, we become better at solving problems. It''s like being a detective, searching for clues until we crack the case. Let''s keep exploring and learning together!', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d7ce5ce1-442a-e5ba-fe22-1abbffed390f', 1, 'When I use the internet, it''s important to be kind. Just like in real life, being kind online means treating others with respect and making good choices.', 'importante', '❗'),
  ('d7ce5ce1-442a-e5ba-fe22-1abbffed390f', 2, 'I can be kind on the internet by using polite words when I talk to others. If someone sends me a message or comment, I can respond with nice words. It''s also important not to say mean things or make fun of others online. Treating people the way I want to be treated is always a good idea, whether it''s in person or on the internet.', 'amable', '💝'),
  ('d7ce5ce1-442a-e5ba-fe22-1abbffed390f', 3, 'Another way to be kind is to ask for permission before sharing someone else''s pictures or information. I should only share my own pictures and information if my parents say it''s okay. This helps keep everyone safe and respectful online.', 'otro', '🔄'),
  ('d7ce5ce1-442a-e5ba-fe22-1abbffed390f', 4, 'If I see something that makes me feel uncomfortable or upset, I can tell a trusted adult about it. They can help me understand what to do and how to handle the situation. It''s okay to ask for help when I need it.', 'ayuda', '🆘'),
  ('d7ce5ce1-442a-e5ba-fe22-1abbffed390f', 5, 'Being kind on the internet means using polite words, respecting others'' privacy, and asking for help when needed. When I am kind online, I help create a positive and safe environment for everyone.', 'amable', '💝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0056352d-b220-81a8-5d49-bdf3c30d1b55', 1, 'Being a good friend means showing empathy and understanding when our friends are upset. Empathy is when we try to understand how someone else feels, even if we haven''t experienced the same thing.', 'bien', '👍'),
  ('0056352d-b220-81a8-5d49-bdf3c30d1b55', 2, 'Sometimes, our friends may feel sad, angry, or frustrated. It''s important to listen to them and let them know that we care. We can say things like, "I''m sorry you''re feeling this way" or "Is there anything I can do to help?"', 'escuchar', '👂'),
  ('0056352d-b220-81a8-5d49-bdf3c30d1b55', 3, 'When our friends are upset, it''s important not to make fun of them or ignore their feelings. Instead, we can offer support by saying, "I''m here for you" or "You''re not alone." Sometimes, just being there and listening is enough to make our friends feel better.', 'amigos', '🤝'),
  ('0056352d-b220-81a8-5d49-bdf3c30d1b55', 4, 'We can also show empathy by trying to imagine how our friends might be feeling. For example, if they didn''t get invited to a party, we can say, "That must have made you feel left out. I would feel the same way."', 'amigos', '🤝'),
  ('0056352d-b220-81a8-5d49-bdf3c30d1b55', 5, 'Being empathetic towards our friends helps us build stronger friendships. When we show understanding and support, our friends will trust us and feel comfortable talking to us about their feelings. Let''s remember to be kind and caring when our friends are upset.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('bbfdba3f-ef3b-3921-c131-714c4ce4691c', 1, 'Nap time is a special moment during the day for resting and recharging.', 'tiempo', '⏰'),
  ('bbfdba3f-ef3b-3921-c131-714c4ce4691c', 2, 'When it''s nap time, I can lie down on my bed or cozy spot. I can close my eyes and take deep breaths. It''s okay to have a favorite blanket or stuffed animal with me.', 'respirar', '🫁'),
  ('bbfdba3f-ef3b-3921-c131-714c4ce4691c', 3, 'I can think of happy thoughts or listen to calming music. This helps me relax and feel peaceful. Nap time is a quiet time for my body and mind to rest.', 'escuchar', '👂'),
  ('bbfdba3f-ef3b-3921-c131-714c4ce4691c', 4, 'After nap time, I will feel refreshed and ready for more fun activities.', 'tiempo', '⏰'),
  ('bbfdba3f-ef3b-3921-c131-714c4ce4691c', 5, 'Nap time is a special moment during the day for resting and recharging.', 'tiempo', '⏰');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4e1369aa-1d9e-a836-8677-5be1f46c29c0', 1, 'Everyone is different in their own special way. Some people can do things easily that others find hard to do. This is because we all have different abilities. Abilities are the things we are good at doing, like singing, drawing, or running. Disabilities are when someone finds it harder to do certain things, like seeing, hearing, or moving around.', 'todos', '🌐'),
  ('4e1369aa-1d9e-a836-8677-5be1f46c29c0', 2, 'Abilities and disabilities make each person unique. For example, some people may use a wheelchair to help them move around because their legs don’t work as well. Others might need glasses to see clearly. It’s important to remember that just because someone has a disability doesn’t mean they can’t do amazing things too! They just might do things differently.', 'persona', '🧑'),
  ('4e1369aa-1d9e-a836-8677-5be1f46c29c0', 3, 'When we learn about abilities and disabilities, we become more understanding and kind towards others. We can offer help if someone needs it, or simply be patient and supportive. By respecting everyone''s differences, we create a world where everyone feels accepted and valued for who they are.', 'aprender', '📖'),
  ('4e1369aa-1d9e-a836-8677-5be1f46c29c0', 4, 'Understanding abilities and disabilities helps us appreciate the diversity in our world. We should treat everyone with kindness and respect, no matter what challenges they may face. Each person''s unique abilities contribute to making our world a brighter and richer place.', 'mundo', '🌍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f4b2d353-969a-0821-a96c-73149a8c7a8a', 1, 'Being part of a team is exciting! When we work together, we can achieve great things.', 'equipo', '👥'),
  ('f4b2d353-969a-0821-a96c-73149a8c7a8a', 2, 'In our class, we have many opportunities to be part of a team. We play games, do projects, and learn new things together. It''s important to remember that being on a team means we all have different strengths and abilities. Some of us are good at math, while others are great artists or excellent problem solvers.', 'clase', '📚'),
  ('f4b2d353-969a-0821-a96c-73149a8c7a8a', 3, 'When we work as a team, we support each other and celebrate our successes. We listen to each other''s ideas and take turns sharing our thoughts. Sometimes, we may not agree with everyone, but it''s okay because we respect each other''s opinions.', 'esperar', '⏳'),
  ('f4b2d353-969a-0821-a96c-73149a8c7a8a', 4, 'Cooperation is key when working in a team. We help each other out and share the workload. If someone needs assistance, we offer a helping hand without hesitation. Together, we can accomplish more than we could alone.', 'equipo', '👥'),
  ('f4b2d353-969a-0821-a96c-73149a8c7a8a', 5, 'Patience is also important when working as a team. We understand that not everything will go smoothly all the time. There may be challenges along the way, but we stay calm and work through them together. We encourage each other and never give up.', 'paciencia', '🧘'),
  ('f4b2d353-969a-0821-a96c-73149a8c7a8a', 6, 'As a team, we celebrate our successes and learn from our mistakes. We know that by working together, we can achieve amazing things. Let''s continue to support and uplift each other as we grow and learn as a team.', 'equipo', '👥');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fea7c113-2670-5045-5077-a812c6474c3a', 1, 'Taking turns means waiting for my chance to do something when others are also waiting. It’s like playing a game where everyone gets a fair opportunity to participate.', 'esperar', '⏳'),
  ('fea7c113-2670-5045-5077-a812c6474c3a', 2, 'When we take turns, it helps us share and be patient. Sharing is when we let others have a chance too. Being patient means waiting calmly without getting upset or frustrated. Taking turns shows kindness and respect towards each other.', 'esperar', '⏳'),
  ('fea7c113-2670-5045-5077-a812c6474c3a', 3, 'Sometimes taking turns can be hard because we might feel excited or eager to go next. But remember, everyone deserves a turn, just like I do. When we wait our turn, it makes the activity more enjoyable for everyone involved.', 'a veces', '⏳'),
  ('fea7c113-2670-5045-5077-a812c6474c3a', 4, 'So, when it''s time to take turns, I will remember to be patient and kind. I will wait for my turn with a smile on my face, knowing that sharing and patience make friendships stronger.', 'esperar', '⏳');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('58089cba-34ad-7b01-06d4-53d9511c0576', 1, 'I love playing sports and being part of a team. It''s important to remember that celebrating victories respectfully is just as important as winning the game.', 'jugar', '🎮'),
  ('58089cba-34ad-7b01-06d4-53d9511c0576', 2, 'When my team wins a game, it feels amazing! We all worked hard together and achieved something great. But it''s important to celebrate in a way that shows respect for the other team and their efforts.', 'equipo', '👥'),
  ('58089cba-34ad-7b01-06d4-53d9511c0576', 3, 'We can cheer and high-five our teammates, but we should also shake hands with the opposing team and say "good game." This shows that we appreciate their effort and sportsmanship.', 'deber', '📋'),
  ('58089cba-34ad-7b01-06d4-53d9511c0576', 4, 'Sometimes, when we win, we might feel really excited and want to brag or show off. But it''s important to remember that being humble and respectful is more important than boasting about our victory.', 'a veces', '⏳'),
  ('58089cba-34ad-7b01-06d4-53d9511c0576', 5, 'If the other team wins, we should still congratulate them and be good sports. We can learn from our losses and use them as motivation to improve for the next game.', 'otro', '🔄'),
  ('58089cba-34ad-7b01-06d4-53d9511c0576', 6, 'Celebrating victories respectfully means showing appreciation for both our own team''s success and the efforts of the opposing team. Let''s always remember to be humble, congratulate others, and be good sports, whether we win or lose.', 'propio', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('500ea0b8-825e-81d7-76c6-7896bb1924c4', 1, 'My place in the community is important. I am learning about different places and how to be comfortable in them.', 'lugar', '📍'),
  ('500ea0b8-825e-81d7-76c6-7896bb1924c4', 2, 'In my community, there are many places like stores, restaurants, parks, and schools. Sometimes these places can get busy. When a place is busy, it means there are a lot of people moving around, and sometimes it may feel crowded. There might also be long lines, and it could be noisy with lots of sounds.', 'muchos', '✨'),
  ('500ea0b8-825e-81d7-76c6-7896bb1924c4', 3, 'When a place is busy, it''s okay to feel a little overwhelmed or unsure. It''s important to remember that everyone feels this way sometimes, not just me. If I need to, I can take a break and find a quiet spot to relax for a bit.', 'lugar', '📍'),
  ('500ea0b8-825e-81d7-76c6-7896bb1924c4', 4, 'Sometimes, when a place is too busy, my family might decide to come back later or visit another time when it''s less crowded. This helps make our visit more enjoyable and less stressful.', 'a veces', '⏳'),
  ('500ea0b8-825e-81d7-76c6-7896bb1924c4', 5, 'My place in the community is wherever I feel safe and comfortable. It''s okay if some places are too busy for me. I can always come back another time when it''s better for me.', 'lugar', '📍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('912f3499-2537-55b1-4e5f-749cb79748f5', 1, 'Celebrating successes and achievements is an important part of life. It means recognizing when we have done something well or accomplished a goal. When we celebrate, it makes us feel happy and proud. We can celebrate big things like winning a game or small things like finishing our homework on time.', 'importante', '❗'),
  ('912f3499-2537-55b1-4e5f-749cb79748f5', 2, 'We celebrate successes in different ways. Sometimes, we clap our hands or give high-fives to show that we are proud of ourselves or someone else. Other times, we might get a special treat or go somewhere fun as a reward for our hard work.', 'celebrar', '🎊'),
  ('912f3499-2537-55b1-4e5f-749cb79748f5', 3, 'When we achieve something, it''s important to take a moment to acknowledge our efforts and the progress we''ve made. Even if things were difficult at first, celebrating shows that we have tried our best and overcome challenges along the way.', 'importante', '❗'),
  ('912f3499-2537-55b1-4e5f-749cb79748f5', 4, 'It''s also nice to celebrate with others. Sharing our successes with friends and family can make the moment even more special. They can cheer us on and share in our happiness, making the celebration even more joyful.', 'amable', '💝'),
  ('912f3499-2537-55b1-4e5f-749cb79748f5', 5, 'Celebrating successes and achievements is a wonderful way to recognize our hard work and dedication. Whether big or small, each success deserves to be acknowledged and celebrated. So let''s remember to celebrate our accomplishments and be proud of all that we have achieved!', 'forma', '📐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('ee076ff5-9dab-fa1c-61ad-8e1fad85237f', 1, 'Welcoming a new baby into the family is an exciting time for everyone. A new baby brings joy and changes to our family.', 'nuevo', '🆕'),
  ('ee076ff5-9dab-fa1c-61ad-8e1fad85237f', 2, 'When a new baby comes home, they need lots of care and attention. Babies cry when they are hungry, tired, or need a diaper change. They like to be held gently and rocked to sleep.', 'nuevo', '🆕'),
  ('ee076ff5-9dab-fa1c-61ad-8e1fad85237f', 3, 'As the big brother or sister, I can help take care of the new baby by being gentle and quiet around them. I can also show love by giving hugs and kisses to the baby.', 'hermano', '👦'),
  ('ee076ff5-9dab-fa1c-61ad-8e1fad85237f', 4, 'Sometimes, babies may cry a lot, and it''s okay to feel a little jealous because they need a lot of attention. It''s important to talk about these feelings with mom and dad so they can help me understand that it''s normal to have mixed emotions.', 'a veces', '⏳'),
  ('ee076ff5-9dab-fa1c-61ad-8e1fad85237f', 5, 'Welcoming a new baby into the family means more love and fun times together. Being a caring and helpful big brother or sister will make the new baby feel safe and loved in our family.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8c9362ae-390e-7eef-ff5b-8f37d187b97d', 1, 'Volunteering in our community is a way to help others and make a positive impact. It means giving our time and effort to support those who need it. When we volunteer, we show kindness and care for the people around us.', 'forma', '📐'),
  ('8c9362ae-390e-7eef-ff5b-8f37d187b97d', 2, 'When we volunteer, we can do many different things to help others. We might clean up a park, visit elderly neighbors, or collect donations for those in need. Volunteering allows us to connect with our community and build friendships while making a difference.', 'muchos', '✨'),
  ('8c9362ae-390e-7eef-ff5b-8f37d187b97d', 3, 'Sometimes, volunteering may involve tasks that are new or challenging. It''s okay to feel unsure at first, but remember that every small act of kindness counts. By working together as a team, we can achieve great things and create a better world for everyone.', 'a veces', '⏳'),
  ('8c9362ae-390e-7eef-ff5b-8f37d187b97d', 4, 'Volunteering in our community is a special way to show compassion and generosity. Just like how we work together on Trevor’s Team, we can also join hands with others in our community to spread positivity and support each other. Let''s explore opportunities to volunteer and make a difference in the lives of those around us.', 'especial', '⭐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3ac9a99e-cf68-9017-6d94-91bd02050e8a', 1, 'CREATING LASTING MEMORIES THROUGH CELEBRATIONS', 'feliz', '😊'),
  ('3ac9a99e-cf68-9017-6d94-91bd02050e8a', 2, 'This is a very special chapter. Together, the Stories in this chapter describe how to create lasting memories through celebrations. It is important to begin with some information.', 'muy', '💯'),
  ('3ac9a99e-cf68-9017-6d94-91bd02050e8a', 3, 'Celebrations are times when people come together to share joy and happiness. During celebrations, people give and receive gifts as a way of showing love and appreciation for each other. Sometimes, there are decorations, music, and delicious food to enjoy. People may also play games and spend time talking and laughing with each other.', 'personas', '👥'),
  ('3ac9a99e-cf68-9017-6d94-91bd02050e8a', 4, 'When it''s someone''s birthday, we celebrate their life and all the wonderful things about them. We show our love by giving them presents and sharing happy moments together. When it''s a holiday like Christmas or Eid, we celebrate traditions and the spirit of giving. These celebrations help us feel connected to our family and friends.', 'alguien', '✨'),
  ('3ac9a99e-cf68-9017-6d94-91bd02050e8a', 5, 'Creating lasting memories through celebrations will bring joy and warmth to my heart. My loved ones and I will cherish these moments forever. Together, we will make every celebration special and full of love.', 'alegria', '🎉');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8c9c2908-ffb4-0ad5-5614-d340d8d0979f', 1, 'Empathy and compassion are important qualities that help us understand and care for others. Sometimes, people may act unkindly or hurtful towards us. It can be difficult to understand why they behave this way. But by looking beyond their actions, we can find empathy and compassion within ourselves.', 'importante', '❗'),
  ('8c9c2908-ffb4-0ad5-5614-d340d8d0979f', 2, 'When someone is being mean or bullying, it''s important to remember that they might be going through something difficult themselves. They may feel sad, angry, or scared, and they don''t know how to express those feelings in a positive way. Instead, they choose to hurt others.', 'alguien', '✨'),
  ('8c9c2908-ffb4-0ad5-5614-d340d8d0979f', 3, 'It''s not our fault if someone bullies us. We didn''t do anything wrong. The bully''s behavior says more about them than it does about us.', 'alguien', '✨'),
  ('8c9c2908-ffb4-0ad5-5614-d340d8d0979f', 4, 'If someone is being mean to me, I can try to respond with kindness. I can say things like, "I''m sorry you''re feeling upset" or "Is there something bothering you?" This shows the bully that I see beyond their hurtful actions and that I care about their well-being.', 'alguien', '✨'),
  ('8c9c2908-ffb4-0ad5-5614-d340d8d0979f', 5, 'Sometimes, it''s best to walk away from the situation and find a trusted adult who can help. They can provide support and guidance on how to handle the situation. Remember, it takes strength to ask for help.', 'ayuda', '🆘'),
  ('8c9c2908-ffb4-0ad5-5614-d340d8d0979f', 6, 'Empathy and compassion allow us to see beyond the bully''s actions and understand that they may be struggling too. By responding with kindness and seeking help when needed, we can create a safer and more compassionate environment for everyone. Let''s remember to treat others with respect and understanding, even when faced with challenging situations.', 'ver', '👀');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1d56a83b-5699-7ca2-898a-2556e25f9324', 1, 'Understanding consequences is an important skill. Consequences are what happen as a result of our actions.', 'importante', '❗'),
  ('1d56a83b-5699-7ca2-898a-2556e25f9324', 2, 'When we make good choices, positive consequences usually follow. For example, if I do my homework, the consequence is that I will learn new things and get better at school. If I am kind to others, the consequence may be that they want to spend time with me.', 'bien', '👍'),
  ('1d56a83b-5699-7ca2-898a-2556e25f9324', 3, 'On the other hand, when we make not-so-good choices, there may be negative consequences. For instance, if I don’t listen to my teacher, the consequence might be missing out on fun activities or getting into trouble. If I break something, the consequence could be having to fix it or replace it.', 'escuchar', '👂'),
  ('1d56a83b-5699-7ca2-898a-2556e25f9324', 4, 'It’s important to think about the consequences before making a choice. My Team can help me understand the possible outcomes of different choices. They can also help me learn from any mistakes I make so that I can make better choices in the future.', 'importante', '❗'),
  ('1d56a83b-5699-7ca2-898a-2556e25f9324', 5, 'Understanding consequences helps me make good choices and have positive experiences. My Team will support me in understanding and learning from the consequences of my actions.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('175dd385-4cb7-4c35-8cdb-066aca3c1cb5', 1, 'Hello, my name is Sarah. Sometimes I feel strong emotions that are hard to understand and manage. These emotions can be like big waves that make me feel overwhelmed. It’s important for me to learn how to navigate these emotional triggers.', 'saludar', '👋'),
  ('175dd385-4cb7-4c35-8cdb-066aca3c1cb5', 2, 'When something happens that makes me feel upset or scared, it''s called an emotional trigger. Emotional triggers can be different for everyone. For some people, it might be a loud noise, a change in routine, or feeling misunderstood. When I experience an emotional trigger, it can be really hard to stay calm and think clearly.', 'sentir', '💓'),
  ('175dd385-4cb7-4c35-8cdb-066aca3c1cb5', 3, 'It’s okay to feel this way. Many people have emotional triggers, and it’s normal to feel overwhelmed sometimes. What’s important is learning how to recognize when we’re triggered and finding ways to calm down. This could be taking deep breaths, counting to ten, or finding a quiet space to relax.', 'respirar', '🫁'),
  ('175dd385-4cb7-4c35-8cdb-066aca3c1cb5', 4, 'Navigating emotional triggers means understanding what makes us feel upset or scared and finding healthy ways to cope with those feelings. It’s okay to ask for help from a trusted adult if we need support. Learning about our emotional triggers helps us build resilience and become better at managing our emotions.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 1, 'Our weekly planner helps us know what to expect each day.', 'saber', '🧠'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 2, 'Every Sunday, we sit down with our weekly planner. The planner has all the days of the week listed. We talk about what will happen each day.', 'sentarse', '🪑'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 3, 'On Monday, I have school in the morning. After school, it’s time for snack and then playtime. Then, dinner and bedtime routine.', 'escuela', '🏫'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 4, 'Tuesday is different. I have therapy after school. It''s important because it helps me learn new things. When I come home, I get to relax and watch my favorite show.', 'diferente', '🌈'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 5, 'Wednesday is a fun day because we go to the park. I love playing on the swings and slides. In the evening, we have family game night.', 'divertido', '😄'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 6, 'Thursday is another school day. I have art class, which is my favorite. After that, we visit grandma and grandpa.', 'otro', '🔄'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 7, 'Friday is special because it''s pizza night! We order pizza and watch a movie together as a family.', 'especial', '⭐'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 8, 'Saturday is when we do something fun as a family. Sometimes we go to the zoo or have a picnic at the park.', 'divertido', '😄'),
  ('4fd3bdfd-75b7-5df9-8554-2ec5c3c30aa6', 9, 'Our weekly planner helps me feel prepared and less anxious about what comes next. I like knowing what to expect each day.', 'sentir', '💓');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fe7eaf51-c6f5-93aa-dc12-7688b0b21b27', 1, 'Fear is a feeling that everyone experiences at some point. It''s like when I see a big dog barking loudly or hear thunder during a storm.', 'miedo', '😨'),
  ('fe7eaf51-c6f5-93aa-dc12-7688b0b21b27', 2, 'When we feel scared, our bodies might shake, and our hearts may beat fast. We might want to run away or hide. But it''s important to remember that fear is a normal emotion.', 'sentir', '💓'),
  ('fe7eaf51-c6f5-93aa-dc12-7688b0b21b27', 3, 'To overcome scary situations, we can take deep breaths and tell ourselves, "I am safe." We can also ask for help from someone we trust, like a parent or teacher. They can comfort us and make us feel better.', 'respirar', '🫁'),
  ('fe7eaf51-c6f5-93aa-dc12-7688b0b21b27', 4, 'Facing our fears helps us become stronger and braver. It''s okay to be scared sometimes, but we can learn to manage our fears and not let them control us.', 'miedo', '😨'),
  ('fe7eaf51-c6f5-93aa-dc12-7688b0b21b27', 5, 'Remember, it''s normal to feel scared sometimes. By taking deep breaths, seeking help, and facing our fears, we can navigate through scary situations and grow stronger.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fcb183ac-1dd9-cae6-f8d2-827f1eeca5e0', 1, 'Empathy is when we understand and care about how other people feel. It''s important to show empathy and care for others.', 'entender', '🧠'),
  ('fcb183ac-1dd9-cae6-f8d2-827f1eeca5e0', 2, 'When someone is sad, we can comfort them by giving them a hug or saying kind words. If someone is hurt, we can help them by getting a bandage or telling an adult. When someone is happy, we can celebrate with them by smiling and sharing in their joy.', 'alguien', '✨'),
  ('fcb183ac-1dd9-cae6-f8d2-827f1eeca5e0', 3, 'We can also show empathy by listening to others when they talk about their feelings. This helps them know that we care about what they are going through.', 'hablar', '🗣️'),
  ('fcb183ac-1dd9-cae6-f8d2-827f1eeca5e0', 4, 'It feels good to show empathy and care for others. I will try to be understanding and caring towards others'' feelings.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3ebabac5-849f-012b-3b0c-95a08e2a4992', 1, 'Waiting in line is something we do when we want to get or do something. It''s important to wait our turn.', 'esperar', '⏳'),
  ('3ebabac5-849f-012b-3b0c-95a08e2a4992', 2, 'When we are in a line, we stand behind the person who is in front of us. We can look around and see what others are doing while we wait.', 'levantarse', '🧍'),
  ('3ebabac5-849f-012b-3b0c-95a08e2a4992', 3, 'Sometimes waiting feels long, but it helps if we stay calm and patient. We can think about fun things or count quietly in our heads.', 'a veces', '⏳'),
  ('3ebabac5-849f-012b-3b0c-95a08e2a4992', 4, 'It''s nice to use polite words like "Excuse me" or "Thank you" when we need to move past someone or when it''s our turn.', 'gracias', '🙏'),
  ('3ebabac5-849f-012b-3b0c-95a08e2a4992', 5, 'Waiting in line with patience means being respectful to others and showing good manners. I will try to wait in line. My family will be proud of me for being patient and polite!', 'esperar', '⏳');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('18f55251-38a0-e999-696e-c034db53eb23', 1, 'Playing games and sports can be a lot of fun. It''s important to remember that being part of a team means supporting each other, whether we win or lose. Today, let''s talk about how we can encourage others during games.', 'jugar', '🎮'),
  ('18f55251-38a0-e999-696e-c034db53eb23', 2, 'Encouraging others means cheering them on and showing support. When my friend makes a good play, I can say things like, "Great job!" or "You''re doing awesome!" This helps them feel proud of themselves and keeps the game positive for everyone.', 'amigo', '🤝'),
  ('18f55251-38a0-e999-696e-c034db53eb23', 3, 'If someone on my team is feeling down because they made a mistake, I can help by saying something like, "It''s okay, we all make mistakes sometimes. Let''s keep trying our best." My words can make a big difference in how they feel.', 'error', '💪'),
  ('18f55251-38a0-e999-696e-c034db53eb23', 4, 'During games, it''s important to stay positive and show good sportsmanship. This means playing fair, following the rules, and respecting both my teammates and opponents. Remember, winning isn''t everything; having fun and doing my best are what truly matter.', 'instrucciones', '📋'),
  ('18f55251-38a0-e999-696e-c034db53eb23', 5, 'When I see someone feeling discouraged or left out, I can offer to include them in the game or give them a high-five to show that I care. Small gestures of kindness go a long way in making everyone feel valued and included.', 'ver', '👀'),
  ('18f55251-38a0-e999-696e-c034db53eb23', 6, 'Encouraging others during games is a great way to build teamwork and create a positive environment for everyone. By supporting each other, we can enjoy playing together and learn important values like fairness and respect. So, let''s cheer each other on and have a blast while staying active and having fun!', 'juegos', '🎲');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6664ff42-f7fe-3d47-208d-e5f25eff3902', 1, 'Finding quiet spaces in busy environments can help me feel calm and safe.', 'silencio', '🔇'),
  ('6664ff42-f7fe-3d47-208d-e5f25eff3902', 2, 'I may find a quiet space in the library, where people read quietly and there are comfy chairs to sit on.', 'silencio', '🔇'),
  ('6664ff42-f7fe-3d47-208d-e5f25eff3902', 3, 'I may find a quiet space in a park, away from the noise of the playground, where I can listen to the birds and feel the breeze.', 'escuchar', '👂'),
  ('6664ff42-f7fe-3d47-208d-e5f25eff3902', 4, 'I may find a quiet space at home, in my room with soft lighting and my favorite toys or books.', 'silencio', '🔇'),
  ('6664ff42-f7fe-3d47-208d-e5f25eff3902', 5, 'Sometimes, I may need to ask for a quiet space if I''m feeling overwhelmed in a crowded place. It''s okay to take a break and find a peaceful spot to relax.', 'a veces', '⏳'),
  ('6664ff42-f7fe-3d47-208d-e5f25eff3902', 6, 'Finding quiet spaces in busy environments helps me stay calm and comfortable. When I need a break, I can look for a quiet space to feel better.', 'silencio', '🔇');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('88cb72c0-b1fa-dc34-315b-67c29ee28ed2', 1, 'Working together on a project is like putting puzzle pieces together. Each person has their own piece to contribute, and when we work as a team, we can create something amazing.', 'gustar', '👍'),
  ('88cb72c0-b1fa-dc34-315b-67c29ee28ed2', 2, 'This is Emily. She enjoys working with her friends on a project. They listen to each other''s ideas and decide how to best put them all together. Sometimes they may have different opinions, but they talk about it calmly and find a solution that works for everyone.', 'escuchar', '👂'),
  ('88cb72c0-b1fa-dc34-315b-67c29ee28ed2', 3, 'When working on a project, it''s important to communicate openly and respectfully. Everyone''s ideas are valuable, and by sharing them, we can come up with creative solutions. Patience is also key - sometimes things may not go as planned, but by staying patient and working together, we can overcome any challenges.', 'importante', '❗'),
  ('88cb72c0-b1fa-dc34-315b-67c29ee28ed2', 4, 'Teamwork means supporting each other and celebrating our achievements together. When the project is finished, everyone feels proud of what they have accomplished as a team.', 'otro', '🔄'),
  ('88cb72c0-b1fa-dc34-315b-67c29ee28ed2', 5, 'My name is (). Working together on a project is fun and rewarding. I will listen to my friends'' ideas, communicate respectfully, and be patient if things don''t go smoothly. Together, we can create something wonderful!', 'escuchar', '👂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d7331789-cffb-ac4a-048b-9202e7b327b4', 1, 'Using words wisely is important. It helps me express my thoughts and feelings in a smart and friendly way. When I use assertive communication skills, I can stand up for myself and others without being mean or aggressive.', 'importante', '❗'),
  ('d7331789-cffb-ac4a-048b-9202e7b327b4', 2, 'Sometimes, people may say or do things that make me feel uncomfortable or upset. This is called bullying. If someone says unkind things to me, I can respond with assertive words like, "Please stop," or "I don''t like it when you talk to me that way." Using these words shows that I am confident and respectful of myself.', 'a veces', '⏳'),
  ('d7331789-cffb-ac4a-048b-9202e7b327b4', 3, 'When I see someone else being bullied, I can also use assertive words to help them. I might say, "That''s not nice. Let''s play together instead," or "We should include everyone."', 'ver', '👀'),
  ('d7331789-cffb-ac4a-048b-9202e7b327b4', 4, 'Assertive communication means speaking up for what is right while still being kind and calm. It lets others know how I feel and sets boundaries to keep me safe and respected.', 'correcto', '✅'),
  ('d7331789-cffb-ac4a-048b-9202e7b327b4', 5, 'Using assertive words is a powerful tool. It helps me stand up against bullying and create a positive environment for myself and others. Remember, using words wisely is a smart and friendly choice.', 'levantarse', '🧍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f339e2c4-1752-25ab-b263-b10da98c45d8', 1, 'Visiting family on holidays is a special time. It means spending time with loved ones and creating happy memories together.', 'familia', '👨‍👩‍👧‍👦'),
  ('f339e2c4-1752-25ab-b263-b10da98c45d8', 2, 'During the holiday season, we may visit our family members. We might travel by car or plane to reach their homes. When we arrive, there will be hugs, smiles, and maybe even some presents. Grandma and Grandpa will be so happy to see us!', 'vacaciones', '🏖️'),
  ('f339e2c4-1752-25ab-b263-b10da98c45d8', 3, 'At family gatherings, there will be lots of people talking and laughing. Some relatives we see often, like Aunt Lisa and Uncle Tom. Others we may not see as frequently, like cousins who live far away. It''s okay if I don''t remember everyone''s names right away. My parents can help me with that.', 'familia', '👨‍👩‍👧‍👦'),
  ('f339e2c4-1752-25ab-b263-b10da98c45d8', 4, 'Sometimes, there are special traditions during these visits. We might play games together, share stories, or enjoy a big meal. If there are children my age, we can have fun playing together.', 'a veces', '⏳'),
  ('f339e2c4-1752-25ab-b263-b10da98c45d8', 5, 'If I feel overwhelmed or need a break, it''s okay to let my parents know. They can find a quiet space for me to relax for a bit before rejoining the festivities.', 'sentir', '💓'),
  ('f339e2c4-1752-25ab-b263-b10da98c45d8', 6, 'Visiting family on holidays is a wonderful experience. I can look forward to seeing familiar faces, making new memories, and feeling the warmth of being surrounded by loved ones.', 'familia', '👨‍👩‍👧‍👦');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b4c55597-13ec-01c8-f77d-69c01c3d69eb', 1, 'Sometimes, unexpected things happen that need quick action. An emergency is when something unusual or dangerous occurs and we must act fast to stay safe.', 'a veces', '⏳'),
  ('b4c55597-13ec-01c8-f77d-69c01c3d69eb', 2, 'In an emergency, adults may use words like "emergency" or "urgent." They might look serious or move quickly. It’s important to pay attention and follow their directions carefully.', 'atencion', '📢'),
  ('b4c55597-13ec-01c8-f77d-69c01c3d69eb', 3, 'Emergencies can be different - like a fire, someone getting hurt, or feeling very sick. When there''s an emergency, it''s crucial to stay calm and listen to the grown-ups around me for guidance on what to do next.', 'escuchar', '👂'),
  ('b4c55597-13ec-01c8-f77d-69c01c3d69eb', 4, 'If I hear an alarm or see flashing lights during an emergency, know that it''s a signal to take action right away. This could mean leaving a building, finding a safe spot, or staying put until help arrives.', 'escuchar', '👂'),
  ('b4c55597-13ec-01c8-f77d-69c01c3d69eb', 5, 'Understanding what an emergency means helps us be prepared and stay safe. If I ever face an emergency, I will remember to stay calm, listen to adults, and follow instructions to keep myself and others out of harm''s way.', 'escuchar', '👂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 1, 'Learning from others'' experiences is important. I can understand more about feelings and how to express them by watching what happens around me.', 'aprender', '📖'),
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 2, 'When someone is sad, they may have tears in their eyes or a frown on their face. They might need a hug or kind words. If I see this, I can learn that sadness needs comfort.', 'alguien', '✨'),
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 3, 'If someone is happy, they may smile, laugh, or jump for joy. They might want to share their happiness with others. If I notice this, I can learn that happiness is contagious.', 'alguien', '✨'),
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 4, 'Sometimes people get angry. They may raise their voice, stomp their feet, or make a grumpy face. They might need space or time alone. If I observe this, I can learn that anger needs calmness.', 'a veces', '⏳'),
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 5, 'When someone is scared, they may shake, sweat, or look worried. They might need reassurance or a hand to hold. If I pay attention, I can learn that fear needs support.', 'atencion', '📢'),
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 6, 'By learning from others'' experiences, I can become better at understanding different emotions and how to respond to them.', 'aprender', '📖'),
  ('b635a51f-98e7-777f-f4b3-086bbfb7147f', 7, 'Learning from others'' experiences helps me understand feelings better.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e481b80d-741b-47c2-290c-6274f7f5ca3e', 1, 'Growing together as friends is a special journey. It means learning, playing, and caring for each other. Making friends can be exciting and sometimes challenging.', 'amigos', '🤝'),
  ('e481b80d-741b-47c2-290c-6274f7f5ca3e', 2, 'When we make new friends, we share our toys, take turns, and listen to each other. Sharing shows that we care about our friends'' feelings. Taking turns helps us all have fun together. Listening is important because it lets our friends know we value what they say.', 'esperar', '⏳'),
  ('e481b80d-741b-47c2-290c-6274f7f5ca3e', 3, 'Sometimes, friends may disagree or feel upset. It''s okay to talk about our feelings calmly and respectfully. We can use kind words and find solutions together. This helps us understand each other better and strengthens our friendship.', 'a veces', '⏳'),
  ('e481b80d-741b-47c2-290c-6274f7f5ca3e', 4, 'As friends, we support each other through good times and bad. We celebrate successes and offer comfort during tough moments. Being a good friend means being there for each other no matter what.', 'amigos', '🤝'),
  ('e481b80d-741b-47c2-290c-6274f7f5ca3e', 5, 'Growing together as friends is a wonderful experience. By sharing, taking turns, listening, resolving conflicts, and supporting each other, we build strong and lasting friendships. Let''s continue to learn and grow together as friends.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0f9597e7-9c80-3be4-140c-66e1c0f667ac', 1, 'In our world, there are many different cultures. Each culture has its own traditions, foods, and ways of doing things. It''s like having a big puzzle with lots of unique pieces that fit together to make something beautiful.', 'mundo', '🌍'),
  ('0f9597e7-9c80-3be4-140c-66e1c0f667ac', 2, 'Some people celebrate holidays in different ways. For example, during Diwali, families light candles and share sweets. In Chinese New Year, they have dragon dances and fireworks. Everyone celebrates special days in their own way.', 'algunos', '✨'),
  ('0f9597e7-9c80-3be4-140c-66e1c0f667ac', 3, 'People from different cultures may speak different languages. Some wear clothes that look different from what we wear. But all these differences make our world colorful and interesting.', 'personas', '👥'),
  ('0f9597e7-9c80-3be4-140c-66e1c0f667ac', 4, 'When we learn about other cultures, we can understand and appreciate them better. We can ask questions to learn more or share about our own traditions too. This helps us build friendships and respect each other''s differences.', 'aprender', '📖'),
  ('0f9597e7-9c80-3be4-140c-66e1c0f667ac', 5, 'Different cultures, one world. Just like how different colors make a rainbow beautiful, different cultures make our world rich and vibrant. Let''s celebrate and learn from each other''s uniqueness!', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7a612b1b-b758-93bf-4dd0-a84a40bc7790', 1, 'Everyone deserves respect. We all want to be treated kindly and fairly. It’s important for us to treat others the same way we want to be treated.', 'todos', '🌐'),
  ('7a612b1b-b758-93bf-4dd0-a84a40bc7790', 2, 'Sometimes, people may say or do unkind things that make us feel upset. This is not okay. If someone says or does something that makes me feel bad, I can tell a trusted adult about it. They will help me feel better and take care of the situation.', 'a veces', '⏳'),
  ('7a612b1b-b758-93bf-4dd0-a84a40bc7790', 3, 'It''s also important to remember that if I see someone being treated unkindly, I can stand up for them and let an adult know so they can help too. Together, we can create a safe and respectful environment for everyone.', 'importante', '❗'),
  ('7a612b1b-b758-93bf-4dd0-a84a40bc7790', 4, 'I will always remember that everyone deserves respect, including myself. I will speak up if I need help and support others who may need it too. By treating others with kindness and standing up against unkindness, we can make our community a better place for everyone.', 'siempre', '♾️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('48030a3f-adb8-a099-e7a2-e283e35887e5', 1, 'Building friendships is about connecting with others emotionally. It''s important to understand and express our feelings to build strong relationships.', 'importante', '❗'),
  ('48030a3f-adb8-a099-e7a2-e283e35887e5', 2, 'When I meet someone new, I can share my interests or ask them about theirs. This helps us find common ground and things we both enjoy.', 'alguien', '✨'),
  ('48030a3f-adb8-a099-e7a2-e283e35887e5', 3, 'If I feel happy when playing with a friend, I can smile and laugh to show them that I''m having fun. If I feel upset, I can tell my friend how I feel using kind words and a calm voice.', 'sentir', '💓'),
  ('48030a3f-adb8-a099-e7a2-e283e35887e5', 4, 'Sometimes, friends may have different feelings than me. It''s okay to listen and try to understand their emotions. Showing empathy means caring about how others feel.', 'a veces', '⏳'),
  ('48030a3f-adb8-a099-e7a2-e283e35887e5', 5, 'My Team, which includes my family and teachers, can help me learn more about emotions and how to connect with others in a positive way.', 'equipo', '👥'),
  ('48030a3f-adb8-a099-e7a2-e283e35887e5', 6, 'By understanding and expressing our feelings, we can build meaningful friendships. Connecting emotionally with others helps us create strong bonds and enjoy positive social interactions.', 'sentimientos', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f90a3f50-1d10-85c1-2bf7-b1a79206a26a', 1, 'My name is Ethan, and I love playing with my friends. Playing together is so much fun!', 'jugar', '🎮'),
  ('f90a3f50-1d10-85c1-2bf7-b1a79206a26a', 2, 'When we play together, it''s important to take turns and share toys. Sharing makes everyone happy. Sometimes, it can be hard to wait for our turn or give up a toy, but when we do, it shows that we care about our friends.', 'esperar', '⏳'),
  ('f90a3f50-1d10-85c1-2bf7-b1a79206a26a', 3, 'We also need to listen to each other and use kind words. If someone asks us to stop doing something, we should respect their feelings and find another game to play. It''s important to treat others the way we want to be treated.', 'escuchar', '👂'),
  ('f90a3f50-1d10-85c1-2bf7-b1a79206a26a', 4, 'Sometimes, disagreements happen when we play. It''s okay to have different opinions, but we should always try to solve problems peacefully. We can talk calmly and find a compromise that makes everyone happy. Remember, friendships are built on understanding and kindness.', 'a veces', '⏳'),
  ('f90a3f50-1d10-85c1-2bf7-b1a79206a26a', 5, 'Playing together is a wonderful way to make friends and have fun. Let''s remember to take turns, share toys, listen to each other, and solve problems peacefully. When we do these things, our friendships will grow stronger every day!', 'esperar', '⏳');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('707b3d24-71b1-f3ce-0b32-eefa04037c8f', 1, 'Adults get sad too.', 'triste', '😢'),
  ('707b3d24-71b1-f3ce-0b32-eefa04037c8f', 2, 'Sometimes adults feel sad, just like children do. It''s okay to feel sad sometimes. When adults are sad, they may need some time alone or someone to talk to about their feelings. They might not smile as much or want to play. That''s because sadness can make people feel different inside.', 'a veces', '⏳'),
  ('707b3d24-71b1-f3ce-0b32-eefa04037c8f', 3, 'When an adult is sad, it doesn''t mean I did something wrong. Adults have many reasons for feeling sad, and most of the time, it has nothing to do with me. It could be because of work, relationships, or other grown-up things that are hard to understand.', 'adulto', '🧑'),
  ('707b3d24-71b1-f3ce-0b32-eefa04037c8f', 4, 'If I see an adult who is sad, I can show them kindness by being gentle and understanding. I can offer a hug if they like hugs, or simply sit quietly with them. Sometimes, just knowing that someone cares can help a sad adult feel better.', 'ver', '👀'),
  ('707b3d24-71b1-f3ce-0b32-eefa04037c8f', 5, 'Remember, adults also have ways to cope with sadness, like talking to friends, taking deep breaths, or doing activities they enjoy. It''s important to respect their feelings and give them space when needed.', 'respirar', '🫁'),
  ('707b3d24-71b1-f3ce-0b32-eefa04037c8f', 6, 'Just like how it''s okay for me to feel sad sometimes, it''s okay for adults to feel sad too. I will remember that adults have feelings too and show them kindness when they are sad.', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('30d13eee-f64a-3bfc-c64f-f35e6292a23a', 1, 'Building a support system is important. A support system includes friends, family, and teachers who help us feel safe and happy.', 'importante', '❗'),
  ('30d13eee-f64a-3bfc-c64f-f35e6292a23a', 2, 'Friends are people we like to spend time with. They listen when we talk and play games with us. Family members care about us. They make sure we eat well and sleep enough. Teachers teach us new things and keep us safe at school.', 'amigos', '🤝'),
  ('30d13eee-f64a-3bfc-c64f-f35e6292a23a', 3, 'When someone is mean to us, our support system can help. Friends can stand up for us. Family members can comfort us. Teachers can stop the bullying.', 'alguien', '✨'),
  ('30d13eee-f64a-3bfc-c64f-f35e6292a23a', 4, 'It’s okay to ask for help from our support system. They want to help us stay strong and brave.', 'ayuda', '🆘'),
  ('30d13eee-f64a-3bfc-c64f-f35e6292a23a', 5, 'Having friends, family, and teachers in my support system makes me feel protected and cared for. I know they will help me if someone is unkind.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 1, 'Keeping our hands clean is very important. It helps us stay healthy and keeps germs away. One way to keep our hands clean is by washing them with soap and water.', 'manos', '🤚'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 2, 'When we touch things like doorknobs, toys, or even pets, germs can get on our hands. These germs can make us sick if we touch our face or eat without cleaning our hands first. That''s why it''s essential to wash our hands often, especially before eating and after using the bathroom.', 'cosas', '📦'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 3, 'Here are some steps to wash our hands properly: - First, wet my hands with clean, running water.', 'algunos', '✨'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 4, '- Then, apply soap and lather up my hands. Make sure to scrub all parts of my hands, including between my fingers and under my nails, for at least 20 seconds.', 'manos', '🤚'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 5, '- Next, rinse my hands well under clean, running water.', 'manos', '🤚'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 6, '- Finally, dry my hands with a clean towel or air dryer.', 'manos', '🤚'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 7, 'Remember, singing the "Happy Birthday" song twice while washing my hands can help me know when I''ve washed long enough!', 'recordar', '📝'),
  ('b8505597-ce57-bcf8-232d-1c28850be7eb', 8, 'By washing our hands regularly, we can say goodbye to germs and stay healthy. Let''s remember to wash our hands often to keep ourselves and others safe from getting sick. Goodbye germs!', 'despedirse', '👋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4b0dbba5-264a-5f76-cde4-b85d1713aa6e', 1, 'Finding calm in a busy world can be challenging, but it is possible. It''s important to know how to find calm when things get overwhelming.', 'tranquilo', '🧘'),
  ('4b0dbba5-264a-5f76-cde4-b85d1713aa6e', 2, 'When the world feels loud and busy, it can make me feel anxious or overwhelmed. Sometimes there are so many things happening at once that it''s hard to focus or stay calm. But I can find ways to help myself feel better. Taking deep breaths can help me relax and feel calmer. I can also find a quiet space where I can take a break from all the noise and activity. Doing something I enjoy, like drawing or listening to calming music, can also help me feel more peaceful. It''s okay to ask for help if I need it. I can talk to a trusted adult about how I''m feeling, and they can support me in finding calm.', 'respirar', '🫁'),
  ('4b0dbba5-264a-5f76-cde4-b85d1713aa6e', 3, 'Even though the world can be busy and overwhelming, I have the power to find calm within myself. By using strategies like deep breathing, finding quiet spaces, and doing activities I enjoy, I can navigate through the busyness and feel more peaceful.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fd4eb654-bfaf-6899-71f5-5c8b73228f12', 1, 'Helping out during grocery shopping can be a fun and important task. It’s a chance to learn about different foods, how to pick the best ones, and how to help at home.', 'compras', '🛒'),
  ('fd4eb654-bfaf-6899-71f5-5c8b73228f12', 2, 'When we go grocery shopping, there are many things to do. We make a list of what we need before we leave. At the store, we find the items on our list. Sometimes, we compare prices or look for special deals.', 'ir', '🚶'),
  ('fd4eb654-bfaf-6899-71f5-5c8b73228f12', 3, 'I can help by pushing the cart, picking fruits and vegetables, or finding items on the shelves. If I see something interesting, I can ask questions too!', 'ayuda', '🆘'),
  ('fd4eb654-bfaf-6899-71f5-5c8b73228f12', 4, 'Sometimes it may feel crowded or noisy in the store. That''s okay. I can hold onto the cart or stay close to my grown-up if I feel unsure.', 'a veces', '⏳'),
  ('fd4eb654-bfaf-6899-71f5-5c8b73228f12', 5, 'Helping out during grocery shopping is a way to learn new things and be helpful. I will try my best to help and enjoy the experience!', 'compras', '🛒');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1f68f948-9183-cce5-ed92-93f2327de678', 1, 'Welcome to the world of feelings, where we learn about emotions and how they affect us and those around us. Today, we will explore the skill of reading others'' feelings, an important ability that helps us connect with people in a positive way.', 'mundo', '🌍'),
  ('1f68f948-9183-cce5-ed92-93f2327de678', 2, 'When we look at someone''s face, we can often tell how they are feeling. Sometimes their eyes light up when they''re happy, or their brow furrows when they''re worried. These are clues that help us understand what someone is feeling.', 'mirar', '👀'),
  ('1f68f948-9183-cce5-ed92-93f2327de678', 3, 'People may not always say out loud how they feel, so it''s like solving a mystery by paying attention to their expressions and body language. When someone smiles, they might be happy. If they frown, they could be upset.', 'personas', '👥'),
  ('1f68f948-9183-cce5-ed92-93f2327de678', 4, 'It''s essential to remember that everyone feels different emotions, just like I do. Some days I might feel excited, while other days I might feel sad. It''s okay to have these feelings, and it''s okay for others to have them too.', 'recordar', '📝'),
  ('1f68f948-9183-cce5-ed92-93f2327de678', 5, 'By learning to read others'' feelings, we can show empathy and support to our friends and family. We can offer a kind word or gesture when someone seems down, or share in their joy when they''re happy. This helps build strong relationships based on understanding and care.', 'aprender', '📖'),
  ('1f68f948-9183-cce5-ed92-93f2327de678', 6, 'Reading others'' feelings is like being a detective of emotions, uncovering the hidden messages behind smiles and tears. Let''s practice this skill together and create connections filled with kindness and understanding.', 'leer', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('11cd7fbf-ffae-a68a-a770-326a5232f10c', 1, 'Feedback is information that helps us learn and grow. It’s like a map that shows us the way to get better at something.', 'aprender', '📖'),
  ('11cd7fbf-ffae-a68a-a770-326a5232f10c', 2, 'When we try new things, sometimes people give us feedback. This can be about how we did something or how we could do it even better next time. Sometimes, this feedback makes us feel uncomfortable or sad. But remember, feedback isn’t meant to hurt our feelings. It’s meant to help us improve!', 'intentar', '💪'),
  ('11cd7fbf-ffae-a68a-a770-326a5232f10c', 3, 'Just like when I play a video game, if I don’t know where to go next, the map helps me find my way. Feedback is like that map—it guides us in the right direction.', 'gustar', '👍'),
  ('11cd7fbf-ffae-a68a-a770-326a5232f10c', 4, 'If someone tells me, “You did a great job on your drawing, but maybe next time you could use more colors,” they are giving me helpful feedback. They want to see I become an even better artist!', 'alguien', '✨'),
  ('11cd7fbf-ffae-a68a-a770-326a5232f10c', 5, 'Feedback is not the end of the road; it’s a new beginning. It helps us understand what we’re good at and what we can work on. With feedback, we can keep learning and growing. That’s Life on Planet Earth.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('eeb18643-ef26-f73d-cd97-0f5347529612', 1, 'Fireworks night is a special event where we get to see beautiful lights and colors in the sky. It can be exciting but also loud.', 'noche', '🌙'),
  ('eeb18643-ef26-f73d-cd97-0f5347529612', 2, 'When we go to watch fireworks, it''s important to remember that they make loud noises. Some people may cover their ears or wear ear protection to feel more comfortable. I can do the same if the noise bothers me.', 'ir', '🚶'),
  ('eeb18643-ef26-f73d-cd97-0f5347529612', 3, 'It''s also essential to stay close to my family during the fireworks show. We can hold hands or stand together to enjoy the display safely. If I feel scared or overwhelmed, I can tell my family, and we can move to a quieter spot.', 'cerrar', '🔒'),
  ('eeb18643-ef26-f73d-cd97-0f5347529612', 4, 'Fireworks night is a magical experience. By staying close to my family and protecting my ears from loud noises, I can have a wonderful time watching the colorful fireworks light up the sky.', 'noche', '🌙');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('95da532b-4db8-e6ad-5cbd-67a56c6f090e', 1, 'When people nod their heads, it means more than just saying "yes." What else can a nod mean?', 'personas', '👥'),
  ('95da532b-4db8-e6ad-5cbd-67a56c6f090e', 2, 'A nod is like a silent way of talking. It can say, “I understand,” or “I agree.” When someone nods at me, they might be showing that they are listening and paying attention.', 'gustar', '👍'),
  ('95da532b-4db8-e6ad-5cbd-67a56c6f090e', 3, 'Sometimes, when I am talking to someone, they may nod to show that they hear me. Nodding helps me know that the person understands what I am saying. It’s like a little sign that says, “I’m with you.”', 'a veces', '⏳'),
  ('95da532b-4db8-e6ad-5cbd-67a56c6f090e', 4, 'Remember, a nod is a friendly gesture that shows understanding and agreement. So, when someone nods at me, I will know they are listening and understanding what I am saying.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('94c50db4-acf3-b995-38f8-3b1ffbe21418', 1, 'Managing free time wisely is important for me. I can use my free time in fun and helpful ways.', 'tiempo', '⏰'),
  ('94c50db4-acf3-b995-38f8-3b1ffbe21418', 2, 'When school ends, I have free time before dinner. I can choose to play with toys, draw pictures, or read a book during this time. These are all good choices for using my free time wisely.', 'escuela', '🏫'),
  ('94c50db4-acf3-b995-38f8-3b1ffbe21418', 3, 'If it''s raining outside, I can''t go out to play. Instead, I can watch a movie, do a puzzle, or help mom or dad with a chore. These are great ways to spend my indoor free time.', 'fuera', '🌳'),
  ('94c50db4-acf3-b995-38f8-3b1ffbe21418', 4, 'During the weekend, I have more free time. I can plan fun activities like going to the park, baking cookies, or playing games with my family. These activities make my free time enjoyable and meaningful.', 'mas', '➕'),
  ('94c50db4-acf3-b995-38f8-3b1ffbe21418', 5, 'Using my free time wisely means making good choices about how to spend it. Whether it''s after school, on a rainy day, or during the weekend, I will try to fill my free time with activities that bring me joy and satisfaction. Managing my free time wisely helps me feel happy and fulfilled!', 'tiempo', '⏰');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 1, 'Making friends is like baking a delicious cake. It takes different ingredients and steps to create a wonderful friendship.', 'amigos', '🤝'),
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 2, 'First, we need kindness. Being kind means treating others with respect and being friendly. When we are kind, it helps us make new friends.', 'necesitar', '❗'),
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 3, 'Next, we add listening. Listening means paying attention when someone is talking and showing interest in what they have to say. When we listen, we show that we care about our friends.', 'alguien', '✨'),
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 4, 'Now, let''s sprinkle in sharing. Sharing means taking turns and playing together. When we share, it makes our friendships stronger.', 'compartir', '🤲'),
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 5, 'We also need understanding. Understanding means trying to see things from our friend''s perspective and being patient with them. When we understand each other, our friendships grow deeper.', 'necesitar', '❗'),
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 6, 'Lastly, we mix in forgiveness. Forgiveness means letting go of mistakes and not holding grudges. When we forgive, it allows our friendships to heal and continue to flourish.', 'ir', '🚶'),
  ('1710a930-790a-1d9e-2f30-47b96fe9a882', 7, 'Just like a recipe, making friends requires kindness, listening, sharing, understanding, and forgiveness. By using these ingredients, I can bake the perfect friendship cake!', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a98db3e4-f5b0-a8f9-b309-a2fdcf0631d1', 1, 'I have a fun hobby that I love to do - storytelling with action figures! It''s like creating my own movies or adventures using my favorite characters.', 'divertido', '😄'),
  ('a98db3e4-f5b0-a8f9-b309-a2fdcf0631d1', 2, 'When I tell stories with action figures, I can use my imagination and create exciting scenes. First, I choose the action figures I want to include in my story. Maybe it''s superheroes, princesses, or even animals. Then, I set up a scene using props or objects around me. It could be a cityscape, a forest, or a spaceship!', 'decir', '💬'),
  ('a98db3e4-f5b0-a8f9-b309-a2fdcf0631d1', 3, 'Once everything is ready, I start telling my story. I give each character a voice and make them move around. I can act out battles, rescue missions, or even funny moments. The possibilities are endless!', 'listo', '✅'),
  ('a98db3e4-f5b0-a8f9-b309-a2fdcf0631d1', 4, 'Sometimes, I like to write down my stories or draw pictures to remember them. This way, I can share my creativity with others too. I can show my friends or family what I''ve created and they might even join in on the storytelling fun!', 'a veces', '⏳'),
  ('a98db3e4-f5b0-a8f9-b309-a2fdcf0631d1', 5, 'Storytelling with action figures is a wonderful hobby that lets me express myself and bring my favorite characters to life. It''s a great way to have fun and share my imagination with others. So let''s grab our action figures and embark on amazing adventures together!', 'forma', '📐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('305d9b8b-9465-e88f-ca2d-7e5e82341041', 1, 'Respecting public property is important for everyone in our community.', 'importante', '❗'),
  ('305d9b8b-9465-e88f-ca2d-7e5e82341041', 2, 'Public property belongs to everyone. It includes parks, benches, sidewalks, and more. When we respect public property, we take care of it so that everyone can enjoy it.', 'todos', '🌐'),
  ('305d9b8b-9465-e88f-ca2d-7e5e82341041', 3, 'We should not litter in public places. Littering makes the environment dirty and unpleasant for others. We can use trash cans to dispose of our garbage properly.', 'deber', '📋'),
  ('305d9b8b-9465-e88f-ca2d-7e5e82341041', 4, 'It''s also essential not to damage or vandalize public property. This means we should not draw on walls, break things, or harm plants in public spaces. Taking care of public property helps keep our community clean and beautiful for all to enjoy.', 'deber', '📋'),
  ('305d9b8b-9465-e88f-ca2d-7e5e82341041', 5, 'Remember, respecting public property shows that we care about our community and want to make it a better place for everyone. Let''s all do our part to keep public spaces clean and enjoyable for ourselves and others.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c5a0962e-9111-0a8d-6cc4-5a64cb379561', 1, 'Preparing for a birthday party can be exciting!', 'cumpleanos', '🎂'),
  ('c5a0962e-9111-0a8d-6cc4-5a64cb379561', 2, 'Birthday parties are special celebrations where we gather to have fun and celebrate someone''s birthday. At a birthday party, there may be decorations like balloons and banners, yummy food such as cake and snacks, games to play, and sometimes even music to dance to. People might bring gifts for the birthday person to show their love and care.', 'cumpleanos', '🎂'),
  ('c5a0962e-9111-0a8d-6cc4-5a64cb379561', 3, 'During the party, we sing "Happy Birthday" and watch as the birthday person blows out candles on their cake. It''s a happy moment that everyone enjoys together. Sometimes, there are party favors or goodie bags given to guests as a thank you for coming.', 'gracias', '🙏'),
  ('c5a0962e-9111-0a8d-6cc4-5a64cb379561', 4, 'Remember, it''s important to be polite and say "thank you" when receiving gifts or compliments at a birthday party. If we follow these simple steps, we can have a great time celebrating with friends and family.', 'gracias', '🙏'),
  ('c5a0962e-9111-0a8d-6cc4-5a64cb379561', 5, 'Preparing for a birthday party is a wonderful experience filled with joy and happiness. By being kind, respectful, and joining in the fun activities, we can make the celebration even more special for everyone involved.', 'cumpleanos', '🎂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7a597543-a97b-e376-1ec0-5c3dcc6cea3d', 1, 'Big feelings are emotions that can be strong and overwhelming. It’s okay to have big feelings, and there are ways to cope with them.', 'sentimientos', '💗'),
  ('7a597543-a97b-e376-1ec0-5c3dcc6cea3d', 2, 'Sometimes, I feel really happy or excited. Other times, I might feel sad, angry, or scared. These are all examples of big feelings. When I have big feelings, it''s important to remember that everyone feels this way sometimes.', 'a veces', '⏳'),
  ('7a597543-a97b-e376-1ec0-5c3dcc6cea3d', 3, 'One way to cope with big feelings is to take deep breaths. Deep breaths help calm my body down when I''m feeling overwhelmed. Another way is to talk to someone I trust about how I''m feeling. This could be a parent, teacher, or friend. They can help me understand my feelings better.', 'respirar', '🫁'),
  ('7a597543-a97b-e376-1ec0-5c3dcc6cea3d', 4, 'It''s also helpful to find activities that make me feel better when I''m experiencing big feelings. Drawing, listening to music, or going for a walk are some things I can do to distract myself and feel more relaxed.', 'sentir', '💓'),
  ('7a597543-a97b-e376-1ec0-5c3dcc6cea3d', 5, 'Remember, it''s okay to have big feelings, and it''s important to express them in a healthy way. By learning how to cope with big feelings, I can feel more in control and happier.', 'recordar', '📝'),
  ('7a597543-a97b-e376-1ec0-5c3dcc6cea3d', 6, 'Dealing with big feelings is a normal part of life. Taking deep breaths, talking to someone I trust, and finding relaxing activities are great ways to manage my emotions. Remember, it''s okay to have big feelings, and I can always seek support when I need it.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('addd30ff-993d-0c14-0533-f83fdd9a4668', 1, 'Exploring nature''s wonders is an exciting adventure. Nature has so many beautiful and interesting things to discover.', 'naturaleza', '🌿'),
  ('addd30ff-993d-0c14-0533-f83fdd9a4668', 2, 'When we explore nature, we can find colorful flowers, buzzing bees, tall trees, and chirping birds. We might see squirrels playing or butterflies fluttering by. There are rocks to climb, streams to listen to, and leaves to crunch under our feet.', 'escuchar', '👂'),
  ('addd30ff-993d-0c14-0533-f83fdd9a4668', 3, 'Nature changes with the seasons. In spring, flowers bloom and baby animals are born. Summer brings warm sunshine and picnics in the park. Fall paints the trees in vibrant colors, and winter covers everything in a blanket of snow.', 'naturaleza', '🌿'),
  ('addd30ff-993d-0c14-0533-f83fdd9a4668', 4, 'Exploring nature helps us learn about the world around us. It teaches us to appreciate the beauty of our planet and how everything is connected.', 'naturaleza', '🌿'),
  ('addd30ff-993d-0c14-0533-f83fdd9a4668', 5, 'Exploring nature''s wonders is a special way to connect with the world. Let''s continue to explore and marvel at all the amazing things nature has to offer.', 'naturaleza', '🌿');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b047eea9-9a80-f5e1-9f4c-310c1e2296bf', 1, 'When new people move into the house next door, it''s time to welcome them with kindness and make them feel at home.', 'nuevo', '🆕'),
  ('b047eea9-9a80-f5e1-9f4c-310c1e2296bf', 2, 'New neighbors might be feeling a little nervous or unsure in their new surroundings. We can help by smiling and saying hello when we see them.', 'nuevo', '🆕'),
  ('b047eea9-9a80-f5e1-9f4c-310c1e2296bf', 3, 'We can offer to show them around the neighborhood or share information about local parks and schools. This can help them feel more comfortable and welcomed.', 'compartir', '🤲'),
  ('b047eea9-9a80-f5e1-9f4c-310c1e2296bf', 4, 'Sometimes new neighbors may have different customs or speak a different language. It''s important to be patient and understanding as they adjust to their new home.', 'a veces', '⏳'),
  ('b047eea9-9a80-f5e1-9f4c-310c1e2296bf', 5, 'Inviting them over for a meal or offering to help them unpack boxes can be a great way to show kindness and build a friendly relationship.', 'comida', '🍽️'),
  ('b047eea9-9a80-f5e1-9f4c-310c1e2296bf', 6, 'Welcoming new neighbors is a wonderful opportunity to make new friends and create a sense of community. By being kind and helpful, we can make our neighborhood a warm and welcoming place for everyone, including our new neighbors.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('50634e80-b28b-aa6d-3a1c-96be7a5acd19', 1, 'Sometimes, I feel angry. It''s a strong feeling that can make me want to shout or hit things. But what should I do when I feel angry? Is it okay to act on my anger?', 'a veces', '⏳'),
  ('50634e80-b28b-aa6d-3a1c-96be7a5acd19', 2, 'Feeling angry is normal. Everyone feels angry sometimes. It''s a signal that something isn''t right or fair. When I feel angry, I can take deep breaths and count to ten. This helps me calm down and think before I react.', 'respirar', '🫁'),
  ('50634e80-b28b-aa6d-3a1c-96be7a5acd19', 3, 'Acting angry means doing things that might hurt myself or others. It''s important to remember that I have control over my actions. Instead of hitting or shouting, I can use words to express how I feel. I can say, "I''m angry because..." or "I need some space right now."', 'enfadado', '😤'),
  ('50634e80-b28b-aa6d-3a1c-96be7a5acd19', 4, 'If I need help managing my anger, I can talk to a trusted adult. They can teach me more strategies to cope with my emotions. They might suggest taking a break, listening to calming music, or doing something I enjoy to distract myself from the anger.', 'necesitar', '❗'),
  ('50634e80-b28b-aa6d-3a1c-96be7a5acd19', 5, 'Feeling angry is okay, but acting on my anger is a choice. I can choose to respond in a positive way by using words and seeking support. Taking control of my actions helps me manage my anger and maintain positive relationships with others.', 'sentimiento', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c8d6e99a-2b57-c701-b8d9-185a1f85cfdc', 1, 'Good manners at the dinner table are important for everyone.', 'bien', '👍'),
  ('c8d6e99a-2b57-c701-b8d9-185a1f85cfdc', 2, 'When we sit down to eat, it''s polite to say "please" and "thank you." We use our utensils to eat our food instead of our hands. Chewing with our mouths closed is a good habit too.', 'gracias', '🙏'),
  ('c8d6e99a-2b57-c701-b8d9-185a1f85cfdc', 3, 'If I don''t like a certain food, it''s okay to politely decline and ask for something else. It''s important to try new foods sometimes, even if they look different.', 'gustar', '👍'),
  ('c8d6e99a-2b57-c701-b8d9-185a1f85cfdc', 4, 'Remember to sit up straight in my chair and not talk with my mouth full. It''s also nice to engage in conversation with others at the table.', 'recordar', '📝'),
  ('c8d6e99a-2b57-c701-b8d9-185a1f85cfdc', 5, 'Having good manners at the dinner table shows respect for myself and others. By using polite words and actions, mealtime can be enjoyable for everyone.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 1, 'When I feel overwhelmed, it can be hard to know what to do. Sometimes my body feels tight and my mind races with thoughts. It''s important to remember that there are ways to seek help when feeling this way.', 'sentir', '💓'),
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 2, 'Feeling overwhelmed is like having too many puzzle pieces in my hands at once. My body might feel tense, my heart may beat fast, and I might find it difficult to focus on anything else.', 'sentimiento', '💗'),
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 3, 'When I feel overwhelmed, taking deep breaths can help calm me down. Inhale slowly through my nose, hold for a moment, then exhale gently through my mouth. This can make the jumbled thoughts slow down.', 'respirar', '🫁'),
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 4, 'It''s okay to ask for help when feeling overwhelmed. I can talk to a trusted adult, like a parent or teacher, about how I am feeling. They can listen and offer support to help me feel better.', 'ayuda', '🆘'),
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 5, 'Sometimes, finding a quiet space to take a break can also help. A cozy corner or a favorite spot where I can relax and gather my thoughts can make a big difference.', 'a veces', '⏳'),
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 6, 'Remember, everyone feels overwhelmed sometimes, and it''s okay to reach out for help. Seeking support from others can make things feel more manageable and less stressful.', 'recordar', '📝'),
  ('a85347f7-7fd5-4783-af22-8a713c927b21', 7, 'When I feel overwhelmed, seeking help is a good choice. Taking deep breaths, talking to someone I trust, and finding a quiet space are all helpful strategies. Remember, it''s okay to ask for help when needed.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('322ad783-ab57-b8fa-47bf-c24dbc5247dc', 1, 'Animals live in different homes. Some animals live in the forest, some in the ocean, and others on the farm. They need their homes to be safe and comfortable just like we do.', 'diferente', '🌈'),
  ('322ad783-ab57-b8fa-47bf-c24dbc5247dc', 2, 'In the forest, there are tall trees and bushes where birds build nests for their eggs. Squirrels make their homes in tree hollows or leafy nests called dreys. Bears find cozy dens in caves or under thick bushes to sleep during winter.', 'construir', '🔨'),
  ('322ad783-ab57-b8fa-47bf-c24dbc5247dc', 3, 'Under the sea, fish swim around coral reefs and hide in seaweed. Sea turtles lay their eggs on sandy beaches near the water. Dolphins and whales travel through the deep blue ocean waves.', 'nadar', '🏊'),
  ('322ad783-ab57-b8fa-47bf-c24dbc5247dc', 4, 'On the farm, cows graze in fields and rest in barns. Chickens lay their eggs in cozy nesting boxes. Horses have stables with fresh hay and clean water.', 'limpiar', '🧹'),
  ('322ad783-ab57-b8fa-47bf-c24dbc5247dc', 5, 'Animals and their homes are all around us. Each animal has a special place to live that keeps them safe and happy. Just like animals, we also have our own homes where we feel safe and loved.', 'todo', '🌐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('baad188c-80b1-1a92-db65-d12e80e2c702', 1, 'Sometimes, things change in my life. Change can be exciting and bring new opportunities. Today, I am going to learn about the beauty of trying something new.', 'a veces', '⏳'),
  ('baad188c-80b1-1a92-db65-d12e80e2c702', 2, 'When I try something new, it means I am being brave and open-minded. It might feel a little scary at first, but that''s okay. Trying new things helps me grow and discover new interests and talents.', 'intentar', '💪'),
  ('baad188c-80b1-1a92-db65-d12e80e2c702', 3, 'Change can happen in many ways. It could be trying a new food, playing a new game, or visiting a new place. Each time I try something new, I am expanding my horizons and learning more about myself and the world around me.', 'cambio', '🔄'),
  ('baad188c-80b1-1a92-db65-d12e80e2c702', 4, 'It''s important to remember that not everything will go perfectly when trying something new. That''s okay too! Mistakes are part of the learning process. If I make a mistake, I can learn from it and try again.', 'error', '💪'),
  ('baad188c-80b1-1a92-db65-d12e80e2c702', 5, 'Trying something new is an adventure. It opens doors to new experiences and helps me become more adaptable and resilient. So, next time something new comes my way, I will embrace it with excitement and curiosity.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e5d9ec23-cc5a-2817-a0ac-b3382cc2246e', 1, 'Stretching is an important part of exercising. It helps my body get ready for exercise and also helps it cool down after I am done.', 'vestirse', '👕'),
  ('e5d9ec23-cc5a-2817-a0ac-b3382cc2246e', 2, 'Before I start to exercise, I stretch my arms, legs, and back. This helps me warm up my muscles so they don''t get hurt when I move around a lot. After I finish exercising, I do more stretching to help my muscles relax. Stretching feels good and makes my body feel better.', 'empezar', '🏁'),
  ('e5d9ec23-cc5a-2817-a0ac-b3382cc2246e', 3, 'When I stretch, I reach my arms up high and then reach down low to touch my toes. I also stretch my legs by pulling one foot towards my bottom and holding it there for a few seconds. Then I switch to the other leg. These stretches help my body stay flexible and strong.', 'otro', '🔄'),
  ('e5d9ec23-cc5a-2817-a0ac-b3382cc2246e', 4, 'Stretching before and after exercise helps keep my body healthy and strong.', 'ejercicio', '🏋️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('acedd550-cd01-29cb-40a7-12014c581e22', 1, 'Listening and taking turns in conversations is important. When I listen and take turns, it helps me understand what others are saying and share my thoughts too.', 'esperar', '⏳'),
  ('acedd550-cd01-29cb-40a7-12014c581e22', 2, 'When someone talks to me, I look at them and try to pay attention to their words. It''s like when I tell a story, and I want others to listen, so I need to listen when they talk too. Sometimes, I may have something exciting to say, but I wait for the other person to finish talking before I speak. This way, we both get a chance to share our ideas and feelings. Taking turns in conversations makes everyone feel valued and respected.', 'atencion', '📢'),
  ('acedd550-cd01-29cb-40a7-12014c581e22', 3, 'By listening and taking turns in conversations, I can show that I care about what others have to say and also make sure my voice is heard. Listening and taking turns helps us all have good conversations.', 'decir', '💬');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8454aefc-d295-2c91-d1d1-ec00a80b8459', 1, 'Sun safety is important for our skin. It helps protect us from the sun''s strong rays, which can sometimes cause harm.', 'sol', '☀️'),
  ('8454aefc-d295-2c91-d1d1-ec00a80b8459', 2, 'When we go outside on a sunny day, it’s smart to wear sunscreen and hats. Sunscreen is like a protective shield for our skin. It keeps the harmful rays away so that our skin stays healthy. Hats also help by shading our face and head from direct sunlight.', 'ir', '🚶'),
  ('8454aefc-d295-2c91-d1d1-ec00a80b8459', 3, 'If we forget to put on sunscreen or wear a hat, our skin might get red and hurt. This is called a sunburn. Sunburns can be uncomfortable and make our skin feel hot. They can happen quickly if we stay in the sun too long without protection.', 'vestirse', '👕'),
  ('8454aefc-d295-2c91-d1d1-ec00a80b8459', 4, 'Remembering to apply sunscreen before going out and wearing a hat can keep our skin safe and healthy. It’s a good habit to practice whenever we are outdoors during sunny days.', 'seguro', '🛡️'),
  ('8454aefc-d295-2c91-d1d1-ec00a80b8459', 5, 'Protecting our skin with sunscreen and hats is like giving it a shield against the sun. By taking care of our skin, we can enjoy being outside without worrying about getting a sunburn. Let’s remember to use sunscreen and wear hats to keep our skin happy and healthy!', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e40b5453-fcb1-a53f-19a2-0287b0d023cd', 1, 'I am part of a team. A team is like a group of friends who work together to help each other and achieve great things.', 'equipo', '👥'),
  ('e40b5453-fcb1-a53f-19a2-0287b0d023cd', 2, 'In my team, everyone has different strengths and talents. Some people are good at drawing, some are good at running, and others are good at making people laugh. Together, we can do amazing things because we all bring something special to the team.', 'equipo', '👥'),
  ('e40b5453-fcb1-a53f-19a2-0287b0d023cd', 3, 'Sometimes, we might have disagreements or find it hard to understand each other, but that''s okay. We can talk about our feelings and try to find solutions together. This helps us learn how to work as a team and understand each other better.', 'a veces', '⏳'),
  ('e40b5453-fcb1-a53f-19a2-0287b0d023cd', 4, 'When we work together, we feel proud of what we accomplish. It''s like putting puzzle pieces together – when we all contribute, we create something beautiful and complete.', 'trabajar', '💼'),
  ('e40b5453-fcb1-a53f-19a2-0287b0d023cd', 5, 'Being part of a team means we grow and learn together. I will try my best to listen, share, and support my teammates, and they will do the same for me. Together, we can achieve wonderful things!', 'equipo', '👥');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9a52b6a1-7f9b-e0cf-ba34-a08f3a7e4973', 1, 'Dressing up for Halloween is fun! It''s a special day where we get to wear costumes and go trick-or-treating.', 'divertido', '😄'),
  ('9a52b6a1-7f9b-e0cf-ba34-a08f3a7e4973', 2, 'Last year, I dressed up as a superhero. My costume had a cape and a mask. I felt strong and brave. When I knocked on doors, people gave me candy because they liked my costume. This year, I am thinking of dressing up as a pirate. Pirates have swords and treasure maps. It will be exciting to pretend to search for hidden treasures!', 'ano', '✨'),
  ('9a52b6a1-7f9b-e0cf-ba34-a08f3a7e4973', 3, 'When we go trick-or-treating, it''s important to stay with our family or friends. We should only visit houses with lights on outside. It''s also good to say "trick or treat" and "thank you" when we receive candy. Sometimes, people may wear scary costumes or decorate their homes with spooky things. It''s okay to feel a little scared, but remember that it''s all make-believe and meant to be fun.', 'gracias', '🙏'),
  ('9a52b6a1-7f9b-e0cf-ba34-a08f3a7e4973', 4, 'I love dressing up for Halloween. It''s a time to use our imagination and have fun with others. This year, I will dress up as a pirate and enjoy the adventure of trick-or-treating with my family and friends.', 'tiempo', '⏰');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('aeba7dde-6b16-54dc-80d2-077b9a28fc0c', 1, 'Sometimes, I feel anxious and worried. This happens to many people, including me. Let''s learn how to handle anxiety and worries together.', 'a veces', '⏳'),
  ('aeba7dde-6b16-54dc-80d2-077b9a28fc0c', 2, 'Anxiety is when we feel scared or nervous about something that might happen in the future. Worries are thoughts that make us feel uneasy or upset. It''s important to remember that everyone feels anxious or worried sometimes, and it''s okay to have these feelings.', 'sentir', '💓'),
  ('aeba7dde-6b16-54dc-80d2-077b9a28fc0c', 3, 'When I start feeling anxious or worried, I can take deep breaths to help calm myself down. I can also try to think positive thoughts and remind myself that everything will be okay. Talking to someone I trust, like a parent or teacher, can also help me feel better.', 'respirar', '🫁'),
  ('aeba7dde-6b16-54dc-80d2-077b9a28fc0c', 4, 'It''s helpful to have a routine and stick to it. Having a schedule helps me know what to expect and reduces my anxiety. I can also use relaxation techniques, such as listening to calming music or doing yoga, to relax my mind and body.', 'rutina', '🔄'),
  ('aeba7dde-6b16-54dc-80d2-077b9a28fc0c', 5, 'I can also write down my worries in a journal or draw them on paper. This helps me express my feelings and release some of the tension. Sometimes, talking to a therapist or counselor can provide additional support and strategies for managing anxiety and worries.', 'escribir', '✏️'),
  ('aeba7dde-6b16-54dc-80d2-077b9a28fc0c', 6, 'Remember, it''s normal to feel anxious or worried sometimes. By using different strategies like deep breathing, positive thinking, sticking to a routine, and seeking support from trusted adults, I can effectively handle my anxiety and worries.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 1, 'Homework is an important part of school. It helps us practice what we''ve learned and become even smarter! Sometimes, homework can be challenging, but there are ways to make it easier.', 'deberes', '📋'),
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 2, 'When I have homework, I find a quiet place where I can concentrate. It could be my bedroom, the kitchen table, or a cozy corner in the house. Having a designated homework spot helps me focus.', 'deberes', '📋'),
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 3, 'Before starting my homework, I gather all the materials I need. This includes pencils, erasers, textbooks, and any other supplies that will help me complete my assignments. Being prepared makes the task less overwhelming.', 'deberes', '📋'),
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 4, 'I break down my homework into smaller tasks. For example, if I have math problems to solve, I do a few at a time instead of trying to do them all at once. Taking breaks in between each task helps me stay focused and motivated.', 'deberes', '📋'),
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 5, 'If I don''t understand something, I ask for help. My teacher, parents, or even classmates can assist me in understanding the assignment better. Asking for help is not a sign of weakness; it shows that I am determined to learn and succeed.', 'ayuda', '🆘'),
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 6, 'Once I finish my homework, I check it carefully to make sure everything is correct. If I made mistakes, I try to understand why and learn from them. Making mistakes is a normal part of learning, and it helps me grow.', 'terminar', '✅'),
  ('b1e7b807-4eb0-93d4-bea9-d3dce8f005ca', 7, 'Homework may seem challenging at times, but with the right strategies, I can tackle it successfully. By finding a quiet space, gathering necessary materials, breaking tasks into smaller parts, asking for help when needed, and checking my work, I can become a homework helper and achieve academic success.', 'deberes', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3be846fe-98b9-aa70-a3ff-8de4091649d9', 1, 'The weather changes from day to day. It can be sunny, rainy, windy, or snowy.', 'dia', '☀️'),
  ('3be846fe-98b9-aa70-a3ff-8de4091649d9', 2, 'When the weather changes, we need to change what we wear and what we do. If it''s raining, I will need my raincoat and umbrella. If it''s sunny, I will wear sunglasses and sunscreen.', 'necesitar', '❗'),
  ('3be846fe-98b9-aa70-a3ff-8de4091649d9', 3, 'Sometimes, the weather may surprise us. It''s okay to feel unsure about sudden changes. Taking deep breaths can help me calm down when things are unexpected.', 'respirar', '🫁'),
  ('3be846fe-98b9-aa70-a3ff-8de4091649d9', 4, 'The weather is always changing. I can adapt by being prepared with the right clothes and tools. When the weather surprises me, I will take deep breaths to stay calm and handle the changes positively.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2fafbf1d-f057-d60b-a232-22cd28912544', 1, 'I am learning about screen time limits. Screen time is the amount of time I spend using devices like tablets, computers, and phones.', 'aprender', '📖'),
  ('2fafbf1d-f057-d60b-a232-22cd28912544', 2, 'My parents want me to have a healthy balance between screen time and other activities. Too much screen time can make my eyes tired and give me less time for playing outside or spending time with family and friends. It''s important to take breaks from screens and do other things that I enjoy, like reading, drawing, or playing games.', 'padres', '👨‍👩‍👧'),
  ('2fafbf1d-f057-d60b-a232-22cd28912544', 3, 'My parents will help me set specific times for using screens, and they may use timers to remind me when it''s time to take a break. They care about my health and well-being, so I will try to follow their guidance on screen time limits.', 'padres', '👨‍👩‍👧'),
  ('2fafbf1d-f057-d60b-a232-22cd28912544', 4, 'Learning about screen time limits helps me understand how to use technology in a balanced way. By following the rules my parents set, I can enjoy my screen time while also making time for other fun activities.', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8ace5ee5-ef8a-968a-81d5-d9c825bb9967', 1, 'Respecting boundaries is important for friends. It helps us feel safe and comfortable.', 'limites', '🚧'),
  ('8ace5ee5-ef8a-968a-81d5-d9c825bb9967', 2, 'Everyone has their own personal space, like an invisible bubble around them. We need to be aware of this and not stand too close or touch someone without asking first. If we want to play with a friend''s toy, it''s important to ask before taking it. This shows respect for their things and their personal space. When we''re playing games, we should also make sure everyone feels included and comfortable.', 'espacio personal', '↔️'),
  ('8ace5ee5-ef8a-968a-81d5-d9c825bb9967', 3, 'Respecting boundaries makes our friendships stronger. It''s important to always ask before touching or taking something that belongs to someone else. By respecting each other''s personal space, we can all have fun together and enjoy spending time with our friends.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d04afeec-3d8e-b0b6-4a20-082eb170fa63', 1, 'Sometimes, I feel happy. My name is Lily. When I am happy, it feels like the sun shining brightly in the sky. It makes me smile and feel warm inside.', 'a veces', '⏳'),
  ('d04afeec-3d8e-b0b6-4a20-082eb170fa63', 2, 'When I play with my favorite toys or read a good book, I feel happy. Last week, my friend Mia invited me to her birthday party. We played games, ate cake, and laughed together. That made me very happy.', 'jugar', '🎮'),
  ('d04afeec-3d8e-b0b6-4a20-082eb170fa63', 3, 'My mom says that when we are happy, our faces light up, just like the sun brightens the day. She also tells me that it''s okay to feel happy and enjoy those moments.', 'feliz', '😊'),
  ('d04afeec-3d8e-b0b6-4a20-082eb170fa63', 4, 'Being happy helps me be kind to others. When I''m happy, I share my toys with my brother, and I help my mom set the table for dinner. It feels good to spread happiness around.', 'feliz', '😊'),
  ('d04afeec-3d8e-b0b6-4a20-082eb170fa63', 5, 'I love feeling happy like a big yellow sun. It''s important to remember that everyone feels happy sometimes. Next time I feel happy, I will think of the big yellow sun and let my happiness shine through.', 'sentimiento', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9df02a61-1441-1633-59a7-fa315f666e95', 1, 'Sometimes, things we like may change. It’s okay to feel a little unsure when this happens.', 'a veces', '⏳'),
  ('9df02a61-1441-1633-59a7-fa315f666e95', 2, 'My favorite TV show might not be on anymore. Or my friend might have a new toy that I haven’t seen before. When my favorite things change, it can make me feel surprised or even a little sad. But it''s important to remember that change is a normal part of life and it can bring new and exciting experiences too.', 'television', '📺'),
  ('9df02a61-1441-1633-59a7-fa315f666e95', 3, 'It’s okay to talk about how I feel with someone I trust. They can help me understand and adjust to the changes. I can also try to find new things to enjoy and explore different activities.', 'hablar', '🗣️'),
  ('9df02a61-1441-1633-59a7-fa315f666e95', 4, 'When my favorite things change, it’s okay to feel unsure. Talking about my feelings and finding new things to enjoy can help me adapt to the changes.', 'cosas', '📦');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 1, 'Getting ready for a special event can be exciting. I am learning how to prepare for it.', 'listo', '✅'),
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 2, 'Special events are fun times with family and friends. They might happen at school, home, or other places. When there is a special event coming up, my parents will tell me about it. They will help me get ready.', 'vestirse', '👕'),
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 3, 'First, we talk about what the event will be like. We may dress differently or do special activities. My parents will make sure I know what to expect.', 'hablar', '🗣️'),
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 4, 'Next, we plan how to get there. It could be by car, bus, or walking. Knowing the way helps me feel more comfortable.', 'coche', '🚗'),
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 5, 'During the event, I can have fun and enjoy myself. If I need a break, I can let my parents know. They will understand.', 'divertido', '😄'),
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 6, 'After the event, we talk about what happened. I can share my favorite parts and any concerns I had. This helps me learn from the experience.', 'hablar', '🗣️'),
  ('7dba8fcc-66f6-9aba-6ea3-85366ea8c3b8', 7, 'Preparing for a special event is an opportunity to create happy memories. I will listen to my parents and follow their guidance to make the most of the event.', 'escuchar', '👂');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d7fa7507-5034-e3bc-9051-6a938bf13874', 1, 'We live on a planet full of amazing creatures and beautiful nature. It''s important to understand and respect them.', 'naturaleza', '🌿'),
  ('d7fa7507-5034-e3bc-9051-6a938bf13874', 2, 'Nature is home to many animals, plants, and trees. They all have their own special place in the world. Animals need our care and protection. We can help by not littering or harming their homes.', 'naturaleza', '🌿'),
  ('d7fa7507-5034-e3bc-9051-6a938bf13874', 3, 'When we visit parks or go for walks, we should be gentle with the plants and animals. We can watch them from a distance and appreciate their beauty without disturbing them. This helps keep them safe and happy.', 'ir', '🚶'),
  ('d7fa7507-5034-e3bc-9051-6a938bf13874', 4, 'It''s also important to remember that some animals might feel scared if we get too close. We can show kindness by giving them space and letting them be themselves.', 'importante', '❗'),
  ('d7fa7507-5034-e3bc-9051-6a938bf13874', 5, 'Respecting nature and animals is part of being a good friend to our planet. Let''s always treat them with love and care.', 'naturaleza', '🌿');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2204be7b-a5da-18b0-8d35-4d9e51fb1700', 1, 'My family is going to have a new baby! Mommy''s tummy is getting bigger and bigger. We are all very excited!', 'familia', '👨‍👩‍👧‍👦'),
  ('2204be7b-a5da-18b0-8d35-4d9e51fb1700', 2, 'When the new baby comes, things will change in our house. Mommy and Daddy will need to take care of the baby a lot. They might not be able to play with me as much as before.', 'nuevo', '🆕'),
  ('2204be7b-a5da-18b0-8d35-4d9e51fb1700', 3, 'Sometimes babies cry a lot because they can''t talk yet. It might be loud and make me feel upset or overwhelmed. But it''s okay, because babies cry to let us know what they need.', 'a veces', '⏳'),
  ('2204be7b-a5da-18b0-8d35-4d9e51fb1700', 4, 'I might have to share my toys and space with the new baby. Sharing can be hard sometimes, but it''s important to be kind and patient. I can show the baby how to play with toys gently.', 'compartir', '🤲'),
  ('2204be7b-a5da-18b0-8d35-4d9e51fb1700', 5, 'Having a new sibling means there will be changes in our family. Even though it might be different and challenging at times, it also means more love and fun. I am going to be a great big brother/sister!', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('bf72bc54-9051-1807-0989-4b97f8b41f7c', 1, 'Emotions are feelings we have inside. They can be happy, sad, excited, or even scared. Understanding our emotions helps us know how to react in different situations.', 'sentimientos', '💗'),
  ('bf72bc54-9051-1807-0989-4b97f8b41f7c', 2, 'There are many types of emotions. Happy is when we feel good and smile. Sad is when we feel down and might cry. Excited is when we feel like jumping up and down. Scared is when we feel afraid and want to stay safe.', 'muchos', '✨'),
  ('bf72bc54-9051-1807-0989-4b97f8b41f7c', 3, 'Sometimes, we may feel a mix of emotions at the same time. For example, feeling happy and excited before going on a trip but also a bit nervous about flying. It''s okay to have mixed feelings.', 'a veces', '⏳'),
  ('bf72bc54-9051-1807-0989-4b97f8b41f7c', 4, 'It''s important to recognize our emotions and talk about them with someone we trust. This way, we can understand why we feel a certain way and find ways to cope with those feelings.', 'importante', '❗'),
  ('bf72bc54-9051-1807-0989-4b97f8b41f7c', 5, 'Understanding our emotions is like understanding colors - each one is unique and tells us something important. By recognizing and expressing our feelings, we can learn more about ourselves and how to navigate the world around us.', 'gustar', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a651f705-c1bf-e7a4-5215-fa18795e7db5', 1, 'Growing stronger through empathy is like building a superpower in my heart. It helps me understand how others feel and be kind to them.', 'gustar', '👍'),
  ('a651f705-c1bf-e7a4-5215-fa18795e7db5', 2, 'Empathy is when I can imagine how someone else feels. If a friend falls down and scrapes their knee, I might remember how it felt when I fell once. I know it hurt, so I can guess that my friend''s knee hurts too. That''s empathy!', 'alguien', '✨'),
  ('a651f705-c1bf-e7a4-5215-fa18795e7db5', 3, 'When I see someone crying, I may think about a time when I was sad. I remember how I wanted someone to comfort me. So, I can offer a hug or ask if they need help. That''s using empathy to be kind.', 'ver', '👀'),
  ('a651f705-c1bf-e7a4-5215-fa18795e7db5', 4, 'Sometimes, people have feelings inside that they don''t show on the outside. Maybe a classmate looks fine but feels worried about a test. If I pay attention and use my empathy, I might notice their worry and offer some encouragement.', 'atencion', '📢'),
  ('a651f705-c1bf-e7a4-5215-fa18795e7db5', 5, 'By growing stronger through empathy, I become better at understanding others'' feelings. This makes me a good friend and helps me connect with people in a caring way.', 'sentimientos', '💗'),
  ('a651f705-c1bf-e7a4-5215-fa18795e7db5', 6, 'Growing stronger through empathy means having a big heart full of kindness. I will keep practicing empathy to build my superpower of understanding and helping others.', 'corazon', '❤️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('207f3e2a-f3d9-342a-4a2c-43e3414fe4bf', 1, 'Halloween is a fun holiday where people get to dress up in costumes. It''s exciting to pretend to be someone or something else for a day.', 'divertido', '😄'),
  ('207f3e2a-f3d9-342a-4a2c-43e3414fe4bf', 2, 'During Halloween, children and adults wear different costumes. Some are spooky like ghosts and witches, while others are funny like superheroes and animals. People decorate their houses with pumpkins, spiders, and cobwebs to make them look scary or silly.', 'ninos', '👧'),
  ('207f3e2a-f3d9-342a-4a2c-43e3414fe4bf', 3, 'Trick-or-treating is a popular activity on Halloween. Children go from house to house saying "trick or treat" and receive candy or treats. It''s important to only visit houses with lights on and to say thank you after receiving treats.', 'gracias', '🙏'),
  ('207f3e2a-f3d9-342a-4a2c-43e3414fe4bf', 4, 'Dressing up in costumes and going trick-or-treating can be so much fun on Halloween. I will have a great time pretending to be someone else for the day.', 'mucho', '📈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('07ce13ad-71ba-401f-43da-be0800937672', 1, 'In sports and games, sometimes we win and sometimes we lose. It''s important to remember that winning isn''t everything, and how we handle both wins and losses is what truly matters.', 'deporte', '⚽'),
  ('07ce13ad-71ba-401f-43da-be0800937672', 2, 'When we win, it feels great! We feel proud of ourselves and our team. We celebrate our achievements and cheer for each other. But it''s also important to be humble in victory. We should congratulate the other team and show respect for their efforts. Winning gracefully means being a good sport and not bragging or showing off.', 'sentir', '💓'),
  ('07ce13ad-71ba-401f-43da-be0800937672', 3, 'On the other hand, when we lose, it can be disappointing and frustrating. It''s okay to feel sad or upset about losing, but it''s important to handle it with grace. We should shake hands with the opposing team and say "good game." We can learn from our mistakes and use them as motivation to improve for next time. Losing gracefully means accepting defeat with dignity and respecting the skills of the other team.', 'otro', '🔄'),
  ('07ce13ad-71ba-401f-43da-be0800937672', 4, 'Whether we win or lose, what matters most is how we conduct ourselves. Celebrating wins with humility and handling losses with grace shows true sportsmanship. Remember, it''s not just about the outcome, but also about the effort, teamwork, and enjoyment of the game. Let''s always strive to be good sports and make every game a positive experience for everyone involved.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2ab601a7-48bf-07d0-090f-0acb6ff9bd25', 1, 'Every day, I try my best to do many things. Sometimes, these things can be hard for me, but I keep trying.', 'dia', '☀️'),
  ('2ab601a7-48bf-07d0-090f-0acb6ff9bd25', 2, 'When I work hard and make progress, even if it''s just a little bit, that''s a small victory! It could be finishing my homework, sharing a toy, or saying "hello" to a friend. These are all small victories that show how strong and capable I am.', 'trabajar', '💼'),
  ('2ab601a7-48bf-07d0-090f-0acb6ff9bd25', 3, 'It''s important to celebrate these small victories because they show that I am growing and learning every day. They help me feel proud of myself and give me the confidence to keep trying new things.', 'importante', '❗'),
  ('2ab601a7-48bf-07d0-090f-0acb6ff9bd25', 4, 'Every time I achieve something, no matter how small, it''s a reason to celebrate. Small victories show how strong and capable I am becoming. So, let''s celebrate each step forward on this journey of growth and learning.', 'tiempo', '⏰');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('25632363-7ceb-aea9-d5df-025632ec2655', 1, 'Watching faces and listening with my eyes is an important way to understand how people are feeling.', 'ojos', '👀'),
  ('25632363-7ceb-aea9-d5df-025632ec2655', 2, 'When I look at someone’s face, I can see if they are happy, sad, or mad. Their eyes, mouth, and eyebrows can show me what they are feeling. If someone is smiling and their eyes are bright, they might be happy. But if their eyebrows are down and their mouth is frowning, they might be sad.', 'mirar', '👀'),
  ('25632363-7ceb-aea9-d5df-025632ec2655', 3, 'Sometimes, people don’t say how they feel out loud. Instead, they show it on their face. This is called non-verbal communication. It’s like having a secret code that tells us how someone feels without using words.', 'a veces', '⏳'),
  ('25632363-7ceb-aea9-d5df-025632ec2655', 4, 'Listening with my eyes means paying attention to more than just the words someone says. I can watch their body language too. If someone is standing tall and looking straight ahead, they might be confident. But if they are hunched over and avoiding eye contact, they might be shy or nervous.', 'ojos', '👀'),
  ('25632363-7ceb-aea9-d5df-025632ec2655', 5, 'It’s important for me to practice watching faces and listening with my eyes so I can understand others better. When I know how someone feels, I can respond in a way that helps them feel understood and supported.', 'importante', '❗'),
  ('25632363-7ceb-aea9-d5df-025632ec2655', 6, 'Watching faces and listening with my eyes helps me connect with others and build strong relationships. By paying attention to non-verbal cues, I can show empathy and kindness towards those around me.', 'ojos', '👀');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 1, 'Eyes can tell us a lot without saying a word. They are like windows to our feelings and thoughts. What can eyes say?', 'ojos', '👀'),
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 2, 'When someone is happy, their eyes might sparkle or crinkle at the edges. It''s like they have little smiles in their eyes.', 'alguien', '✨'),
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 3, 'If someone is sad, their eyes may look downcast or watery. Sometimes, their eyes avoid meeting mine.', 'alguien', '✨'),
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 4, 'Angry eyes might narrow or stare intensely. They could show frustration or annoyance.', 'enfadado', '😤'),
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 5, 'When someone is curious, their eyes widen with interest. They may look around eagerly.', 'alguien', '✨'),
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 6, 'Scared eyes often widen too, showing fear or worry. They might dart around anxiously.', 'miedo', '😨'),
  ('10a65c3a-3c92-7c97-56b2-273296a63bdf', 7, 'Eyes can speak volumes even when words are silent. Paying attention to people''s eyes helps us understand how they feel. Let''s keep watching and learning from what eyes say.', 'ojos', '👀');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6a4f2649-c43f-fea7-73a0-88c63a776148', 1, 'Climate change is a very important topic. It affects the world we live in and our future.', 'cambio', '🔄'),
  ('6a4f2649-c43f-fea7-73a0-88c63a776148', 2, 'The Earth''s climate is changing. This means that the weather patterns are different from what they used to be. Some places are getting hotter, some colder, and some wetter or drier. These changes can cause problems for people, animals, and plants.', 'tierra', '🌍'),
  ('6a4f2649-c43f-fea7-73a0-88c63a776148', 3, 'We can help by doing small things every day. We can turn off lights when we leave a room, use less water, recycle, and plant trees. These actions may seem small, but together they make a big difference. By taking care of the Earth, we can help protect it for the future.', 'ayuda', '🆘'),
  ('6a4f2649-c43f-fea7-73a0-88c63a776148', 4, 'Climate change is an important issue. We can all do our part to take care of the Earth. Together, we can make a positive impact on the world around us.', 'cambio', '🔄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('572f11c9-db0b-9ba3-54ea-3c815760eb20', 1, 'Keeping germs away is important for staying healthy. Germs are tiny things that can make us sick. Washing hands and covering coughs help keep germs from spreading.', 'importante', '❗'),
  ('572f11c9-db0b-9ba3-54ea-3c815760eb20', 2, 'When I sneeze or cough, I cover my mouth with my elbow or a tissue. This helps stop germs from flying through the air. If I use a tissue, I throw it away right after. Then, I wash my hands with soap and water for at least 20 seconds.', 'lavarse', '🧼'),
  ('572f11c9-db0b-9ba3-54ea-3c815760eb20', 3, 'Before eating and after using the bathroom, I always wash my hands. Soap and water work best to get rid of germs. I scrub all over my hands, including between my fingers and under my nails.', 'lavarse', '🧼'),
  ('572f11c9-db0b-9ba3-54ea-3c815760eb20', 4, 'If I see someone who looks sick, I try to stay a little distance away. It''s okay to tell an adult if someone seems unwell. They can help keep everyone safe.', 'ver', '👀'),
  ('572f11c9-db0b-9ba3-54ea-3c815760eb20', 5, 'By washing my hands and being careful around sick people, I can help keep myself and others healthy. Remembering to cover my coughs and sneezes also stops germs from spreading.', 'lavarse', '🧼');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6da9dded-4c3f-0bb1-791d-00e47b38557f', 1, 'Learning new rules can be challenging, but it helps me adapt to different situations.', 'aprender', '📖'),
  ('6da9dded-4c3f-0bb1-791d-00e47b38557f', 2, 'Sometimes, rules change at home, school, or in the community. This can feel confusing at first, but it''s a way for everyone to stay safe and get along better.', 'a veces', '⏳'),
  ('6da9dded-4c3f-0bb1-791d-00e47b38557f', 3, 'When I learn new rules, I can ask questions if I don''t understand. It''s okay to need help figuring out what to do.', 'aprender', '📖'),
  ('6da9dded-4c3f-0bb1-791d-00e47b38557f', 4, 'Practicing the new rules makes them easier to remember. Just like when I learned how to tie my shoes, with practice, I got better at it!', 'nuevo', '🆕'),
  ('6da9dded-4c3f-0bb1-791d-00e47b38557f', 5, 'It''s important to follow the rules even if they seem different from before. Rules are there to keep us all on the same page and make things run smoothly.', 'instrucciones', '📋'),
  ('6da9dded-4c3f-0bb1-791d-00e47b38557f', 6, 'Learning new rules may feel tricky, but it helps me grow and handle changes better.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 1, 'Sometimes, we encounter new things or situations that we haven''t experienced before. It''s okay to feel unsure or nervous about trying something new.', 'a veces', '⏳'),
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 2, 'When faced with something new, it can be helpful to take a deep breath and remind ourselves that it''s an opportunity to learn and grow. We can approach it step by step, just like solving a puzzle.', 'respirar', '🫁'),
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 3, 'First, we can gather information about the new thing or situation. We can ask questions, observe others, or do some research to understand what it''s all about.', 'nuevo', '🆕'),
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 4, 'Next, we can think about how we might feel when trying this new thing. It''s normal to have mixed emotions, but remember that it''s okay to feel excited, curious, or even a little scared.', 'pensar', '🤔'),
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 5, 'Then, we can make a plan. Breaking down the task into smaller steps can make it more manageable. We can set goals for ourselves and celebrate each small achievement along the way.', 'mas', '➕'),
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 6, 'If we encounter any challenges or obstacles, we can try different strategies to overcome them. We can ask for help from a trusted adult or use our problem-solving skills to find alternative solutions.', 'ayuda', '🆘'),
  ('702b254f-48fc-9559-4188-0e891a5c9cdb', 7, 'Trying something new can be an exciting adventure. By taking small steps, gathering information, making a plan, and being open to learning, we can discover new interests, abilities, and strengths within ourselves. Let''s embrace new experiences and enjoy the journey of trying something new!', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1f3ba608-1c43-22cc-63dd-daf50aa0b3f3', 1, 'Adults need time alone. It’s important for them to have moments when they can relax and recharge.', 'necesitar', '❗'),
  ('1f3ba608-1c43-22cc-63dd-daf50aa0b3f3', 2, 'Just like how I enjoy my quiet time or doing activities by myself, adults also need their own space sometimes. They may want to read a book, take a walk, or simply sit quietly. This helps them feel calm and happy.', 'gustar', '👍'),
  ('1f3ba608-1c43-22cc-63dd-daf50aa0b3f3', 3, 'When adults say they need some time alone, it doesn’t mean they don’t like us or that we did something wrong. It just means they need a break to feel better. Adults have many responsibilities and tasks to do each day, so having some time alone is their way of taking care of themselves.', 'decir', '💬'),
  ('1f3ba608-1c43-22cc-63dd-daf50aa0b3f3', 4, 'If an adult asks for some alone time, it’s important to respect their request. We can use this time to play independently, draw a picture, or engage in a quiet activity until the adult is ready to spend time together again.', 'adulto', '🧑'),
  ('1f3ba608-1c43-22cc-63dd-daf50aa0b3f3', 5, 'Remember, adults need time alone to feel good and be at their best. Giving them space shows that we understand and care about their well-being. So, when an adult says they need some alone time, let''s give them that space to relax and recharge.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8646b920-51d5-0984-5ae4-f9520a6342cc', 1, 'Everyone has big emotions sometimes. Big emotions can feel like a storm inside us, making it hard to think clearly or stay calm.', 'todos', '🌐'),
  ('8646b920-51d5-0984-5ae4-f9520a6342cc', 2, 'When I have big emotions, my heart beats fast and my body might feel shaky. It’s important to remember that these feelings are normal, even if they’re strong.', 'corazon', '❤️'),
  ('8646b920-51d5-0984-5ae4-f9520a6342cc', 3, 'Taking deep breaths can help calm the storm inside me. Inhale slowly through my nose, hold for a moment, then exhale slowly through my mouth. This helps bring peace back to my mind and body.', 'respirar', '🫁'),
  ('8646b920-51d5-0984-5ae4-f9520a6342cc', 4, 'I can also try counting to ten or squeezing a stress ball when I feel overwhelmed by big emotions. These actions give me something else to focus on instead of the storm inside me.', 'intentar', '💪'),
  ('8646b920-51d5-0984-5ae4-f9520a6342cc', 5, 'Remember, it''s okay to ask for help when big emotions feel too much to handle alone. My Team is here to support me and guide me through finding ways to manage these big feelings.', 'ayuda', '🆘'),
  ('8646b920-51d5-0984-5ae4-f9520a6342cc', 6, 'Handling big emotions is a skill I can learn. When the storm comes, I will take deep breaths, count to ten, or squeeze a stress ball. My Team will be there to help me weather any emotional storm that comes my way.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('91db1f10-b120-084f-858d-b9e4880cd00b', 1, 'Knowing when to wash my hands is important for staying healthy. Hands can pick up germs from things I touch, like doorknobs or toys. Washing my hands helps get rid of those germs and keeps me and others safe.', 'lavarse', '🧼'),
  ('91db1f10-b120-084f-858d-b9e4880cd00b', 2, 'I should wash my hands at certain times during the day. First, after using the bathroom, it''s essential to wash my hands with soap and water. Second, before eating any meal or snack, washing my hands will help prevent spreading germs. Third, if I cough or sneeze into my hands, it''s a good idea to wash them right away. Lastly, after playing outside or touching animals, washing my hands is necessary to remove dirt and germs.', 'lavarse', '🧼'),
  ('91db1f10-b120-084f-858d-b9e4880cd00b', 3, 'Sometimes, I may not feel like washing my hands, but it''s crucial to remember that doing so keeps me healthy and prevents getting sick. My mom and dad remind me to wash my hands because they care about me and want me to stay well.', 'lavarse', '🧼'),
  ('91db1f10-b120-084f-858d-b9e4880cd00b', 4, 'Remembering to wash my hands at the right times is an important habit. By washing my hands regularly, I am taking care of myself and showing respect for others around me. So, whenever in doubt, just remember: "When should I wash my hands?"', 'lavarse', '🧼');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 1, 'Why rules are friends, not enemies. Rules help us know what to do and keep us safe.', 'normas', '📋'),
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 2, 'Rules are like a guidebook that tells us how to behave in different places. They are there to help everyone get along and have fun together.', 'normas', '📋'),
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 3, 'When we follow the rules, things run smoothly. For example, when we play games, following the rules makes sure everyone has a fair turn and enjoys playing.', 'instrucciones', '📋'),
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 4, 'If we didn''t have rules, things could get confusing or even dangerous. Imagine if there were no rules on the road – it would be chaotic!', 'normas', '📋'),
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 5, 'It''s okay to ask questions about rules if we don''t understand them. Sometimes rules can seem tricky, but asking for clarification helps us learn and follow them better.', 'instrucciones', '📋'),
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 6, 'Remember, rules are not meant to make us feel bad or restrict us. They are there to create order and make sure everyone is treated fairly.', 'recordar', '📝'),
  ('8df1abae-7fad-d451-8d9f-da195fc57ae9', 7, 'Why rules are friends, not enemies. I will try my best to follow the rules because they help me and others stay safe and have a good time.', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1975685e-2cbb-989f-e524-650d0686b789', 1, 'Making friends in new places can be exciting and a little bit scary. It''s like starting a new adventure, where we get to meet new people and learn new things.', 'amigos', '🤝'),
  ('1975685e-2cbb-989f-e524-650d0686b789', 2, 'When I go to a new place, I might feel a little nervous at first. That''s okay! Lots of people feel that way when they''re somewhere new. Sometimes, it takes time to feel comfortable in a new place, and that''s normal too.', 'ir', '🚶'),
  ('1975685e-2cbb-989f-e524-650d0686b789', 3, 'I can start by saying "hello" to someone or smiling at them. If I see other kids playing, I can ask if I can join in. They might say yes, and then we can play together. If they say no, that''s okay too. There are always more chances to make friends.', 'empezar', '🏁'),
  ('1975685e-2cbb-989f-e524-650d0686b789', 4, 'If I''m not sure what to do, I can look around and see what other kids are doing. Maybe there''s a game I can join, or an activity I can try. It''s okay to take my time and find something I enjoy doing.', 'mirar', '👀'),
  ('1975685e-2cbb-989f-e524-650d0686b789', 5, 'Sometimes, making friends means sharing with others and taking turns. This helps us all have fun together and shows that we care about each other''s feelings. When we share and take turns, it makes the time we spend together even better.', 'esperar', '⏳'),
  ('1975685e-2cbb-989f-e524-650d0686b789', 6, 'As I explore new places and meet new people, I will remember that making friends is an adventure. I can take my time, be friendly, and enjoy getting to know others. Each new friend I make adds something special to my life.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1708ae40-01de-2e58-c3c6-894006bb543b', 1, 'Exercise is an important activity that helps make our bodies strong and healthy. When we exercise, we move our bodies in different ways to keep them fit and working well.', 'ejercicio', '🏋️'),
  ('1708ae40-01de-2e58-c3c6-894006bb543b', 2, 'When we exercise, our heart beats faster and we breathe harder. This helps our hearts stay healthy and makes our muscles stronger. Exercise can be fun too! We can run, jump, dance, or play sports with friends. These activities help us feel good and have lots of energy.', 'ejercicio', '🏋️'),
  ('1708ae40-01de-2e58-c3c6-894006bb543b', 3, 'Sometimes, it might be hard to start exercising, but once we begin, it gets easier and more enjoyable. We can set small goals for ourselves, like playing outside for 30 minutes each day or trying a new sport every month. By doing this, we can build up our strength and endurance over time.', 'a veces', '⏳'),
  ('1708ae40-01de-2e58-c3c6-894006bb543b', 4, 'Exercising regularly is good for our bodies and minds. It keeps us healthy, happy, and full of energy. So, let''s remember to include some form of exercise in our daily routine to stay strong and active. Let''s enjoy moving our bodies and feeling great!', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4bff6969-d7f6-325e-eefd-b1036a4e3b59', 1, 'Giving others their space is an important part of being respectful and considerate. It means understanding that everyone has their own personal bubble, just like I do.', 'importante', '❗'),
  ('4bff6969-d7f6-325e-eefd-b1036a4e3b59', 2, 'When we give others their space, it means not standing too close to them or touching them without permission. We all have different comfort zones, and it''s important to respect that.', 'dar', '🎁'),
  ('4bff6969-d7f6-325e-eefd-b1036a4e3b59', 3, 'Sometimes, people need more personal space than others. Some people feel uncomfortable if someone stands too close to them, while others may not mind. It''s important to pay attention to the cues they give us, like if they step back or look uncomfortable.', 'espacio personal', '↔️'),
  ('4bff6969-d7f6-325e-eefd-b1036a4e3b59', 4, 'We can also ask for permission before touching someone. If we want to hug or hold hands with a friend, we can say, "Can I give you a hug?" or "Would you like to hold hands?" This way, we are respecting their boundaries and giving them the choice.', 'alguien', '✨'),
  ('4bff6969-d7f6-325e-eefd-b1036a4e3b59', 5, 'It''s also important to remember that personal space extends beyond physical distance. We should also respect people''s privacy and not invade their personal belongings or personal information.', 'espacio personal', '↔️'),
  ('4bff6969-d7f6-325e-eefd-b1036a4e3b59', 6, 'Giving others their space shows that we care about their feelings and boundaries. By being aware of personal space and respecting it, we can build healthy relationships and avoid misunderstandings. Let''s always remember to give others their space and treat them with kindness and respect.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 1, 'Understanding classroom expectations is important for learning and having a good time at school.', 'importante', '❗'),
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 2, 'In the classroom, we have rules to help us learn and stay safe. The teacher will explain these rules so we know what is expected of us. We need to listen carefully when the teacher talks about how we should behave in class.', 'escuchar', '👂'),
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 3, 'When the teacher asks us to sit down, it means we should find a chair and sit quietly. Sitting down helps everyone see and hear better during lessons.', 'maestro', '👩‍🏫'),
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 4, 'Raising our hand is another important rule. When we want to speak or ask a question, we raise our hand. This way, the teacher knows we have something to say and can call on us.', 'mano', '🤚'),
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 5, 'Following directions is also key. If the teacher asks us to line up, we stand in a straight line behind each other. This makes it easier for everyone to move together without bumping into each other.', 'instrucciones', '📋'),
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 6, 'Remembering to use inside voices is essential. Inside voices are quiet and calm, just like when we''re talking to someone nearby. It helps keep the classroom peaceful and focused on learning.', 'dentro', '🏠'),
  ('dce57872-a5e2-c4aa-37ad-7d63cc8e4f50', 7, 'Understanding classroom expectations helps us have a great time at school. Following rules like sitting down, raising our hand, following directions, and using inside voices make the classroom a fun place to learn and grow.', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b0829c33-0282-e1d9-580e-41d39b824858', 1, 'Helping others is important. When we help someone, it makes them feel happy and cared for.', 'importante', '❗'),
  ('b0829c33-0282-e1d9-580e-41d39b824858', 2, 'Sometimes people need help with different things. It could be carrying something heavy, opening a door, or even just listening when they are sad. When I see someone who needs help, I can offer my assistance. I can ask, "Can I help you?" or "Do you need any help?"', 'a veces', '⏳'),
  ('b0829c33-0282-e1d9-580e-41d39b824858', 3, 'When I help others, it shows that I care about them. It''s like giving them a warm hug or a big smile. Helping others also makes me feel good inside. It''s nice to know that I made someone''s day a little better.', 'ayuda', '🆘'),
  ('b0829c33-0282-e1d9-580e-41d39b824858', 4, 'If I see someone struggling, I can think about how I would feel if I were in their shoes. Would I want someone to help me? By putting myself in their place, I can understand why helping is important.', 'ver', '👀'),
  ('b0829c33-0282-e1d9-580e-41d39b824858', 5, 'Helping hands: how to support others. When I help others, it makes them happy and shows that I care. I will try to look out for opportunities to lend a helping hand.', 'manos', '🤚');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('629f1552-33af-3e4d-1ad3-f012c5826bc2', 1, 'Understanding emotions is like reading faces. Faces can show how people feel inside. When we look at someone’s face, we can see if they are happy, sad, angry, or scared.', 'gustar', '👍'),
  ('629f1552-33af-3e4d-1ad3-f012c5826bc2', 2, 'For example, when someone is happy, their eyes might sparkle, and they may smile with their mouth. They might even laugh or jump for joy. If someone is sad, their eyes might look down, and their mouth might frown. They might cry softly or want to be alone.', 'alguien', '✨'),
  ('629f1552-33af-3e4d-1ad3-f012c5826bc2', 3, 'When a person is angry, their eyebrows might come together, and their eyes could look fierce. Their mouth might tighten, and they might stomp their feet or raise their voice. And when someone is scared, their eyes might widen, and their body might freeze. They might shake or try to hide.', 'persona', '🧑'),
  ('629f1552-33af-3e4d-1ad3-f012c5826bc2', 4, 'It''s important to remember that everyone feels different emotions sometimes. It''s okay to feel happy, sad, angry, or scared. What matters is how we express these feelings in a safe and respectful way.', 'importante', '❗'),
  ('629f1552-33af-3e4d-1ad3-f012c5826bc2', 5, 'Reading faces helps us understand emotions better. When we pay attention to how people''s faces look, we can connect with them and show empathy. Let''s keep practicing reading faces to build stronger relationships with others.', 'atencion', '📢');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('010cb9ed-4b34-e879-4742-6892ba02d27a', 1, 'Recognizing and reacting to disappointment is an important skill. When someone feels disappointed, it means they were hoping for something good to happen, but it didn''t turn out the way they wanted. Understanding this feeling can help us support others when they are sad or upset.', 'importante', '❗'),
  ('010cb9ed-4b34-e879-4742-6892ba02d27a', 2, 'Yesterday, my friend Sarah was excited about her soccer game. She practiced a lot and really wanted her team to win. But during the game, the other team scored more goals. Sarah''s team lost, and she felt disappointed. I saw that Sarah looked sad, so I went over and said, "I''m sorry your team didn''t win. You played great." It made her feel better knowing that I understood how she felt.', 'ayer', '✨'),
  ('010cb9ed-4b34-e879-4742-6892ba02d27a', 3, 'Sometimes, we may also feel disappointed. Maybe we don''t get to do something we were looking forward to, like going to the park. It''s okay to feel disappointed, and it''s important to talk about our feelings with someone we trust.', 'a veces', '⏳'),
  ('010cb9ed-4b34-e879-4742-6892ba02d27a', 4, 'Recognizing when someone is disappointed and responding with kindness shows that we care about their feelings. I will try to be understanding and supportive when others feel disappointed. By showing empathy, we can help each other through tough times.', 'alguien', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e4fa107b-adc9-e637-fb26-5cff5dc0309d', 1, 'Meeting new friends can be exciting and fun.', 'nuevo', '🆕'),
  ('e4fa107b-adc9-e637-fb26-5cff5dc0309d', 2, 'When we go to the park, there may be other children playing. They could become my new friends. Making new friends means saying hello and smiling. I can ask them if they want to play together. We might swing on the swings or slide down the slide. It''s nice to share toys and take turns. If they don''t want to play, that''s okay too. Sometimes children are shy or busy with their own games. Meeting new friends is like starting a new adventure. I can learn about them and they can learn about me.', 'esperar', '⏳'),
  ('e4fa107b-adc9-e637-fb26-5cff5dc0309d', 3, 'Making new friends at the park can bring joy and new experiences. I will try to say hello and make new friends when I visit the park.', 'nuevo', '🆕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 1, 'At school, we have a special time called snack time. It''s a time when we get to eat yummy food and take a break from our activities.', 'escuela', '🏫'),
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 2, 'During snack time, there are some important rules that we need to follow. First, we need to wash our hands before touching any food. This helps keep us healthy and prevents germs from spreading.', 'instrucciones', '📋'),
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 3, 'Next, we need to sit at the table while eating our snacks. Sitting down helps us stay safe and makes it easier for everyone to enjoy their food without any accidents.', 'necesitar', '❗'),
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 4, 'We also need to use our manners during snack time. That means chewing with our mouths closed, not talking with food in our mouths, and saying "please" and "thank you" when asking for or receiving something.', 'gracias', '🙏'),
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 5, 'It''s important to remember that we should only eat our own snacks and not take food from others without asking. Everyone has their own special snacks, and it''s not polite to take someone else''s food without permission.', 'importante', '❗'),
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 6, 'Lastly, when snack time is over, we need to clean up after ourselves. We can throw away any trash in the designated bins and put our dishes and utensils in the sink or dishwasher.', 'merienda', '🍎'),
  ('0d37c208-caa0-6699-2c8a-e1443f214b3d', 7, 'Snack time is a fun and delicious part of our day. By following these snack time rules, we can all enjoy our snacks together and have a great time. I will try my best to follow these rules and be a good snacker!', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8a60821e-cdd8-fb9b-4994-bc4d585214af', 1, 'Sometimes, I feel sad when someone I care about is not with me. It’s okay to have these feelings.', 'a veces', '⏳'),
  ('8a60821e-cdd8-fb9b-4994-bc4d585214af', 2, 'When I miss someone, it means I wish they were here with me. Maybe I miss my friend who moved away or a family member who lives far away. When I miss them, I can think about the fun times we had together. I can also talk to them on the phone or send them a message to let them know I’m thinking of them.', 'alguien', '✨'),
  ('8a60821e-cdd8-fb9b-4994-bc4d585214af', 3, 'It''s normal to feel this way, and it''s important to remember that missing someone doesn''t mean they don''t care about us. They might be missing us too!', 'sentir', '💓'),
  ('8a60821e-cdd8-fb9b-4994-bc4d585214af', 4, 'Feeling sad because I miss someone is okay. I can remember the good times we shared and find ways to stay connected, even if we''re apart.', 'sentimiento', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('07576fe1-b17f-7e3b-c904-db87c0e25188', 1, 'New Year is a special time when people all around the world celebrate. Let''s learn how to say "Happy New Year" in many languages!', 'nuevo', '🆕'),
  ('07576fe1-b17f-7e3b-c904-db87c0e25188', 2, 'In Spanish, we say "¡Feliz Año Nuevo!" In French, it''s "Bonne année!" In Chinese, it''s "Xīnnián kuàilè!" In Arabic, it''s "سنة جديدة سعيدة!" In Hindi, it''s "नया साल मुबारक हो!"', 'decir', '💬'),
  ('07576fe1-b17f-7e3b-c904-db87c0e25188', 3, 'Different countries have different ways of celebrating the New Year. Some have fireworks, some have big feasts, and others have special traditions.', 'diferente', '🌈'),
  ('07576fe1-b17f-7e3b-c904-db87c0e25188', 4, 'Learning about other cultures and languages is exciting! Saying "Happy New Year" in different languages shows respect for diversity and brings joy to people all over the world. Let''s spread happiness by learning new things together!', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('68d66670-d2ad-aa4b-9bc9-42e08f28c8ff', 1, 'My family is like a team. Each person has their own special job to do, and together we make our home a happy place.', 'familia', '👨‍👩‍👧‍👦'),
  ('68d66670-d2ad-aa4b-9bc9-42e08f28c8ff', 2, 'I have some important responsibilities in my family. I help set the table for dinner. I put away my toys after playing with them. When it''s time to feed our pet, I help by giving them food and water. These are all things that help our family run smoothly.', 'algunos', '✨'),
  ('68d66670-d2ad-aa4b-9bc9-42e08f28c8ff', 3, 'Sometimes, I might forget to do these things, but that''s okay. My mom or dad will remind me, and then I can finish my responsibility. It feels good to help out and be part of the team.', 'a veces', '⏳'),
  ('68d66670-d2ad-aa4b-9bc9-42e08f28c8ff', 4, 'In my family, everyone has something they do to help. I''m glad to have my responsibilities because they show that I am an important part of our family team.', 'familia', '👨‍👩‍👧‍👦');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4cf2cd22-d26c-362d-18bb-9ae7920d054f', 1, 'Taking a shower or bath is an important part of staying clean and refreshed. It''s something many people do every day to feel good.', 'importante', '❗'),
  ('4cf2cd22-d26c-362d-18bb-9ae7920d054f', 2, 'When I take a shower or bath, it helps to keep my body clean and fresh. First, I need to go into the bathroom and close the door for privacy. Then, I can take off my clothes and turn on the water to make sure it''s at a comfortable temperature. After that, step carefully into the shower or bathtub and start by washing my hair with shampoo and then rinsing it. I can also use conditioner if needed. Next, wash my skin with soap and rinse well. When I am done, turn off the water and dry myself with a towel before putting on clean clothes.', 'lavarse', '🧼'),
  ('4cf2cd22-d26c-362d-18bb-9ae7920d054f', 3, 'It''s important to remember that taking a shower or bath is a way to take care of myself and stay healthy. It''s something I can learn to do on my own, and if I have any questions, I can always ask for help from someone I trust.', 'ayuda', '🆘'),
  ('4cf2cd22-d26c-362d-18bb-9ae7920d054f', 4, 'Taking a shower or bath helps me feel clean and refreshed. With practice, I can learn to do it on my own and take care of myself. If I ever need help, I know I can ask someone I trust.', 'sentir', '💓');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('edb48a42-43bd-d85f-daff-6b026b6462af', 1, 'Sometimes, we need to say "no" to keep ourselves safe. Saying "no" is an important way to protect ourselves from things that might not be good for us.', 'a veces', '⏳'),
  ('edb48a42-43bd-d85f-daff-6b026b6462af', 2, 'There are times when someone we don’t know tries to talk to us or offer us something. It’s okay to say "no" and walk away if we feel uncomfortable. We can also say "no" if someone asks us to do something that we know is wrong or makes us feel scared.', 'alguien', '✨'),
  ('edb48a42-43bd-d85f-daff-6b026b6462af', 3, 'If a stranger wants us to go with them or get into their car, it''s important to remember that we should never go anywhere with someone we don''t know without asking our parents first. Even if the person seems nice, we must always check with our parents or a trusted adult before going anywhere with them.', 'extrano', '🙅'),
  ('edb48a42-43bd-d85f-daff-6b026b6462af', 4, 'We can practice saying "no" in different ways, like using a strong voice and making eye contact. Remember, it''s okay to say "no" to strangers or anyone who makes us feel unsafe.', 'practicar', '🎯'),
  ('edb48a42-43bd-d85f-daff-6b026b6462af', 5, 'Saying "no" is a powerful way to stay safe. If we ever feel unsure or uncomfortable, we can trust ourselves to say "no" and keep ourselves protected.', 'forma', '📐');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('07389632-d97b-f7fc-1b78-0bff059f8c13', 1, 'Asking for help when I don''t understand is important. It''s okay to ask questions if something is unclear.', 'ayuda', '🆘'),
  ('07389632-d97b-f7fc-1b78-0bff059f8c13', 2, 'Sometimes, instructions can be confusing. If I don''t understand what someone is asking me to do, it''s okay to ask for help. Asking for help means finding someone who can explain things in a way that makes sense to me.', 'ayuda', '🆘'),
  ('07389632-d97b-f7fc-1b78-0bff059f8c13', 3, 'When I ask for help, I show that I am responsible and want to learn. It''s better to ask for clarification than to guess and make mistakes. People are happy to help when I ask politely.', 'ayuda', '🆘'),
  ('07389632-d97b-f7fc-1b78-0bff059f8c13', 4, 'Asking for help when I don''t understand is a good choice. It helps me learn and avoid making errors. Remember, it''s okay to ask questions if something is unclear.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('63be80de-cdbf-97a4-e54a-e10271fc465b', 1, 'When I feel upset, I can use my words to tell someone how I am feeling.', 'sentir', '💓'),
  ('63be80de-cdbf-97a4-e54a-e10271fc465b', 2, 'I may feel upset when things don’t go the way I want them to, or when something changes suddenly. It’s okay to feel upset sometimes. When I feel upset, I can take a deep breath and think about what is making me feel this way. Then, I can use my words to tell an adult how I am feeling. I can say, “I feel upset because…”', 'respirar', '🫁'),
  ('63be80de-cdbf-97a4-e54a-e10271fc465b', 3, 'Using my words helps adults understand how they can help me. They might give me a hug, talk to me about it, or help me find a solution. It’s important for me to remember that using my words is a good way to express my feelings and get the support I need.', 'entender', '🧠'),
  ('63be80de-cdbf-97a4-e54a-e10271fc465b', 4, 'When I’m upset, I can use my words to tell someone how I am feeling.', 'decir', '💬');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('235c30d6-59b8-dc2b-223d-f160ed8ed3de', 1, 'Sharing spaces respectfully is an important skill. It means understanding that everyone has their own personal space, and we need to respect that.', 'espacio personal', '↔️'),
  ('235c30d6-59b8-dc2b-223d-f160ed8ed3de', 2, 'Personal space is like having an invisible bubble around us. When we are close to someone, we need to be aware of their bubble and not invade it without permission. Just like how we wouldn’t want someone to stand too close to us if we don’t feel comfortable.', 'espacio personal', '↔️'),
  ('235c30d6-59b8-dc2b-223d-f160ed8ed3de', 3, 'When we share a space with others, like in a classroom or at home, it’s essential to remember that each person has their own area. We can ask before using someone else''s things or sitting in their spot. Respecting boundaries shows that we care about other people''s feelings and space.', 'compartir', '🤲'),
  ('235c30d6-59b8-dc2b-223d-f160ed8ed3de', 4, 'If we accidentally enter someone''s personal space or touch something that belongs to them without asking, we can apologize and make sure not to do it again. Everyone makes mistakes, but learning from them helps us grow and become more considerate towards others.', 'espacio personal', '↔️'),
  ('235c30d6-59b8-dc2b-223d-f160ed8ed3de', 5, 'Remembering to share spaces respectfully means being mindful of others'' personal bubbles and boundaries. By respecting each other''s space, we show kindness and consideration towards those around us. Let''s always strive to treat others the way we would like to be treated in return.', 'compartir', '🤲');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1900c9d0-4f28-848a-2c08-0a25bf4f293d', 1, 'Understanding the importance of flexibility in life is helpful for me. Being flexible means being able to adjust when things change.', 'cosas', '📦'),
  ('1900c9d0-4f28-848a-2c08-0a25bf4f293d', 2, 'Sometimes, things don’t go as planned. For example, maybe I am used to having art class on Mondays, but one day it changes to Tuesdays. This can be surprising and make me feel uncomfortable at first. It’s okay to feel unsure about changes.', 'a veces', '⏳'),
  ('1900c9d0-4f28-848a-2c08-0a25bf4f293d', 3, 'Being flexible means that even though I may feel unsure or uncomfortable, I can try to adapt to the new schedule. I can talk to my teacher or a friend if I need help understanding why the change happened. They can explain the reasons behind the change and help me feel more comfortable with it.', 'sentir', '💓'),
  ('1900c9d0-4f28-848a-2c08-0a25bf4f293d', 4, 'Flexibility also means being open to trying new things. If I always eat the same lunch every day and one day there’s something different, I can try it out. Who knows, I might discover a new favorite food!', 'abrir', '🔓'),
  ('1900c9d0-4f28-848a-2c08-0a25bf4f293d', 5, 'Being flexible helps me handle changes in routines or environments better. I will remember that it’s okay to feel unsure about changes, but being open-minded and willing to adapt can lead to positive experiences. I will try to embrace flexibility in life to make things easier for myself and those around me.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('419fdffe-c1d5-e8b2-d8d8-94bccb59bc75', 1, 'The world is always changing. Change means things are different from before. Sometimes change can be big, like moving to a new house or getting a new teacher. Other times, change can be small, like trying a new food or wearing a different shirt.', 'mundo', '🌍'),
  ('419fdffe-c1d5-e8b2-d8d8-94bccb59bc75', 2, 'Change happens all around us. The seasons change from winter to spring to summer to fall. Trees change their leaves from green to orange to red. Even people change as they grow older and learn new things.', 'cambio', '🔄'),
  ('419fdffe-c1d5-e8b2-d8d8-94bccb59bc75', 3, 'When something changes, it''s okay to feel unsure or worried. But remember, change can also bring good things. Trying new things helps us learn and grow. It''s like solving a puzzle - each piece fits together to create something new and exciting.', 'sentir', '💓'),
  ('419fdffe-c1d5-e8b2-d8d8-94bccb59bc75', 4, 'The world is always changing, and that''s okay. I can adapt to change by staying positive and open-minded. Embracing change helps me discover new experiences and opportunities.', 'mundo', '🌍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('69827c23-faac-9463-9734-b5275bb467f4', 1, 'When someone gets too close, it can make me feel uncomfortable. Personal space is the area around me where I feel safe and comfortable. It''s important to understand personal space so that everyone feels respected.', 'espacio personal', '↔️'),
  ('69827c23-faac-9463-9734-b5275bb467f4', 2, 'Sometimes people may not realize they are getting too close. They might stand right in front of me or touch me without asking. If this happens, I can politely say, "Please give me some space," or take a step back.', 'a veces', '⏳'),
  ('69827c23-faac-9463-9734-b5275bb467f4', 3, 'It''s okay to tell a teacher or trusted adult if someone keeps invading my personal space even after I''ve asked them to stop. They can help make sure I feel safe.', 'espacio personal', '↔️'),
  ('69827c23-faac-9463-9734-b5275bb467f4', 4, 'Remember, it''s also important for me to respect other people''s personal space. I should ask before hugging or touching someone, and always listen if they say they need more space.', 'espacio personal', '↔️'),
  ('69827c23-faac-9463-9734-b5275bb467f4', 5, 'Understanding personal space helps me and others feel comfortable and safe. By respecting boundaries and communicating clearly, we can create a positive environment where everyone feels valued and respected.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('93c7ebaa-1ddc-4ded-f8e8-29c780f05b5f', 1, 'Working together as a team means that everyone has to be patient and flexible. Sometimes things don’t go exactly as planned, but that’s okay because we can work together to find a solution.', 'equipo', '👥'),
  ('93c7ebaa-1ddc-4ded-f8e8-29c780f05b5f', 2, 'When we are part of a team, it’s important to understand that not everything will happen the way we expect. Sometimes there might be changes or unexpected challenges. For example, if we plan to play a game outside but it starts raining, we have to be flexible and come up with a new plan.', 'equipo', '👥'),
  ('93c7ebaa-1ddc-4ded-f8e8-29c780f05b5f', 3, 'Being patient means waiting calmly and understanding that things may take time. If someone needs extra help or more time to finish their task, we can offer support and encouragement. We can also practice taking turns and listening to each other’s ideas without getting upset if things don’t go our way.', 'paciencia', '🧘'),
  ('93c7ebaa-1ddc-4ded-f8e8-29c780f05b5f', 4, 'Flexibility means being open to change and trying different ways to solve problems. It’s like when we build a tower with blocks and it falls down – instead of feeling frustrated, we can try building it again in a different way. When we show patience and flexibility, we create a positive and supportive environment for our team.', 'abrir', '🔓'),
  ('93c7ebaa-1ddc-4ded-f8e8-29c780f05b5f', 5, 'In teamwork, patience and flexibility are important qualities. By being patient, we can wait calmly and offer support to others. Being flexible allows us to adapt to changes and find new solutions. Together, we can work as a team and achieve great things.', 'paciencia', '🧘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0be71269-9617-b482-6eab-40e17d5a18af', 1, 'Weathering the storm: understanding thunderstorms', 'feliz', '😊'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 2, 'My name is Lily. Sometimes, when dark clouds gather in the sky, it means a thunderstorm is coming. Thunderstorms can be loud and scary, but I have stories to help me understand them better.', 'a veces', '⏳'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 3, 'Thunderstorms happen when warm air rises and cools quickly, making big, fluffy clouds that bring rain and lightning. The sound of thunder is like the sky''s way of talking loudly. Lightning lights up the sky, but it''s not as bright or colorful as fireworks. It''s nature''s own light show!', 'lluvia', '🌧️'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 4, 'During a thunderstorm, it''s important to stay inside where it''s safe. Some people feel scared during storms, and that''s okay. I can talk to my family about how I feel. They will help me feel safe and calm.', 'importante', '❗'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 5, 'If there''s lightning, it''s best to avoid using electronics or taking a bath because lightning can travel through wires and water. Staying away from windows and tall trees is also a good idea.', 'viaje', '🧳'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 6, 'After the storm passes, we might see a rainbow in the sky. Rainbows are like nature''s way of saying everything will be okay. They''re made when sunlight shines through raindrops, creating beautiful colors in the sky.', 'ver', '👀'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 7, 'Weathering the storm: understanding thunderstorms', 'feliz', '😊'),
  ('0be71269-9617-b482-6eab-40e17d5a18af', 8, 'I now know that thunderstorms are a natural part of the weather. They can be loud and bright, but they don''t last forever. I will stay safe indoors and talk to my family if I feel scared. After the storm, I might even get to see a rainbow!', 'saber', '🧠');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 1, 'Sometimes, unexpected things happen that can be scary or dangerous. It''s important to know who we can call for help during emergency situations. Let''s learn about the people we can rely on when we need assistance.', 'a veces', '⏳'),
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 2, 'In an emergency, we can call 911. This is a special number that connects us to people who are trained to help in different emergencies. They will ask questions and send the right kind of help we need.', 'especial', '⭐'),
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 3, 'If there is a fire, we should leave the building right away and call 911 from a safe place. Firefighters are brave heroes who put out fires and keep us safe.', 'deber', '📋'),
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 4, 'When someone is hurt or very sick, we can call an ambulance by dialing 911. Paramedics are skilled at helping people who are injured or not feeling well. They will take us to the hospital if needed.', 'alguien', '✨'),
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 5, 'If we feel scared or unsafe because of someone we don''t know, it''s important to find a trusted adult and tell them what happened. We can also call the police by dialing 911. Police officers are here to protect us and make sure everyone is safe.', 'sentir', '💓'),
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 6, 'Remember, it''s always okay to ask for help when we need it. These people are here to support us and keep us safe.', 'ayuda', '🆘'),
  ('36ed414a-a06e-9bb3-3700-2587fa466195', 7, 'Knowing who to call for help during emergency situations is important. If there is a fire, we call firefighters. If someone is hurt or sick, we call an ambulance. And if we feel scared or unsafe, we can call the police. These people are our heroes and they will always be there for us when we need them.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a65154a7-e3d3-12f1-4f99-8561c5f92461', 1, 'Respecting our elders is an important part of growing up. Elders are people who are older than us, like parents, grandparents, and teachers.', 'importante', '❗'),
  ('a65154a7-e3d3-12f1-4f99-8561c5f92461', 2, 'We show respect to our elders by listening when they talk. When someone is talking, we look at them and pay attention. We don''t interrupt or talk over them. This shows that we value what they have to say.', 'atencion', '📢'),
  ('a65154a7-e3d3-12f1-4f99-8561c5f92461', 3, 'We also show respect by using polite words like "please" and "thank you." When someone does something nice for us, we say thank you. When we want something, we say please. Using these words shows that we appreciate the help and kindness of others.', 'gracias', '🙏'),
  ('a65154a7-e3d3-12f1-4f99-8561c5f92461', 4, 'Another way to show respect is by following their instructions. When our elders ask us to do something, we try our best to do it. They know what is best for us and want to keep us safe and happy.', 'instrucciones', '📋'),
  ('a65154a7-e3d3-12f1-4f99-8561c5f92461', 5, 'Respecting our elders is a way to show gratitude and appreciation for all they do for us. When we listen, use polite words, and follow their instructions, we make them feel valued and respected. Let''s always remember to treat our elders with kindness and respect.', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('ef4f44b5-923a-99af-0352-542513844c33', 1, 'Growing up is a big change for me. I am learning and growing every day, just like the caterpillar that transforms into a butterfly.', 'cambio', '🔄'),
  ('ef4f44b5-923a-99af-0352-542513844c33', 2, 'As I grow, my body changes. My clothes may become too small, and I need new ones. This is like when a caterpillar sheds its skin because it has grown too big.', 'cuerpo', '🧍'),
  ('ef4f44b5-923a-99af-0352-542513844c33', 3, 'My thoughts and feelings also change as I grow. Just like how a caterpillar becomes a pupa and then a butterfly, I am changing and becoming more independent. It''s okay to feel different emotions as I grow, and it''s important to talk about them with someone I trust.', 'sentimientos', '💗'),
  ('ef4f44b5-923a-99af-0352-542513844c33', 4, 'I am learning new things and gaining new skills, just like a butterfly learns to fly. It''s exciting to see all the ways I am growing and changing.', 'aprender', '📖'),
  ('ef4f44b5-923a-99af-0352-542513844c33', 5, 'Growing up means going through many changes, just like a caterpillar transforming into a beautiful butterfly. These changes are part of life, and they help me become stronger and more capable each day.', 'muchos', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('ec526707-7510-f809-5a69-12933d234002', 1, 'Feeling angry is something that can happen to anyone. Sometimes, things don’t go the way we want them to, and that can make us feel upset or frustrated.', 'sentimiento', '💗'),
  ('ec526707-7510-f809-5a69-12933d234002', 2, 'When I feel angry, it’s important to remember that it’s okay to have this feeling. It’s a normal emotion. But what matters most is how I choose to respond when I’m angry. Taking deep breaths, counting to ten, or talking to someone I trust are all good ways to help calm down.', 'respirar', '🫁'),
  ('ec526707-7510-f809-5a69-12933d234002', 3, 'It’s also helpful to think about why I’m feeling angry. Understanding the reason behind my anger can sometimes make it easier to deal with. Maybe I didn’t get my way, or something unexpected happened. By recognizing these triggers, I can learn to manage my emotions better.', 'pensar', '🤔'),
  ('ec526707-7510-f809-5a69-12933d234002', 4, 'Feeling angry is a natural part of life, but how I handle my anger is what truly matters. I will try to take deep breaths and talk to someone I trust when I feel angry. Understanding my feelings can help me navigate through challenging situations more effectively.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f7838f39-861f-25cf-ca5f-5620e4a8ab7f', 1, 'When friends move away, it can be sad and confusing.', 'amigos', '🤝'),
  ('f7838f39-861f-25cf-ca5f-5620e4a8ab7f', 2, 'Sometimes, friends may move to a new house or a different city. They might go to a new school or make new friends. It''s okay to feel sad when this happens. Change can be hard, but it''s a part of life.', 'a veces', '⏳'),
  ('f7838f39-861f-25cf-ca5f-5620e4a8ab7f', 3, 'Even though my friend is moving away, we can still keep in touch. We can talk on the phone, send messages, or even plan visits. Making new friends doesn''t mean forgetting old ones. It means having more people to care about.', 'amigo', '🤝'),
  ('f7838f39-861f-25cf-ca5f-5620e4a8ab7f', 4, 'When friends move away, it''s an opportunity to show kindness and understanding. I can remember the good times we shared and look forward to making new memories with other friends.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('873e9ea6-21ec-267b-65e9-014237ed0d63', 1, 'I like making new friends. Sometimes, I use my words to talk to people and make friends.', 'gustar', '👍'),
  ('873e9ea6-21ec-267b-65e9-014237ed0d63', 2, 'When I see someone playing with a toy that I want to play with, I can say, "Can I play too?" If they say yes, then we can play together. If they say no, I can find another toy to play with or ask if we can take turns.', 'esperar', '⏳'),
  ('873e9ea6-21ec-267b-65e9-014237ed0d63', 3, 'If I feel happy, I can tell my friend, "I''m happy today!" They might be happy too and we can share our happiness.', 'sentir', '💓'),
  ('873e9ea6-21ec-267b-65e9-014237ed0d63', 4, 'Sometimes, I might feel upset. If I do, I can tell my friend, "I''m feeling upset." My friend might help me feel better by talking to me or giving me a hug.', 'a veces', '⏳'),
  ('873e9ea6-21ec-267b-65e9-014237ed0d63', 5, 'Using my words helps me make friends and understand how others are feeling. When I use my words, I can have fun and enjoy spending time with my friends.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('689631fe-abc1-3743-bc8a-b3f3e150a81b', 1, 'Managing noise and crowds can be challenging, but I can learn strategies to help me feel more comfortable.', 'ruido', '🔊'),
  ('689631fe-abc1-3743-bc8a-b3f3e150a81b', 2, 'Sometimes, when I am in a crowded place with lots of noise, it may make me feel overwhelmed or anxious. It''s important for me to remember that it''s okay to feel this way, and there are things I can do to help myself feel better.', 'a veces', '⏳'),
  ('689631fe-abc1-3743-bc8a-b3f3e150a81b', 3, 'One strategy is to find a quiet spot where I can take a break if the noise becomes too much. This could be a corner of the room, a quieter area outside, or even using noise-canceling headphones.', 'silencio', '🔇'),
  ('689631fe-abc1-3743-bc8a-b3f3e150a81b', 4, 'Another helpful technique is deep breathing. Taking slow, deep breaths can calm my mind and body, making it easier to cope with the noise and crowds around me.', 'respirar', '🫁'),
  ('689631fe-abc1-3743-bc8a-b3f3e150a81b', 5, 'I can also use visualization techniques, like imagining myself in a peaceful place or focusing on a favorite calming activity, to help distract myself from the overwhelming sensory input.', 'gustar', '👍'),
  ('689631fe-abc1-3743-bc8a-b3f3e150a81b', 6, 'By practicing these strategies, I can learn to manage noise and crowds more effectively. Remembering to take breaks, breathe deeply, and use visualization can help me feel calmer and more in control in busy environments. Managing noise and crowds is a skill I can develop over time.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0e64bdc9-99ea-3e6e-89d2-31672f5c2a2c', 1, 'When mom and dad go on a date', 'ir', '🚶'),
  ('0e64bdc9-99ea-3e6e-89d2-31672f5c2a2c', 2, 'Sometimes, mom and dad like to spend time together, just the two of them. They call it a "date." A date is when they go out somewhere special, like a restaurant or a movie.', 'a veces', '⏳'),
  ('0e64bdc9-99ea-3e6e-89d2-31672f5c2a2c', 3, 'When mom and dad go on a date, they ask someone to come over and stay with me. This person could be a family member, a friend, or a babysitter. They make sure I am safe and taken care of while they are away.', 'ir', '🚶'),
  ('0e64bdc9-99ea-3e6e-89d2-31672f5c2a2c', 4, 'I might feel a little sad or worried when mom and dad leave for their date. It''s okay to have these feelings. Mom and dad always come back home after their date. They love me very much and want to spend time together to keep their relationship strong.', 'sentir', '💓'),
  ('0e64bdc9-99ea-3e6e-89d2-31672f5c2a2c', 5, 'When mom and dad go on a date, it''s because they care about each other and our family. I can have fun with the person who stays with me and look forward to hearing about mom and dad''s special time together when they return.', 'ir', '🚶');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d4e82b69-e095-73b7-b39e-3604b12d0b59', 1, 'My name is Emily. I am learning about bedtime routines.', 'aprender', '📖'),
  ('d4e82b69-e095-73b7-b39e-3604b12d0b59', 2, 'Every evening, it''s time for bed. First, I brush my teeth to keep them clean and healthy. Next, I change into my cozy pajamas to feel comfortable. Then, I pick out a book to read with Mom or Dad before going to sleep. Finally, I snuggle under the covers and close my eyes to rest.', 'cepillarse', '🪥'),
  ('d4e82b69-e095-73b7-b39e-3604b12d0b59', 3, 'Bedtime is important because it helps me relax and get ready for a new day. When I follow my routine, I feel calm and sleepy, making it easier to fall asleep.', 'vestirse', '👕'),
  ('d4e82b69-e095-73b7-b39e-3604b12d0b59', 4, 'At night, it''s time for bed. By following my bedtime routine, I can unwind and prepare for a good night''s sleep.', 'noche', '🌙');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('66784cc9-231d-6764-0ad9-a7f97a3f826c', 1, 'Feeling different emotions at the same time can be confusing. Sometimes, we may feel happy and sad all at once. It''s okay to have mixed feelings. Let''s understand how it''s possible to experience multiple emotions simultaneously.', 'sentimiento', '💗'),
  ('66784cc9-231d-6764-0ad9-a7f97a3f826c', 2, 'Imagine a day when I wake up excited about going to school but also feeling a bit nervous because of a test. I might feel happy to see my friends but worried about finishing my homework. These mixed emotions are like having two colors swirled together.', 'dia', '☀️'),
  ('66784cc9-231d-6764-0ad9-a7f97a3f826c', 3, 'It''s normal to feel more than one emotion at a time. Emotions are like colors on a palette, blending and mixing in our hearts. Just like a rainbow has many colors, our feelings can overlap and create new shades too.', 'sentir', '💓'),
  ('66784cc9-231d-6764-0ad9-a7f97a3f826c', 4, 'When we feel different emotions at the same time, it''s important to acknowledge each feeling. We can say, "I am happy about seeing my friends, but I am also worried about the test." Recognizing and accepting these mixed emotions helps us navigate through them.', 'sentir', '💓'),
  ('66784cc9-231d-6764-0ad9-a7f97a3f826c', 5, 'Feeling different emotions at the same time is part of being human. It''s like painting with a brush that carries both joy and concern. By understanding and accepting our mixed feelings, we learn more about ourselves and how colorful our emotional world can be. Remember, it''s okay to feel a range of emotions—it makes us beautifully unique.', 'sentimiento', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('451df41a-55ac-d32d-9661-176c7dd0a648', 1, 'The importance of changing socks and underwear', 'feliz', '😊'),
  ('451df41a-55ac-d32d-9661-176c7dd0a648', 2, 'Changing socks and underwear is an important part of staying clean and healthy. Socks and underwear help protect our feet and private areas, so it’s essential to keep them fresh.', 'importante', '❗'),
  ('451df41a-55ac-d32d-9661-176c7dd0a648', 3, 'Wearing the same socks and underwear for too long can make us feel uncomfortable and may cause skin irritation or bad smells. That’s why changing into clean ones regularly is a good habit.', 'igual', '➡️'),
  ('451df41a-55ac-d32d-9661-176c7dd0a648', 4, 'After wearing socks and underwear for a day, they collect sweat and dirt. Changing into fresh pairs helps us feel refreshed and ready for the day ahead. It’s like giving ourselves a little gift of cleanliness.', 'dia', '☀️'),
  ('451df41a-55ac-d32d-9661-176c7dd0a648', 5, 'Remembering to change socks and underwear every day or after taking a bath or shower is a great way to take care of ourselves. It shows that we respect our bodies and want to stay healthy and comfortable.', 'cambio', '🔄'),
  ('451df41a-55ac-d32d-9661-176c7dd0a648', 6, 'The importance of changing socks and underwear cannot be overstated. By keeping them clean and fresh, we are taking care of our bodies and showing self-respect. Let''s remember to change them daily to stay clean and healthy!', 'limpiar', '🧹');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3af28237-3ac0-e91a-4012-b1aad022ed6b', 1, 'Sometimes, friends move away. This can be hard and sad. It’s okay to feel upset when a friend moves away.', 'a veces', '⏳'),
  ('3af28237-3ac0-e91a-4012-b1aad022ed6b', 2, 'When a friend moves away, it means they are going to live in a new place. Even though they won’t be close by anymore, we can still keep in touch with them. We can call them on the phone, send them messages, or even plan visits if possible.', 'amigo', '🤝'),
  ('3af28237-3ac0-e91a-4012-b1aad022ed6b', 3, 'It’s normal to miss our friend when they leave. We might feel lonely or sad for a while, and that’s okay. Talking about how we feel with someone we trust can help us feel better.', 'amigo', '🤝'),
  ('3af28237-3ac0-e91a-4012-b1aad022ed6b', 4, 'Making new friends can also help fill the gap left by our friend moving away. New friends can bring new adventures and fun times into our lives. It’s exciting to meet new people and learn about them.', 'nuevo', '🆕'),
  ('3af28237-3ac0-e91a-4012-b1aad022ed6b', 5, 'Change is a part of life, and even though it can be tough at first, we can adapt and grow from these experiences. Remembering the good times we shared with our friend can bring comfort and warmth during this time of change.', 'cambio', '🔄'),
  ('3af28237-3ac0-e91a-4012-b1aad022ed6b', 6, 'When friends move away, it''s natural to feel sad and miss them. But we can stay connected through calls, messages, and visits. Making new friends can also bring joy and new experiences into our lives. Change may be hard, but we can adjust and find happiness in new connections.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d61bd0be-90f8-5eb6-31af-0b4464113b61', 1, 'Hi, my name is Alex. I go to school every day and there are many other children in my class. We all share the same spaces, like the classroom and the playground.', 'saludar', '👋'),
  ('d61bd0be-90f8-5eb6-31af-0b4464113b61', 2, 'When we share spaces, it''s important to be kind and respectful to each other. This means using our words instead of pushing or hitting. If someone is already playing with a toy or sitting at a table, I will wait for my turn patiently. Sharing spaces also means keeping them clean and tidy. I will put my toys away when I am done playing and throw trash in the bin.', 'esperar', '⏳'),
  ('d61bd0be-90f8-5eb6-31af-0b4464113b61', 3, 'Sometimes, sharing spaces can be challenging because everyone has different preferences. Some people may like things quiet while others enjoy being active. It''s important to understand that we all have different needs and find ways to compromise. If I need some quiet time, I can ask my teacher if there is a quiet corner where I can go.', 'a veces', '⏳'),
  ('d61bd0be-90f8-5eb6-31af-0b4464113b61', 4, 'When we share spaces and respect each other''s needs, we create a positive and welcoming environment. I will try my best to be considerate and understanding towards my classmates. By sharing spaces and sharing smiles, we can all have a great time together at school.', 'compartir', '🤲');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5e6faef6-bd78-2c9c-393b-bae0ac9404c8', 1, 'Feeling anxious is when my body and mind feel worried or nervous. It''s okay to feel this way sometimes, but it''s important to learn how to manage these feelings.', 'sentimiento', '💗'),
  ('5e6faef6-bd78-2c9c-393b-bae0ac9404c8', 2, 'When I recognize that I am feeling anxious, I can take deep breaths and think about something positive. I can also talk to a trusted adult about how I''m feeling. Sometimes doing an activity I enjoy, like drawing or listening to music, can help me feel better. It''s important to remember that it''s okay to ask for help when I need it.', 'respirar', '🫁'),
  ('5e6faef6-bd78-2c9c-393b-bae0ac9404c8', 3, 'Recognizing and managing anxiety helps me feel more calm and in control. I can practice these strategies to help myself feel better when I start to feel anxious.', 'sentir', '💓');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('45217e40-7a7f-c91b-5eb3-7ff251f8a7f7', 1, 'Feeling different emotions is a natural part of life. It''s okay to feel happy, sad, excited, or even worried at times.', 'sentimiento', '💗'),
  ('45217e40-7a7f-c91b-5eb3-7ff251f8a7f7', 2, 'Sometimes I feel really happy when I play with my favorite toys or spend time with my family. Other times, I might feel a little bit sad if something doesn''t go the way I wanted it to. It''s important to remember that everyone feels different emotions and that''s okay.', 'a veces', '⏳'),
  ('45217e40-7a7f-c91b-5eb3-7ff251f8a7f7', 3, 'When I''m feeling upset, I can take deep breaths or talk to someone I trust about how I''m feeling. This can help me feel better and understand my emotions.', 'respirar', '🫁'),
  ('45217e40-7a7f-c91b-5eb3-7ff251f8a7f7', 4, 'It''s also okay to show empathy towards others who are feeling different emotions. If someone else is feeling sad, I can try to comfort them by being kind and understanding.', 'sentimiento', '💗'),
  ('45217e40-7a7f-c91b-5eb3-7ff251f8a7f7', 5, 'Feeling different emotions is a normal part of life. It''s okay to have ups and downs, and it''s important to express our feelings in a safe and respectful way.', 'sentimiento', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('71a39edd-a8af-bc0a-2768-c22437ea619a', 1, 'Every day, I have a schedule. A schedule is a plan that tells me what to do and when to do it.', 'dia', '☀️'),
  ('71a39edd-a8af-bc0a-2768-c22437ea619a', 2, 'In the morning, I wake up and get ready for school. Then, I eat breakfast before leaving for school. At school, I learn new things and play with my friends. After school, I come home and have a snack. Sometimes, I go to therapy or other activities. In the evening, I have dinner with my family and then take a bath before bedtime. My schedule helps me know what comes next and makes me feel prepared for each part of the day.', 'vestirse', '👕'),
  ('71a39edd-a8af-bc0a-2768-c22437ea619a', 3, 'Every day, I have a schedule. My schedule helps me know what to expect and feel ready for each part of the day.', 'dia', '☀️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('92ce2d92-edfb-52ff-9711-061adcbc9b93', 1, 'Adapting to changes in weather and seasons is important for everyone. Seasons change throughout the year, bringing different types of weather. It''s essential to understand how to adjust our routines and activities accordingly.', 'importante', '❗'),
  ('92ce2d92-edfb-52ff-9711-061adcbc9b93', 2, 'When the weather changes from warm to cold, we need to wear different clothes to stay comfortable. In the winter, it gets colder, so we wear jackets, hats, and gloves to keep warm. When it''s hot in the summer, we wear lighter clothes like shorts and t-shirts to stay cool.', 'necesitar', '❗'),
  ('92ce2d92-edfb-52ff-9711-061adcbc9b93', 3, 'During spring and fall, the weather can be unpredictable. Sometimes it''s sunny, other times it rains. We may need an umbrella or a light jacket to prepare for these changes. It''s important to check the weather forecast to know what to expect each day.', 'a veces', '⏳'),
  ('92ce2d92-edfb-52ff-9711-061adcbc9b93', 4, 'As the seasons change, nature also transforms. Trees lose their leaves in the fall, and flowers bloom in the spring. These changes are part of the natural cycle of life on Earth. Observing these changes can be exciting and beautiful.', 'cambio', '🔄'),
  ('92ce2d92-edfb-52ff-9711-061adcbc9b93', 5, 'Adapting to changes in weather and seasons helps us stay comfortable and enjoy different experiences throughout the year. By understanding how weather affects our daily lives, we can be prepared and make the most of each season. Remember, adapting to changes in weather and seasons is a normal part of life.', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1654b78a-872d-3925-d321-5e32992dbb33', 1, 'My after-school time is filled with fun activities. I have a schedule for my after-school activities.', 'escuela', '🏫'),
  ('1654b78a-872d-3925-d321-5e32992dbb33', 2, 'When I finish school, I go to an after-school program. In the program, I get to play games, do art projects, and talk with friends. Sometimes, we also have snacks and free time to choose what we want to do.', 'terminar', '✅'),
  ('1654b78a-872d-3925-d321-5e32992dbb33', 3, 'At home, I have other activities too. I may have homework to complete or chores to help with. After that, I can play with my toys, read books, or watch TV. My parents help me follow my schedule and remind me about important things I need to do.', 'casa', '🏠'),
  ('1654b78a-872d-3925-d321-5e32992dbb33', 4, 'Having a schedule helps me know what comes next in my day. It makes it easier for me to understand and enjoy my after-school activities. I will try to follow my schedule every day and ask for help if I need it.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b59daffc-0a8a-6d12-4424-403a7d68f0ac', 1, 'Everyone has their own likes and dislikes. It''s important to respect what other people like, even if it''s different from what I like.', 'todos', '🌐'),
  ('b59daffc-0a8a-6d12-4424-403a7d68f0ac', 2, 'Some people like different foods than I do. That''s okay! They might enjoy spicy food or vegetables that I don''t like. Some people like to wear clothes that are different from mine. They might like bright colors or patterns that I wouldn''t choose for myself. It''s great that we can all have our own unique style.', 'algunos', '✨'),
  ('b59daffc-0a8a-6d12-4424-403a7d68f0ac', 3, 'Sometimes, people have different ways of doing things. For example, some people like to play games that I''m not interested in, and that''s perfectly fine. Other people may prefer quiet activities while I like to be active. We''re all different, and that''s what makes the world interesting.', 'a veces', '⏳'),
  ('b59daffc-0a8a-6d12-4424-403a7d68f0ac', 4, 'It''s important to remember that everyone''s choices and preferences are valuable, even if they''re not the same as mine. When I respect other people''s choices, they feel happy and comfortable around me.', 'importante', '❗'),
  ('b59daffc-0a8a-6d12-4424-403a7d68f0ac', 5, 'When I respect others'' choices and preferences, I help create a friendly and inclusive environment where everyone feels accepted and valued.', 'respetar', '🙇');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4d5a6b2e-0a7f-b319-2d39-19cfea0e9f10', 1, 'Thanksgiving is a special holiday when families and friends come together to share a meal and give thanks for the good things in their lives. It''s a time to show gratitude and appreciate what we have.', 'especial', '⭐'),
  ('4d5a6b2e-0a7f-b319-2d39-19cfea0e9f10', 2, 'During Thanksgiving, people often cook a big meal with turkey, stuffing, mashed potatoes, and pumpkin pie. Families gather around the table to eat together and talk about what they are thankful for. Some families also like to watch parades or play games together.', 'personas', '👥'),
  ('4d5a6b2e-0a7f-b319-2d39-19cfea0e9f10', 3, 'It''s nice to be part of Thanksgiving traditions. I can help by saying what I am thankful for and enjoying the delicious food with my family and friends. This is a time to celebrate and appreciate the good things in life.', 'amable', '💝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('7a320430-464f-2b3e-dfa8-38cb3a27de04', 1, 'Eating together with my family is a special time. It''s when we sit down and share a meal.', 'comer', '🍽️'),
  ('7a320430-464f-2b3e-dfa8-38cb3a27de04', 2, 'During family meals, we talk about our day. Mom cooks delicious food, and we all gather around the table. Dad asks me how school was, and I tell him about my favorite part of the day. My sister shares stories from her dance class.', 'familia', '👨‍👩‍👧‍👦'),
  ('7a320430-464f-2b3e-dfa8-38cb3a27de04', 3, 'Sometimes, I don''t like certain foods, but I can politely say, "No, thank you," if I don''t want to eat something. It''s important to try new foods, but it''s okay if I don''t like everything.', 'gracias', '🙏'),
  ('7a320430-464f-2b3e-dfa8-38cb3a27de04', 4, 'Eating together as a family helps us bond and enjoy each other''s company. I will try to join in during family meals, share about my day, and be polite even if there are foods I don''t prefer. This way, we can have a happy and pleasant mealtime together.', 'comer', '🍽️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8a27c640-f941-de4b-6017-69b77f7f889a', 1, 'Agreeing to disagree means that it''s okay for people to have different opinions. We can still be friends even if we don''t always agree on everything.', 'personas', '👥'),
  ('8a27c640-f941-de4b-6017-69b77f7f889a', 2, 'Sometimes, my friends and I might not see things the same way. For example, I might like one game, but my friend likes a different game. That''s okay! We can both enjoy our own games without arguing about which one is better.', 'a veces', '⏳'),
  ('8a27c640-f941-de4b-6017-69b77f7f889a', 3, 'When we disagree, we can talk about why we feel differently. It''s important to listen to each other and try to understand why we have different opinions. Even if we don''t change each other''s minds, we can respect each other''s thoughts and feelings.', 'escuchar', '👂'),
  ('8a27c640-f941-de4b-6017-69b77f7f889a', 4, 'It''s okay to have different ideas. We can still get along and have fun together, even if we don''t always agree.', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2939e0e9-d9a4-f28a-0cbb-62b402a8e727', 1, 'Disappointment is a feeling we all experience sometimes.', 'sentimiento', '💗'),
  ('2939e0e9-d9a4-f28a-0cbb-62b402a8e727', 2, 'Disappointment happens when things don’t go the way we hoped or expected. It can feel like a heavy cloud over our heads, making us sad or frustrated. Maybe I was looking forward to something special, but it got canceled. Or perhaps I worked hard on a project and didn’t get the result I wanted.', 'cosas', '📦'),
  ('2939e0e9-d9a4-f28a-0cbb-62b402a8e727', 3, 'When I feel disappointed, I might want to cry or be alone for a bit. That’s okay. It’s important to recognize and accept our feelings. Talking about why we feel this way with someone we trust can help too. They might have ideas on how to make things better or just listen while we vent.', 'sentir', '💓'),
  ('2939e0e9-d9a4-f28a-0cbb-62b402a8e727', 4, 'Remember, disappointment doesn’t last forever. It’s a temporary feeling that will pass. Finding ways to cope, like taking deep breaths, drawing, or going for a walk, can help us feel better. We can also try again or find new things to look forward to.', 'respirar', '🫁'),
  ('2939e0e9-d9a4-f28a-0cbb-62b402a8e727', 5, 'Handling disappointment is part of life''s ups and downs. By acknowledging our feelings, seeking support, and finding positive ways to move forward, we can navigate through disappointments and embrace brighter moments ahead.', 'sentimientos', '💗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e945065a-177d-bdea-84cb-866281978901', 1, 'Learning to manage time is important. It helps us stay organized and reduces stress. Let''s explore how we can learn from past mistakes to improve our time management skills.', 'aprender', '📖'),
  ('e945065a-177d-bdea-84cb-866281978901', 2, 'Sometimes, I forget to check my schedule for the day. This makes me late or miss important tasks. To avoid this, I can make it a habit to review my schedule every morning.', 'a veces', '⏳'),
  ('e945065a-177d-bdea-84cb-866281978901', 3, 'In the past, I have procrastinated on assignments, causing me to rush and feel overwhelmed. Instead, I can break down tasks into smaller steps and set aside specific times to work on them.', 'sentir', '💓'),
  ('e945065a-177d-bdea-84cb-866281978901', 4, 'When I don''t prioritize tasks, I end up feeling stressed trying to do everything at once. By identifying what needs to be done first and creating a plan, I can manage my time more effectively.', 'sentimiento', '💗'),
  ('e945065a-177d-bdea-84cb-866281978901', 5, 'By reflecting on past time management mistakes, I can learn valuable lessons. Checking my schedule, avoiding procrastination, and prioritizing tasks will help me stay organized and reduce stress. I am capable of improving my time management skills with practice and patience.', 'tiempo', '⏰');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 1, 'The faces of emotion are like a secret code that tells us how someone is feeling. Ever wondered what these expressions mean?', 'gustar', '👍'),
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 2, 'When someone is happy, their face might light up with a big smile. Their eyes may sparkle, and they might laugh or giggle. Happiness feels warm and fuzzy inside.', 'alguien', '✨'),
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 3, 'If someone is sad, their face might look downcast. They may have tears in their eyes, and their voice might sound quiet. Sadness can make them feel heavy and blue.', 'alguien', '✨'),
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 4, 'Anger can show on a person''s face with furrowed brows and a frown. Their voice may be loud, and they might stomp their feet. Anger can feel hot and intense.', 'enfadado', '😤'),
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 5, 'Sometimes people feel scared. Their eyes widen, and their body might tremble. They may want to hide or run away. Fear can make their heart race.', 'a veces', '⏳'),
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 6, 'When someone is surprised, their eyebrows shoot up, and their mouth forms an "O" shape. Surprise can be exciting and unexpected.', 'alguien', '✨'),
  ('910deb46-75ce-8602-044f-7e9f04887d6d', 7, 'The faces of emotion help us understand how others are feeling. By looking at these expressions, we can connect better with those around us.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('71222138-ed40-bb98-97d6-bb10943e7aa6', 1, 'Drinking water is important for our bodies. It helps us stay healthy and strong. Water is like a special drink that keeps us feeling good inside.', 'agua', '💧'),
  ('71222138-ed40-bb98-97d6-bb10943e7aa6', 2, 'Our bodies need water to work properly. When we play, run, or even when we sleep, our bodies use up water. Drinking water helps us feel refreshed and ready for whatever comes next.', 'necesitar', '❗'),
  ('71222138-ed40-bb98-97d6-bb10943e7aa6', 3, 'Sometimes, we may forget to drink water because we are busy playing or doing other things. But it''s essential to remember to take breaks and have some water. Keeping a water bottle with us can be a great reminder to drink enough water throughout the day.', 'a veces', '⏳'),
  ('71222138-ed40-bb98-97d6-bb10943e7aa6', 4, 'Water is also good for our brains. It helps us think clearly and focus better. When we drink water, we are helping our bodies in many ways without even realizing it.', 'agua', '💧'),
  ('71222138-ed40-bb98-97d6-bb10943e7aa6', 5, 'Remembering to drink water is an important habit. Just like eating healthy foods, drinking water is a way to take care of ourselves. Let''s make sure to keep a water bottle handy and take sips regularly. Drinking water will help us feel good and ready for all the fun activities ahead!', 'beber', '🥤');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('49987a0b-2328-7056-65c1-1d5bb949774a', 1, 'Every person has a favorite sport or activity that they enjoy doing. I am learning about finding my favorite sport or activity.', 'persona', '🧑'),
  ('49987a0b-2328-7056-65c1-1d5bb949774a', 2, 'There are many different sports and activities to try, like soccer, swimming, dancing, or even yoga. When trying new things, it''s okay if I don''t love it right away. It may take time to find what makes me happy and comfortable.', 'muchos', '✨'),
  ('49987a0b-2328-7056-65c1-1d5bb949774a', 3, 'Playing sports or being active is good for my body and mind. It helps me stay healthy and strong. When I play with others, we can work together as a team and have fun. Even if I make mistakes, it''s all part of the game.', 'jugar', '🎮'),
  ('49987a0b-2328-7056-65c1-1d5bb949774a', 4, 'If I feel unsure about a sport or activity, I can talk to my coach or teacher. They can help me understand the rules and practice until I feel more confident. It''s important to listen to their guidance and be patient with myself.', 'escuchar', '👂'),
  ('49987a0b-2328-7056-65c1-1d5bb949774a', 5, 'I am exploring different sports and activities to find what I enjoy the most. Trying new things helps me stay active and learn new skills. I will keep practicing and having fun, knowing that each experience brings me closer to discovering my favorite sport or activity.', 'diferente', '🌈');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fd176975-a4e3-a261-2d83-68b1c1b45493', 1, 'In this story, we will learn about celebrating our differences and appreciating diversity in friendships. Friends come in all shapes, sizes, and colors. It''s what makes each friendship unique and special.', 'aprender', '📖'),
  ('fd176975-a4e3-a261-2d83-68b1c1b45493', 2, 'Every person is different. Some people have brown hair, while others have blonde or black hair. Some people wear glasses, while others don''t. Some people like to play soccer, while others prefer painting or reading books. These differences make us who we are, and they should be celebrated.', 'persona', '🧑'),
  ('fd176975-a4e3-a261-2d83-68b1c1b45493', 3, 'When we make friends, it''s important to remember that everyone has their own interests, talents, and abilities. We may not always understand or enjoy the same things, but that''s okay. Our differences can actually make our friendships stronger and more interesting.', 'amigos', '🤝'),
  ('fd176975-a4e3-a261-2d83-68b1c1b45493', 4, 'Imagine if all of our friends were exactly the same as us. It would be boring! We wouldn''t learn new things or discover new hobbies. By embracing diversity, we open ourselves up to a world of possibilities and enriching experiences.', 'todo', '🌐'),
  ('fd176975-a4e3-a261-2d83-68b1c1b45493', 5, 'Sometimes, we might feel unsure or uncomfortable around someone who is different from us. That''s normal. But instead of judging or excluding them, let''s try to understand and appreciate their uniqueness. We can ask questions, listen to their stories, and find common ground. This way, we can build meaningful connections and create a supportive community.', 'escuchar', '👂'),
  ('fd176975-a4e3-a261-2d83-68b1c1b45493', 6, 'Remember, celebrating our differences and appreciating diversity in friendships is what makes our world colorful and exciting. Let''s embrace the uniqueness of each individual and foster inclusive friendships where everyone feels valued and accepted. Together, we can create a beautiful tapestry of friendship that celebrates diversity.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f855be86-cfb0-ec8d-30c9-cd7e1dfea57f', 1, 'Every day, we see many different faces. Faces can tell us a lot about how someone is feeling. It''s like a secret code that we can learn to understand.', 'dia', '☀️'),
  ('f855be86-cfb0-ec8d-30c9-cd7e1dfea57f', 2, 'When someone is happy, their face might look bright and smiley. Their eyes might sparkle with joy. When someone is sad, their face might look downcast and their eyes might be filled with tears. Sometimes, people feel angry and their face might turn red or scrunch up. And when someone is surprised, their eyebrows might shoot up and their mouth might open wide.', 'alguien', '✨'),
  ('f855be86-cfb0-ec8d-30c9-cd7e1dfea57f', 3, 'It''s important for us to learn how to read these faces and understand the feelings behind them. This way, we can know how someone is feeling and respond in a kind and helpful way.', 'importante', '❗'),
  ('f855be86-cfb0-ec8d-30c9-cd7e1dfea57f', 4, 'Sometimes, it''s not just the face that tells us how someone is feeling. We can also look at their body language. If someone is standing tall and confident, they might be feeling proud. But if someone is hunched over and looking down, they might be feeling shy or nervous.', 'a veces', '⏳'),
  ('f855be86-cfb0-ec8d-30c9-cd7e1dfea57f', 5, 'We can also listen to the tone of someone''s voice. If they sound excited, they might be feeling happy. But if they sound upset or frustrated, they might be feeling angry or sad.', 'escuchar', '👂'),
  ('f855be86-cfb0-ec8d-30c9-cd7e1dfea57f', 6, 'Learning to read emotions is like learning a new language. The more we practice, the better we become at understanding how others are feeling. So let''s pay attention to faces, body language, and voices, so we can be there for our friends and family when they need us.', 'atencion', '📢');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c76bc519-dc85-8908-5ede-bf1794342d71', 1, 'Many people have been to the doctor''s office or hospital at some point. There are many people who work there, and one of them is a nurse. Nurses help take care of patients and make sure they feel better. Let''s learn more about what nurses do!', 'muchos', '✨'),
  ('c76bc519-dc85-8908-5ede-bf1794342d71', 2, 'Nurses wear special uniforms and have a stethoscope around their necks. They work in hospitals, clinics, and sometimes even visit people at home. When someone is sick or hurt, nurses check their temperature, blood pressure, and listen to their heartbeat with a stethoscope. They also give medicine to patients and help them feel comfortable.', 'escuchar', '👂'),
  ('c76bc519-dc85-8908-5ede-bf1794342d71', 3, 'Nurses are very kind and patient. They talk to patients and listen to their concerns. Sometimes, they hold their hands when they''re scared or in pain. Nurses also help doctors during surgeries and make sure everything is ready for the operation.', 'escuchar', '👂'),
  ('c76bc519-dc85-8908-5ede-bf1794342d71', 4, 'Being a nurse is an important job because they help people feel better. I think it would be amazing to be a nurse one day and make a difference in people''s lives.', 'importante', '❗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('f4fe5e42-6f29-1d73-e295-1e8c10f09975', 1, 'Hi, my name is Emily. I love playing with my friends and having fun! Sometimes, I want to invite a friend over to my house for a playdate. It''s exciting to spend time together and share our favorite toys and games.', 'saludar', '👋'),
  ('f4fe5e42-6f29-1d73-e295-1e8c10f09975', 2, 'When I want to invite someone over for a playdate, there are a few things I can do. First, I can think about who I want to invite. Maybe it''s a classmate or a neighbor who I enjoy spending time with. Then, I can ask my mom or dad if it''s okay to have a friend come over. They will help me plan the playdate and make sure everything is ready.', 'querer', '💕'),
  ('f4fe5e42-6f29-1d73-e295-1e8c10f09975', 3, 'Next, I can talk to my friend and ask them if they would like to come over. I can say something like, "Hey, would you like to come to my house and play? We can have so much fun together!" It''s important to give my friend enough time to decide and let me know if they can come.', 'hablar', '🗣️'),
  ('f4fe5e42-6f29-1d73-e295-1e8c10f09975', 4, 'Once my friend says yes, we can talk about when and what time they will come over. My mom or dad will help me pick a day that works for both of us. We can also discuss what activities we want to do during the playdate. It''s great to have some ideas in mind, like playing board games, building with Legos, or even having a picnic in the backyard.', 'amigo', '🤝'),
  ('f4fe5e42-6f29-1d73-e295-1e8c10f09975', 5, 'On the day of the playdate, I can help get everything ready. I can clean up my room and make sure my toys are organized. I can also help set up any snacks or drinks we might have. When my friend arrives, I can greet them with a smile and show them around my house. It''s important to be a good host and make them feel welcome.', 'dia', '☀️'),
  ('f4fe5e42-6f29-1d73-e295-1e8c10f09975', 6, 'Inviting someone over for a playdate is a wonderful way to have fun and build friendships. By following these steps and being a kind and welcoming host, I can create special memories with my friends. I''m excited to plan my next playdate and make it a fantastic experience for everyone involved.', 'alguien', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('894e726d-3252-6e4f-46c7-adb429a544d7', 1, 'There is a tree outside my window. It''s been there for many years.', 'arbol', '🌳'),
  ('894e726d-3252-6e4f-46c7-adb429a544d7', 2, 'The tree started as a small seed in the ground. Over time, it grew taller and stronger. Birds built nests in its branches, and squirrels play around it.', 'arbol', '🌳'),
  ('894e726d-3252-6e4f-46c7-adb429a544d7', 3, 'Seasons change, and so does the tree. In spring, it blossoms with beautiful flowers. In summer, it provides shade from the sun. Fall brings colorful leaves that eventually fall to the ground. Winter sees the tree bare but still standing strong.', 'cambio', '🔄'),
  ('894e726d-3252-6e4f-46c7-adb429a544d7', 4, 'Change is like the tree growing and changing with each season. Just like the tree, I can grow and adapt to new things that happen around me.', 'cambio', '🔄'),
  ('894e726d-3252-6e4f-46c7-adb429a544d7', 5, 'The tree outside my window shows me that change is natural and part of life. Like the tree, I can learn to embrace change and grow stronger because of it.', 'arbol', '🌳');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('1ef35d34-54c1-cfc1-4865-45678cb8adde', 1, 'Animals can be wonderful companions, but it''s important to remember to use caution around them.', 'importante', '❗'),
  ('1ef35d34-54c1-cfc1-4865-45678cb8adde', 2, 'Some animals are friendly and enjoy being petted or played with. Other animals may feel scared or threatened by sudden movements or loud noises. It''s crucial to approach animals gently and calmly to show them respect.', 'algunos', '✨'),
  ('1ef35d34-54c1-cfc1-4865-45678cb8adde', 3, 'When meeting a new animal, always ask the owner for permission before trying to touch or interact with it. This shows good manners and helps keep both me and the animal safe.', 'nuevo', '🆕'),
  ('1ef35d34-54c1-cfc1-4865-45678cb8adde', 4, 'If an animal seems frightened or aggressive, it''s best to give them space and not try to touch them. Animals communicate through their body language, so pay attention to signs like growling, hissing, or backing away.', 'atencion', '📢'),
  ('1ef35d34-54c1-cfc1-4865-45678cb8adde', 5, 'Remember, even pets that I really know well can have moments when they don''t want to be touched or bothered. Always listen to what the animal is telling me and respect their boundaries.', 'escuchar', '👂'),
  ('1ef35d34-54c1-cfc1-4865-45678cb8adde', 6, 'Using caution around animals means treating them kindly and respectfully. By approaching animals gently, asking for permission, and understanding their cues, we can create positive interactions and stay safe.', 'seguro', '🛡️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d07d369a-782f-4841-b966-b7abcd2205bc', 1, 'Water can be fun to play in, but it''s important to remember some safety rules when we are near water.', 'agua', '💧'),
  ('d07d369a-782f-4841-b966-b7abcd2205bc', 2, 'We should always have an adult with us when we are around water. This is because water can be dangerous, and adults can help keep us safe.', 'deber', '📋'),
  ('d07d369a-782f-4841-b966-b7abcd2205bc', 3, 'When we go swimming, we need to wear a life jacket if we don''t know how to swim well. Life jackets help us float and stay safe in the water.', 'ir', '🚶'),
  ('d07d369a-782f-4841-b966-b7abcd2205bc', 4, 'If we see someone struggling in the water, we should not try to help them ourselves. Instead, we should find an adult who can help, like a lifeguard or a parent.', 'ver', '👀'),
  ('d07d369a-782f-4841-b966-b7abcd2205bc', 5, 'Remember, staying safe around water means having fun while being careful and following these important rules!', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('d6ec6961-a00b-78f2-e0d4-bc59848fc87a', 1, 'Faces can tell a story. When I look at someone''s face, I can see how they are feeling.', 'decir', '💬'),
  ('d6ec6961-a00b-78f2-e0d4-bc59848fc87a', 2, 'I know that when someone is smiling, they may be happy or excited. Their eyes might sparkle, and their mouth turns up at the corners. This means they feel good inside.', 'saber', '🧠'),
  ('d6ec6961-a00b-78f2-e0d4-bc59848fc87a', 3, 'When someone is frowning, they might be upset or sad. Their eyebrows come together, and their mouth turns down. This means they don''t feel good inside.', 'alguien', '✨'),
  ('d6ec6961-a00b-78f2-e0d4-bc59848fc87a', 4, 'Sometimes, people show other feelings with their faces. They might look surprised, scared, or angry. It''s important to remember that everyone feels different things at different times.', 'a veces', '⏳'),
  ('d6ec6961-a00b-78f2-e0d4-bc59848fc87a', 5, 'Looking at people''s faces helps me understand how they are feeling. Faces tell a story, and it''s okay to ask someone about their feelings if I''m not sure.', 'personas', '👥');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('19e80a89-df98-ec28-0434-026753da5fae', 1, 'Silence is a part of conversations. Sometimes, people need time to think or feel quiet.', 'a veces', '⏳'),
  ('19e80a89-df98-ec28-0434-026753da5fae', 2, 'When someone is silent during a conversation, it can mean different things. They might be thinking about what was said, feeling unsure, or waiting for their turn to speak. It''s like taking a pause in a song before the next verse.', 'alguien', '✨'),
  ('19e80a89-df98-ec28-0434-026753da5fae', 3, 'If I am talking and someone is silent, I can wait patiently for them to respond. It''s okay to give them space to gather their thoughts.', 'alguien', '✨'),
  ('19e80a89-df98-ec28-0434-026753da5fae', 4, 'Sometimes, I may also feel silent during a conversation. This is normal too. I can take my time to process my feelings or thoughts before sharing them with others.', 'a veces', '⏳'),
  ('19e80a89-df98-ec28-0434-026753da5fae', 5, 'Understanding silence in a conversation is important. It allows us to respect each other''s pace and feelings. Silence can be a way to show we are listening and thinking.', 'importante', '❗');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6231f162-6203-f03c-a030-1f7c0cee4fc5', 1, 'Bullying is when someone says or does mean things to another person on purpose. It’s important to know that everyone deserves to feel safe and respected.', 'acoso', '🚫'),
  ('6231f162-6203-f03c-a030-1f7c0cee4fc5', 2, 'If I see someone being bullied, I can tell a teacher or an adult I trust. If the bullying happens to me, I will tell a teacher or my parents right away. It''s okay to ask for help. I deserve to be treated with kindness and respect.', 'ayuda', '🆘'),
  ('6231f162-6203-f03c-a030-1f7c0cee4fc5', 3, 'I will always remember that it''s important to report bullying so that everyone feels safe and happy at school.', 'siempre', '♾️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('6020634a-0ec8-d0c1-1003-eb6b577cf113', 1, 'Eating healthy foods is important for my body. Healthy foods give me energy and help me grow strong.', 'comer', '🍽️'),
  ('6020634a-0ec8-d0c1-1003-eb6b577cf113', 2, 'When I eat fruits and vegetables, they provide important vitamins and minerals that keep me healthy. They make my body work well so I can play, learn, and have fun.', 'comer', '🍽️'),
  ('6020634a-0ec8-d0c1-1003-eb6b577cf113', 3, 'Drinking water helps to keep me hydrated and feeling good. Water is the best choice to drink throughout the day.', 'agua', '💧'),
  ('6020634a-0ec8-d0c1-1003-eb6b577cf113', 4, 'Avoiding too many sugary snacks is good for my teeth and overall health. Sugary snacks are okay sometimes, but it''s important to enjoy them in moderation.', 'muchos', '✨'),
  ('6020634a-0ec8-d0c1-1003-eb6b577cf113', 5, 'Sometimes, I may not like certain foods, and that''s okay. I can try small bites of new foods to see if I like them. It''s great to explore different tastes!', 'a veces', '⏳'),
  ('6020634a-0ec8-d0c1-1003-eb6b577cf113', 6, 'Eating healthy foods gives me energy and helps me grow strong. When I take care of my body by eating well, drinking water, and enjoying treats in moderation, I feel my best!', 'comer', '🍽️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('92299536-fba4-7b09-6d5d-e9fca1db7c63', 1, 'Building conversations is like building with bricks. Each brick is a word or a sentence that we use to talk to someone.', 'gustar', '👍'),
  ('92299536-fba4-7b09-6d5d-e9fca1db7c63', 2, 'When I want to talk to someone, I can start by saying "Hi" or asking a question like "How are you?" These are the first bricks in our conversation.', 'querer', '💕'),
  ('92299536-fba4-7b09-6d5d-e9fca1db7c63', 3, 'I can add more bricks by sharing something about my day or asking about their favorite things. This helps us keep talking and learning about each other.', 'mas', '➕'),
  ('92299536-fba4-7b09-6d5d-e9fca1db7c63', 4, 'Listening is important too. When someone else is talking, I can show I''m listening by looking at them and nodding my head.', 'importante', '❗'),
  ('92299536-fba4-7b09-6d5d-e9fca1db7c63', 5, 'If I don''t understand something, it''s okay to ask for help. I can say, "Can you please explain that to me?"', 'ayuda', '🆘'),
  ('92299536-fba4-7b09-6d5d-e9fca1db7c63', 6, 'Building conversations brick by brick helps me connect with others. Talking, listening, and asking for help are all important parts of having a good conversation.', 'ayuda', '🆘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5ae75558-4b31-04bc-b146-f5601b721989', 1, 'When I use the internet, I may come across people I don''t know. These are called online strangers.', 'venir', '🚶'),
  ('5ae75558-4b31-04bc-b146-f5601b721989', 2, 'Online strangers can be anyone who I haven''t met in person. They might try to talk to me or ask me questions. It''s important to remember that not everyone on the internet is kind and safe like my family and friends.', 'persona', '🧑'),
  ('5ae75558-4b31-04bc-b146-f5601b721989', 3, 'I should never share personal information with online strangers, such as my full name, address, phone number, school name, or any pictures of myself. If someone asks for this information, I should tell a grown-up right away.', 'deber', '📋'),
  ('5ae75558-4b31-04bc-b146-f5601b721989', 4, 'If an online stranger says something that makes me feel uncomfortable or scared, I should turn off the device and tell a trusted adult about it. It''s okay to say no and stop talking to them.', 'extrano', '🙅'),
  ('5ae75558-4b31-04bc-b146-f5601b721989', 5, 'It''s best to only communicate with people I already know in real life when using the internet. My safety is the most important thing.', 'personas', '👥'),
  ('5ae75558-4b31-04bc-b146-f5601b721989', 6, 'Staying safe online means being careful around online strangers. I will always tell a grown-up if something doesn''t feel right.', 'seguro', '🛡️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4030722e-0657-88e7-4aec-41d1baa3d306', 1, 'When I am excited, but it’s time to be calm.', 'emocionado', '🤩'),
  ('4030722e-0657-88e7-4aec-41d1baa3d306', 2, 'Sometimes, I feel so happy and full of energy that I want to jump around or shout. It''s like a big bubble of excitement inside me! But there are times when being calm is important, like in class or at the doctor''s office. When I need to be calm, I can take deep breaths or count slowly in my head. This helps me relax my body and mind.', 'respirar', '🫁'),
  ('4030722e-0657-88e7-4aec-41d1baa3d306', 3, 'If I''m feeling too excited, I might try squeezing a stress ball or hugging a stuffed animal to help me calm down. These actions can make me feel safe and secure.', 'respirar', '🫁'),
  ('4030722e-0657-88e7-4aec-41d1baa3d306', 4, 'Remember, it''s okay to feel excited, but it''s also important to know how to be calm when needed. Taking deep breaths and finding ways to relax can help me manage my feelings.', 'respirar', '🫁'),
  ('4030722e-0657-88e7-4aec-41d1baa3d306', 5, 'When I am excited, but it’s time to be calm, taking deep breaths and using calming strategies can help me feel better.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b0c21512-f3d7-02dc-ce2c-727de7c9d324', 1, 'Walking in the park is a wonderful experience. Many people enjoy walking in the park to see beautiful trees, flowers, and animals.', 'caminar', '🚶'),
  ('b0c21512-f3d7-02dc-ce2c-727de7c9d324', 2, 'When I walk in the park, I can see tall trees reaching up to the sky. Some trees have colorful leaves that change with the seasons. I may hear birds singing or squirrels chattering as they play in the trees. There are also many different kinds of flowers in the park. Some are big and bright, while others are small and delicate. People take care of the park so that it stays clean and safe for everyone to enjoy.', 'caminar', '🚶'),
  ('b0c21512-f3d7-02dc-ce2c-727de7c9d324', 3, 'Sometimes, I might meet other people who are also walking in the park. It''s nice to smile and say hello if I feel comfortable doing so. If I see someone with a dog, I should always ask their permission before petting the dog. This way, I can show respect for the person and their pet.', 'a veces', '⏳'),
  ('b0c21512-f3d7-02dc-ce2c-727de7c9d324', 4, 'If I need to use the restroom while at the park, I will go with my parent or caregiver. They will help me find the right place and make sure everything goes smoothly.', 'necesitar', '❗'),
  ('b0c21512-f3d7-02dc-ce2c-727de7c9d324', 5, 'I love walking in the park. The beauty of nature makes me happy. I am grateful for the opportunity to explore and appreciate the natural world around me.', 'caminar', '🚶');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('47ca36f0-8fe9-cc57-ba47-c7d20beb8458', 1, 'Learning from other people''s stories is a way to understand how others feel and what they have experienced. It helps us connect with them.', 'aprender', '📖'),
  ('47ca36f0-8fe9-cc57-ba47-c7d20beb8458', 2, 'When we listen to someone else’s story, we can learn about their feelings and experiences. We can understand why they might be happy, sad, or worried. Listening to their stories helps us see things from their point of view.', 'escuchar', '👂'),
  ('47ca36f0-8fe9-cc57-ba47-c7d20beb8458', 3, 'Sometimes, when we share our own stories, it can help others understand us better too. We all have different stories that make us who we are.', 'a veces', '⏳'),
  ('47ca36f0-8fe9-cc57-ba47-c7d20beb8458', 4, 'It''s important to remember that everyone''s story is unique, just like ours. By listening to each other''s stories, we can learn to appreciate and respect the differences between us.', 'importante', '❗'),
  ('47ca36f0-8fe9-cc57-ba47-c7d20beb8458', 5, 'Learning from other people''s stories is a way to understand how others feel and what they have experienced. It helps us connect with them.', 'aprender', '📖');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('205df96f-450e-e10c-b0d1-8e70cc1b2e37', 1, 'Taking breaks and lunchtime etiquette are important parts of working in a job. Breaks help us rest and recharge, while lunchtime is when we eat and socialize with coworkers.', 'importante', '❗'),
  ('205df96f-450e-e10c-b0d1-8e70cc1b2e37', 2, 'During work, it''s essential to take breaks to relax and refocus. When the clock shows break time, I can stand up, stretch my legs, or have a snack. Taking breaks helps me feel refreshed and ready to continue working.', 'trabajar', '💼'),
  ('205df96f-450e-e10c-b0d1-8e70cc1b2e37', 3, 'At lunchtime, I can enjoy my meal and chat with colleagues. It''s polite to wait for everyone to be seated before starting to eat. I can use quiet voices and good manners during lunch. If someone needs help, I can offer assistance politely.', 'esperar', '⏳'),
  ('205df96f-450e-e10c-b0d1-8e70cc1b2e37', 4, 'After eating, I should clean up after myself by throwing away trash and putting dishes in the sink. I can also thank those who prepared the food or served me.', 'comer', '🍽️'),
  ('205df96f-450e-e10c-b0d1-8e70cc1b2e37', 5, 'Remembering to take breaks and showing good manners at lunch makes the workplace a pleasant environment for everyone.', 'bien', '👍'),
  ('205df96f-450e-e10c-b0d1-8e70cc1b2e37', 6, 'Taking breaks and practicing good lunchtime etiquette are ways to make work enjoyable and productive.', 'bien', '👍');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a2169d7b-d241-766c-709c-f500d00592f0', 1, 'Being kind in the digital world is important. My name is Sarah, and I am learning about using technology.', 'amable', '💝'),
  ('a2169d7b-d241-766c-709c-f500d00592f0', 2, 'When we use devices like tablets or computers, we can communicate with others online. It''s essential to be kind and respectful when talking to people on the internet, just like we would in person.', 'gustar', '👍'),
  ('a2169d7b-d241-766c-709c-f500d00592f0', 3, 'If someone sends a message that makes me feel uncomfortable, I will tell an adult I trust. I know it''s okay to say no to things that don''t seem right.', 'alguien', '✨'),
  ('a2169d7b-d241-766c-709c-f500d00592f0', 4, 'Remember, not everything I see online is true. People might pretend to be someone they''re not. It''s crucial to keep personal information private and not share it with strangers.', 'recordar', '📝'),
  ('a2169d7b-d241-766c-709c-f500d00592f0', 5, 'Being kind in the digital world means treating others how I want to be treated. Let''s always remember to be safe, respectful, and honest when using technology.', 'amable', '💝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('b91e967b-8108-6a01-fcee-b2eb283c0dbd', 1, 'I am learning about respecting others'' food choices. Sometimes, people have different preferences for the foods they like to eat.', 'aprender', '📖'),
  ('b91e967b-8108-6a01-fcee-b2eb283c0dbd', 2, 'When we sit down to eat together, I may notice that someone else has chosen not to eat a certain food. This is okay because everyone has their own likes and dislikes when it comes to food.', 'sentarse', '🪑'),
  ('b91e967b-8108-6a01-fcee-b2eb283c0dbd', 3, 'Some people may not eat meat, while others may not eat vegetables. It''s important to understand that everyone has their own reasons for choosing what they eat. Some people have allergies or sensitivities to certain foods, so they need to be careful about what they eat.', 'algunos', '✨'),
  ('b91e967b-8108-6a01-fcee-b2eb283c0dbd', 4, 'If someone chooses not to eat something, it''s respectful to not make them feel bad about their choice. We can politely ask if they would like something else instead, but it''s important to accept their decision without making them uncomfortable.', 'alguien', '✨'),
  ('b91e967b-8108-6a01-fcee-b2eb283c0dbd', 5, 'Just like how I have my favorite foods, other people also have their favorites. By respecting each other''s food choices, we create a positive and inclusive environment during meal times.', 'gustar', '👍'),
  ('b91e967b-8108-6a01-fcee-b2eb283c0dbd', 6, 'Understanding and respecting others'' food choices is an important part of eating together. I will try to remember this and be considerate of others'' preferences when we share meals.', 'comida', '🍽️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3e97f3b4-6562-5cd7-1e3a-c3e30645ac94', 1, 'Sharing Valentine''s Day love is a special tradition.', 'compartir', '🤲'),
  ('3e97f3b4-6562-5cd7-1e3a-c3e30645ac94', 2, 'Valentine''s Day is a day to show love and appreciation for people we care about. Some people give cards, flowers, or chocolates to their loved ones on this day. It''s a time to express kindness and friendship. People may wear red or pink colors to celebrate the day of love.', 'dia', '☀️'),
  ('3e97f3b4-6562-5cd7-1e3a-c3e30645ac94', 3, 'When I share Valentine''s Day love, I can make a card for someone special, like my family or friends. I can write kind words or draw pictures that show how much I care about them. Giving a hug or saying "I love you" are also ways to share love on Valentine''s Day.', 'compartir', '🤲'),
  ('3e97f3b4-6562-5cd7-1e3a-c3e30645ac94', 4, 'This Valentine''s Day, I will share love with those who are important to me. Making a card or giving a hug are ways to show how much I care. Sharing Valentine''s Day love brings happiness to others and makes me feel good too.', 'dia', '☀️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c7b8432a-eacc-3a19-e5e0-d7f3365d8e4a', 1, 'Spending time with my family is important. We have fun together, but it''s also important to remember about personal space and boundaries.', 'espacio personal', '↔️'),
  ('c7b8432a-eacc-3a19-e5e0-d7f3365d8e4a', 2, 'When we are at home or visiting family, we spend time together. Sometimes we play games, watch movies, or talk. It''s nice to be close to each other, but it''s also important to respect personal space. Personal space means giving each other room to feel comfortable.', 'espacio personal', '↔️'),
  ('c7b8432a-eacc-3a19-e5e0-d7f3365d8e4a', 3, 'If I want to hug someone in my family, I can ask first if they would like a hug. If they say yes, then I can give them a gentle hug. If they say no, then I can show my love by smiling or saying kind words instead.', 'querer', '💕'),
  ('c7b8432a-eacc-3a19-e5e0-d7f3365d8e4a', 4, 'Sometimes, when we spend time together, I might need some quiet time alone. It''s okay to let my family know that I need some space. They will understand and give me the time I need.', 'a veces', '⏳'),
  ('c7b8432a-eacc-3a19-e5e0-d7f3365d8e4a', 5, 'My family also respects my personal space. If I tell them I need some space, they will understand and give me the time I need.', 'espacio personal', '↔️'),
  ('c7b8432a-eacc-3a19-e5e0-d7f3365d8e4a', 6, 'Spending time with my family is special. Respecting personal space and boundaries helps us all feel happy and comfortable.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5370fbb4-6247-2fae-a6de-6927f58ab853', 1, 'It''s important to know who we can trust. Trustworthy people are kind, helpful, and make us feel safe.', 'importante', '❗'),
  ('5370fbb4-6247-2fae-a6de-6927f58ab853', 2, 'We can trust our parents, teachers, doctors, and police officers. They help keep us safe and take care of us. If we''re lost or need help, we can ask them for assistance.', 'padres', '👨‍👩‍👧'),
  ('5370fbb4-6247-2fae-a6de-6927f58ab853', 3, 'Strangers are people we don''t know. It''s important to be cautious around strangers. We should never go anywhere with a stranger or accept anything from them without asking a trusted adult first.', 'personas', '👥'),
  ('5370fbb4-6247-2fae-a6de-6927f58ab853', 4, 'If someone makes us feel uncomfortable or scared, we should tell a trusted adult right away. It''s okay to say no if something doesn''t feel right.', 'alguien', '✨'),
  ('5370fbb4-6247-2fae-a6de-6927f58ab853', 5, 'Knowing who to trust helps us stay safe. We can trust certain people like our parents, teachers, doctors, and police officers. It''s important to be careful around strangers and always ask a trusted adult for help when needed.', 'seguro', '🛡️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9ad0c3a6-ef6b-4f98-dd47-d15fcd7bfd43', 1, 'Let''s talk about what happens at work. Work is a place where adults go to do important things during the day.', 'hablar', '🗣️'),
  ('9ad0c3a6-ef6b-4f98-dd47-d15fcd7bfd43', 2, 'Work can be different for each adult. Some adults may work in offices, some outdoors, and others from home. They have tasks to complete and responsibilities to fulfill. At work, adults use their skills and knowledge to help others or create things that are needed.', 'trabajar', '💼'),
  ('9ad0c3a6-ef6b-4f98-dd47-d15fcd7bfd43', 3, 'Sometimes adults need to attend meetings, talk on the phone, or use computers to get their work done. They may also collaborate with other people to achieve common goals. It''s like being part of a team!', 'a veces', '⏳'),
  ('9ad0c3a6-ef6b-4f98-dd47-d15fcd7bfd43', 4, 'Adults often dress professionally for work, wearing clothes that match the type of work they do. They follow schedules and arrive on time to start their workday. During breaks, they may chat with coworkers or have a snack to recharge.', 'vestirse', '👕'),
  ('9ad0c3a6-ef6b-4f98-dd47-d15fcd7bfd43', 5, 'So, work is a place where adults go to contribute to society and earn a living. Just like how I learn and play at school, adults work to make a positive impact. Understanding what happens at work helps me appreciate the efforts of adults around me.', 'trabajar', '💼');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('9778e53c-3bde-b582-63f6-db874c61a7c8', 1, 'When I feel unwell, it’s important to rest and let my body recover. Resting helps me get better.', 'sentir', '💓'),
  ('9778e53c-3bde-b582-63f6-db874c61a7c8', 2, 'If I have a fever or feel very tired, my body is telling me that I need to rest. When I rest, I can lie down on the couch or in bed with a cozy blanket. I can watch my favorite show or listen to calming music. It’s okay to ask for help if I need something while resting.', 'ayuda', '🆘'),
  ('9778e53c-3bde-b582-63f6-db874c61a7c8', 3, 'Drinking water and eating healthy foods will also help my body recover. If I have medicine, I should take it as directed by my parents or doctor. They know what''s best for me when I''m not feeling well.', 'agua', '💧'),
  ('9778e53c-3bde-b582-63f6-db874c61a7c8', 4, 'It’s important to tell my parents how I’m feeling so they can help me. They want to make sure I am comfortable and getting the care I need.', 'importante', '❗'),
  ('9778e53c-3bde-b582-63f6-db874c61a7c8', 5, 'When I rest and take care of myself, I give my body the chance to heal. I will try to rest and follow my parents'' advice when I don''t feel well.', 'dar', '🎁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('8fc82411-42e1-8daf-d9f9-1f47b60b74e0', 1, 'Everyone has a comfort zone, which is the space around them. It''s like an invisible bubble that keeps us feeling safe and comfortable. Understanding personal space helps us to respect each other''s feelings and boundaries.', 'espacio personal', '↔️'),
  ('8fc82411-42e1-8daf-d9f9-1f47b60b74e0', 2, 'When I''m with my family or friends, it''s important to be aware of their comfort zones. If someone steps too close, they might feel uncomfortable. Just like how I don''t like it when someone gets too close to me without asking.', 'familia', '👨‍👩‍👧‍👦'),
  ('8fc82411-42e1-8daf-d9f9-1f47b60b74e0', 3, 'At school, we also have our own spaces. When we line up, we stand a little apart from each other so everyone has their own space. This makes waiting in line more comfortable for everyone.', 'escuela', '🏫'),
  ('8fc82411-42e1-8daf-d9f9-1f47b60b74e0', 4, 'Sometimes, people may not realize they are invading someone else''s comfort zone. If this happens, I can politely say, "Can you please give me some space?" or "I need some space right now." It''s okay to speak up if I feel uncomfortable.', 'a veces', '⏳'),
  ('8fc82411-42e1-8daf-d9f9-1f47b60b74e0', 5, 'Respecting personal space is important for everyone. I will try to be mindful of others'' comfort zones and kindly ask for space when I need it.', 'espacio personal', '↔️');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('bf53021d-91dc-f945-4304-c7a46f471953', 1, 'Responding to criticism is an important skill. It helps me learn and grow.', 'importante', '❗'),
  ('bf53021d-91dc-f945-4304-c7a46f471953', 2, 'Criticism is when someone tells me what I did wrong or how I can improve. It may feel uncomfortable, but it''s a chance for me to get better at something. For example, if my teacher says my handwriting is hard to read, she wants me to practice writing more neatly.', 'alguien', '✨'),
  ('bf53021d-91dc-f945-4304-c7a46f471953', 3, 'When I receive feedback, I can listen carefully without getting upset. I can ask questions to understand better and thank the person for helping me improve. It''s okay to feel a little sad or frustrated, but I can use that feeling to work harder next time.', 'escuchar', '👂'),
  ('bf53021d-91dc-f945-4304-c7a46f471953', 4, 'Remember, everyone makes mistakes, and it''s normal to receive feedback. By listening and learning from criticism, I am showing maturity and growth.', 'recordar', '📝'),
  ('bf53021d-91dc-f945-4304-c7a46f471953', 5, 'I will remember that receiving feedback is a positive opportunity for me to learn and become better. I will try my best to respond calmly and with gratitude, knowing that each piece of criticism helps me improve in some way.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3cc0894b-ad86-f94c-d409-9bbd712520d2', 1, 'Sometimes, children may see their friends being bullied. It can be confusing and upsetting to witness someone being treated unkindly.', 'a veces', '⏳'),
  ('3cc0894b-ad86-f94c-d409-9bbd712520d2', 2, 'When a friend is being bullied, it''s important to show support. I can stand beside my friend and let them know I am there for them. Sometimes, just having someone by their side can make a big difference.', 'amigo', '🤝'),
  ('3cc0894b-ad86-f94c-d409-9bbd712520d2', 3, 'I can also help my friend by telling an adult about the bullying. Adults can help stop the hurtful behavior and make sure everyone feels safe at school or in the community.', 'ayuda', '🆘'),
  ('3cc0894b-ad86-f94c-d409-9bbd712520d2', 4, 'It''s essential to remember that everyone deserves to feel respected and valued. By supporting my friend who is being bullied, I am showing kindness and making a positive impact.', 'recordar', '📝'),
  ('3cc0894b-ad86-f94c-d409-9bbd712520d2', 5, 'Supporting friends who are bullied is a way to spread kindness and create a safe environment for everyone. Being there for each other makes us stronger as a community.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 1, 'Growing taller than my door mark I''m getting bigger, that''s for sure. But will I ever grow so tall,', 'puerta', '🚪'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 2, 'That I''ll reach above the door? Every year, I measure my height, And mark it on the wall.', 'puerta', '🚪'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 3, 'But lately, I''ve noticed something new, I''m growing really tall!', 'nuevo', '🆕'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 4, 'Last year, I was up to my dad''s shoulder, But now I''m almost at his chin.', 'ano', '✨'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 5, 'I can see over the kitchen counter, And reaching things is no longer a problem.', 'ver', '👀'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 6, 'My clothes are getting tighter, And my shoes feel too small. I used to fit in my bed perfectly,', 'ropa', '👗'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 7, 'But now my feet hang off the end. Growing taller is a natural change, It happens to everyone.', 'cambio', '🔄'),
  ('e5da371d-9601-5c3b-ab70-2db71099a0fc', 8, 'Even though it may feel strange, I''m proud of the person I''m becoming, and so should everyone be!', 'sentir', '💓');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4cec1c19-6bb9-17c7-e4ac-6021dc94af95', 1, 'When plans change, I can adapt and move forward. Sometimes things don’t go as expected, but that’s okay.', 'cambio', '🔄'),
  ('4cec1c19-6bb9-17c7-e4ac-6021dc94af95', 2, 'Plans can change for many reasons. Maybe the weather is different than we thought, or someone gets sick. It’s important to remember that changes happen sometimes, and it’s okay.', 'cambio', '🔄'),
  ('4cec1c19-6bb9-17c7-e4ac-6021dc94af95', 3, 'When plans change, I might feel a little confused or upset. That’s normal. I can take deep breaths or talk to someone about how I’m feeling. This can help me feel better.', 'respirar', '🫁'),
  ('4cec1c19-6bb9-17c7-e4ac-6021dc94af95', 4, 'It’s good to be flexible and try to go with the flow when things change. I can think of new ways to handle the situation and keep moving forward.', 'bien', '👍'),
  ('4cec1c19-6bb9-17c7-e4ac-6021dc94af95', 5, 'When plans change, I can remember to stay calm and adjust. Being able to adapt to changes helps me grow and learn new things.', 'cambio', '🔄');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fb4ad99b-22e9-b8d2-2db4-e3086e0a8b58', 1, 'Keeping germs away is important for staying healthy. Tissues and hand sanitizer help us do that. When we use tissues, we catch sneezes and coughs so germs don’t spread. Hand sanitizer kills germs on our hands to keep them clean.', 'importante', '❗'),
  ('fb4ad99b-22e9-b8d2-2db4-e3086e0a8b58', 2, 'When I feel a sneeze or cough coming, I can grab a tissue quickly. I cover my mouth and nose with the tissue. This stops germs from flying around. After using the tissue, I throw it in the trash. That way, the germs stay in the trash and not on my hands or other things.', 'sentir', '💓'),
  ('fb4ad99b-22e9-b8d2-2db4-e3086e0a8b58', 3, 'Hand sanitizer is like magic for keeping hands clean. A small amount goes a long way. I put some on my hands and rub them together until they are dry. This helps kill the germs that make me sick. It’s like having invisible shields on my hands!', 'mano', '🤚'),
  ('fb4ad99b-22e9-b8d2-2db4-e3086e0a8b58', 4, 'Staying germ-free is easy when I remember to use tissues and hand sanitizer. They are my helpers in keeping me healthy and strong. Remembering to use them will help me and others around me stay well.', 'facil', '😊');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2fec740b-abf2-e3d8-fc1d-6fcf92c2be8f', 1, 'Receiving feedback from others is a chance to learn and grow. Feedback helps me understand how I can improve and do better next time.', 'aprender', '📖'),
  ('2fec740b-abf2-e3d8-fc1d-6fcf92c2be8f', 2, 'When someone gives me feedback, it means they care about helping me get better. It''s important to listen carefully to what they say, even if it feels a little uncomfortable at first. Sometimes, the feedback may point out things I didn''t notice before, which can help me see things from a different perspective.', 'escuchar', '👂'),
  ('2fec740b-abf2-e3d8-fc1d-6fcf92c2be8f', 3, 'Constructive criticism is like a puzzle piece that fits into making me better. Just like putting together a puzzle, each piece of feedback helps complete the picture of my progress and skills. It''s okay to feel a bit unsure or surprised by the feedback, but remember, it''s all part of learning and growing.', 'gustar', '👍'),
  ('2fec740b-abf2-e3d8-fc1d-6fcf92c2be8f', 4, 'Listening to feedback without getting upset or defensive is a skill that takes practice. Taking a deep breath and staying calm can help me process the feedback in a positive way. Asking questions to clarify the feedback shows that I am interested in understanding and improving.', 'respirar', '🫁'),
  ('2fec740b-abf2-e3d8-fc1d-6fcf92c2be8f', 5, 'Feedback is a gift that can guide me towards becoming the best version of myself. Constructive criticism is an opportunity for me to learn and develop new skills.', 'regalo', '🎁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4ac56c68-9b9e-d1ff-beda-9596fb5fd2b2', 1, 'Lunchtime is a special break in the day. It''s a time to rest and refuel our bodies for the rest of the day.', 'especial', '⭐'),
  ('4ac56c68-9b9e-d1ff-beda-9596fb5fd2b2', 2, 'When it''s lunchtime, we stop what we''re doing and gather around to eat together. Sometimes there are different foods to choose from, and that can be exciting! We sit down, use our utensils, and enjoy our meal quietly.', 'parar', '✋'),
  ('4ac56c68-9b9e-d1ff-beda-9596fb5fd2b2', 3, 'After eating, we clean up by putting our dishes away and throwing any trash in the bin. This helps keep our space tidy and ready for the next activity.', 'comer', '🍽️'),
  ('4ac56c68-9b9e-d1ff-beda-9596fb5fd2b2', 4, 'Remember, lunchtime is just a short break before we continue with our day. It''s important to eat well so we have energy for playing and learning.', 'recordar', '📝'),
  ('4ac56c68-9b9e-d1ff-beda-9596fb5fd2b2', 5, 'During lunchtime, I will take a moment to relax and enjoy my food. When lunchtime is over, I will clean up after myself and get ready for the next part of the day.', 'vestirse', '👕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('3e66393e-ab32-cc15-ea70-b1499e607ebe', 1, 'Each person is unique and special in their own way. Our differences are what make us interesting and wonderful.', 'persona', '🧑'),
  ('3e66393e-ab32-cc15-ea70-b1499e607ebe', 2, 'Some people like to wear glasses because it helps them see better. Others may use a wheelchair to help them move around easily. These differences don''t make anyone less important or valuable.', 'algunos', '✨'),
  ('3e66393e-ab32-cc15-ea70-b1499e607ebe', 3, 'We all have different likes and dislikes. Some of us enjoy playing sports, while others prefer reading books. It''s these differences that make our world colorful and exciting.', 'todo', '🌐'),
  ('3e66393e-ab32-cc15-ea70-b1499e607ebe', 4, 'When we meet someone new, it''s important to remember that they may have different abilities or preferences than us. This doesn''t mean they are any less capable or deserving of respect.', 'alguien', '✨'),
  ('3e66393e-ab32-cc15-ea70-b1499e607ebe', 5, 'Sometimes, people express their feelings in different ways. While some may be very vocal about their emotions, others might prefer to keep them private. It''s essential to understand and respect these differences.', 'a veces', '⏳'),
  ('3e66393e-ab32-cc15-ea70-b1499e607ebe', 6, 'Remember, what makes us different also makes us special. Embracing diversity and showing empathy towards others can help us build meaningful connections and create a more inclusive and compassionate world.', 'recordar', '📝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('938b636f-dde9-3852-f469-46a2d948a0fd', 1, 'Sometimes people communicate without using words. They use their bodies and faces to show how they feel or what they want to say. This is called non-verbal communication.', 'a veces', '⏳'),
  ('938b636f-dde9-3852-f469-46a2d948a0fd', 2, 'When someone smiles, it usually means they are happy or friendly. If someone frowns, they might be feeling sad or upset. When a person crosses their arms, it could mean they are feeling defensive or closed off. These are just some examples of non-verbal cues that people use to express themselves.', 'alguien', '✨'),
  ('938b636f-dde9-3852-f469-46a2d948a0fd', 3, 'It''s important for me to pay attention to these cues so I can understand how others are feeling. If someone looks away while talking to me, it might mean they are feeling shy or nervous. If someone stands too close to me, they might not realize that I need more personal space. By noticing these cues, I can better understand the feelings and intentions of those around me.', 'espacio personal', '↔️'),
  ('938b636f-dde9-3852-f469-46a2d948a0fd', 4, 'I will practice paying attention to non-verbal cues in my daily interactions. It will help me understand others better and improve my own communication skills.', 'practicar', '🎯');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('2ba65842-35d0-6877-bedb-294e10b14125', 1, 'Breathing deep to find peace is something I can do when I feel upset or worried. It helps me calm down and feel better.', 'respirar', '🫁'),
  ('2ba65842-35d0-6877-bedb-294e10b14125', 2, 'When I take a deep breath, I fill my tummy with air like blowing up a balloon. Then I let the air out slowly, like letting the air out of a balloon. This makes me feel calmer and more relaxed. Taking deep breaths can help me when I''m feeling angry, scared, or overwhelmed. It''s a way to help myself feel better.', 'respirar', '🫁'),
  ('2ba65842-35d0-6877-bedb-294e10b14125', 3, 'Sometimes, it''s hard to remember to breathe deeply when I''m upset. But if I practice taking deep breaths when I''m calm, it will be easier for me to remember to do it when I need it most. I can also ask someone I trust to remind me to take deep breaths when they see that I''m upset.', 'respirar', '🫁'),
  ('2ba65842-35d0-6877-bedb-294e10b14125', 4, 'Taking deep breaths helps me feel peaceful and in control. I can use this skill whenever I need to calm down. I am learning how to take deep breaths to find peace.', 'respirar', '🫁');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('971a7609-c092-b698-1714-1e27e2125150', 1, 'Recognizing when someone is proud', 'alguien', '✨'),
  ('971a7609-c092-b698-1714-1e27e2125150', 2, 'When people feel proud, they stand tall and smile. They may say, “I did it!” or “Look what I made!” When someone feels proud, their eyes sparkle with happiness.', 'personas', '👥'),
  ('971a7609-c092-b698-1714-1e27e2125150', 3, 'Sometimes, a person might feel proud of themselves for doing something good, like finishing a puzzle or helping a friend. Other times, they might feel proud of someone else, like when a friend wins a game or finishes a project.', 'a veces', '⏳'),
  ('971a7609-c092-b698-1714-1e27e2125150', 4, 'I can tell when someone is proud by looking at their face and listening to their words. It’s nice to see others feeling proud, and it''s okay to feel proud myself when I do something great!', 'decir', '💬'),
  ('971a7609-c092-b698-1714-1e27e2125150', 5, 'Recognizing when someone is proud helps us understand how others are feeling. It''s wonderful to share in the joy of someone''s achievements and to feel proud of our own accomplishments too!', 'alguien', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('fb08cc1c-c648-8ce5-da3a-33a37c44beb5', 1, 'Water can be a lot of fun, but it''s important to stay safe around water. This story is about how I can stay safe when I am near water.', 'agua', '💧'),
  ('fb08cc1c-c648-8ce5-da3a-33a37c44beb5', 2, 'When I am near water, I need to remember some important rules. First, I should always have an adult with me when I am near water. They will help keep me safe and make sure I don''t go too deep.', 'agua', '💧'),
  ('fb08cc1c-c648-8ce5-da3a-33a37c44beb5', 3, 'I also need to listen to the lifeguards or adults who are in charge. They know all the safety rules and can tell me what to do if there is an emergency.', 'escuchar', '👂'),
  ('fb08cc1c-c648-8ce5-da3a-33a37c44beb5', 4, 'It''s important for me to wear a life jacket if I don''t know how to swim or if the water is deep. A life jacket will help me float and stay safe.', 'importante', '❗'),
  ('fb08cc1c-c648-8ce5-da3a-33a37c44beb5', 5, 'If I see someone struggling in the water, I should not try to rescue them myself. Instead, I should find an adult or a lifeguard who can help. It''s important to let the professionals handle these situations.', 'ver', '👀'),
  ('fb08cc1c-c648-8ce5-da3a-33a37c44beb5', 6, 'Staying safe around water is very important. By following the rules and listening to the adults in charge, I can have a great time while staying safe. Water can be a lot of fun when we are careful!', 'instrucciones', '📋');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('5a28c547-0521-c6e2-c15d-26f8053a5733', 1, 'Being part of a team means working together with others towards a common goal. Sometimes, I may need to be patient when things don''t go as planned or when my teammates need extra help.', 'equipo', '👥'),
  ('5a28c547-0521-c6e2-c15d-26f8053a5733', 2, 'When I am patient with my teammates, it shows that I care about them and our shared goal. Patience means waiting calmly without getting upset or frustrated. It''s important to remember that everyone has different strengths and weaknesses, and we can support each other by being patient.', 'paciencia', '🧘'),
  ('5a28c547-0521-c6e2-c15d-26f8053a5733', 3, 'If a teammate is struggling, I can offer encouragement and assistance instead of getting annoyed. I can say things like, "It''s okay, we all make mistakes sometimes" or "I''m here to help if you need me."', 'decir', '💬'),
  ('5a28c547-0521-c6e2-c15d-26f8053a5733', 4, 'Patience also means listening to others and taking turns during group activities. When I wait for my turn to speak or share ideas, it helps the team work smoothly together. By being patient, I can build stronger relationships with my teammates and achieve success as a group.', 'esperar', '⏳'),
  ('5a28c547-0521-c6e2-c15d-26f8053a5733', 5, 'Being patient with my teammates is an important part of teamwork. Together, we can accomplish great things when we support each other with understanding and kindness.', 'paciencia', '🧘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e40c273d-9fc8-8df6-e00b-f991ae9ad3d3', 1, 'Ava''s story of patience and understanding', 'paciencia', '🧘'),
  ('e40c273d-9fc8-8df6-e00b-f991ae9ad3d3', 2, 'Once upon a time, Ava was playing with her friend Max at the park. They were having so much fun on the swings when suddenly another child came and wanted to join in. The new child seemed excited but also a bit unsure.', 'tiempo', '⏰'),
  ('e40c273d-9fc8-8df6-e00b-f991ae9ad3d3', 3, 'Ava noticed that the child looked lost and confused, so she decided to show kindness and patience. She smiled warmly and said, "Hi, I''m Ava. Would you like to swing with us?" The new child''s face lit up with joy as they joined Ava and Max on the swings.', 'nino', '👦'),
  ('e40c273d-9fc8-8df6-e00b-f991ae9ad3d3', 4, 'Patience means waiting calmly and being understanding towards others, especially when they are feeling unsure or scared. Ava showed great patience by including the new child and making them feel welcome.', 'paciencia', '🧘'),
  ('e40c273d-9fc8-8df6-e00b-f991ae9ad3d3', 5, 'Ava''s story teaches us that patience and understanding can make a big difference in someone''s day. By showing kindness and being patient, we can create a welcoming and inclusive environment for everyone around us.', 'paciencia', '🧘');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('a4c66002-f66c-2956-4abf-47e472f5b7ae', 1, 'Recognizing comfort and discomfort in others is important. How can I tell if someone feels comfortable or uncomfortable?', 'importante', '❗'),
  ('a4c66002-f66c-2956-4abf-47e472f5b7ae', 2, 'When someone feels comfortable, they may smile, laugh, or make eye contact. They might also have relaxed body language, like sitting back in a chair or leaning in during a conversation.', 'alguien', '✨'),
  ('a4c66002-f66c-2956-4abf-47e472f5b7ae', 3, 'On the other hand, when someone feels uncomfortable, they may frown, avoid eye contact, or tense up their body. They might also try to move away from a situation or person that makes them feel uneasy.', 'otro', '🔄'),
  ('a4c66002-f66c-2956-4abf-47e472f5b7ae', 4, 'It''s essential to pay attention to these cues so we can respond appropriately and help others feel at ease. By noticing how people express comfort and discomfort, we can show empathy and support.', 'atencion', '📢'),
  ('a4c66002-f66c-2956-4abf-47e472f5b7ae', 5, 'Recognizing comfort and discomfort in others helps us be kind and understanding. When we pay attention to signals like smiles, laughter, or tension, we can better connect with those around us. Let''s keep practicing recognizing these signs to create positive interactions with others.', 'atencion', '📢');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e794d82e-b113-9da5-1fc4-08b852158f16', 1, 'Gifts are special things that people give to each other. They can be wrapped in colorful paper with a bow on top. But gifts are more than just things.', 'especial', '⭐'),
  ('e794d82e-b113-9da5-1fc4-08b852158f16', 2, 'When someone gives me a gift, it means they were thinking about me. They wanted to make me happy. It feels good to know that someone cares about me.', 'alguien', '✨'),
  ('e794d82e-b113-9da5-1fc4-08b852158f16', 3, 'Sometimes, I get excited when I see a big box or a shiny package. I wonder what could be inside! Opening the gift is like unwrapping a surprise. It''s fun to discover what''s hidden inside.', 'a veces', '⏳'),
  ('e794d82e-b113-9da5-1fc4-08b852158f16', 4, 'But gifts aren''t always toys or things I can play with. Sometimes, the best gifts are experiences. Like going to the zoo, having a picnic, or spending time together as a family. These gifts create memories that last forever.', 'siempre', '♾️'),
  ('e794d82e-b113-9da5-1fc4-08b852158f16', 5, 'When I receive a gift, it''s important to say "thank you." This shows appreciation and gratitude for the person who gave it to me. Saying thank you makes them feel good too.', 'gracias', '🙏'),
  ('e794d82e-b113-9da5-1fc4-08b852158f16', 6, 'Gifts are more than just things. They are expressions of love, kindness, and thoughtfulness. Whether it''s a toy, an experience, or simply someone''s presence, gifts remind us that we are cared for and valued.', 'mas', '➕');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('0b1c9b0e-fef6-e56e-240e-315e575ed062', 1, 'I am learning to use the potty like a big kid. Using the potty is an important skill that helps me stay clean and comfortable.', 'aprender', '📖'),
  ('0b1c9b0e-fef6-e56e-240e-315e575ed062', 2, 'When I feel like I need to go potty, I can tell an adult. They will help me get to the bathroom quickly. In the bathroom, there is a toilet where I can sit down. I pull my pants down and sit on the toilet seat. It''s important to remember to wash my hands with soap and water after using the potty.', 'lavarse', '🧼'),
  ('0b1c9b0e-fef6-e56e-240e-315e575ed062', 3, 'Sometimes accidents happen, and that''s okay. If I have an accident, I can change into clean clothes and try again next time. It''s all part of learning how to use the potty like a big kid.', 'a veces', '⏳'),
  ('0b1c9b0e-fef6-e56e-240e-315e575ed062', 4, 'Using the potty like a big kid is a new skill for me to learn. I will keep practicing and getting better at it each day. Remembering to tell an adult when I need to go and washing my hands are important steps in becoming more independent with using the potty.', 'bano', '🚽');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('72f961b4-91c5-2588-34f8-a7b267469038', 1, 'It''s important to be a good friend and treat others with kindness. Friends don''t let friends be bullied.', 'importante', '❗'),
  ('72f961b4-91c5-2588-34f8-a7b267469038', 2, 'Bullying is when someone hurts another person on purpose, either with words or actions. It can make the person being bullied feel sad, scared, or upset. If I see someone being bullied, I can help by telling an adult I trust. I can also support my friend by standing up for them and showing that bullying is not okay.', 'acoso', '🚫'),
  ('72f961b4-91c5-2588-34f8-a7b267469038', 3, 'Remember, it''s always better to be kind and inclusive. Being a good friend means supporting each other and creating a safe and happy environment for everyone.', 'recordar', '📝'),
  ('72f961b4-91c5-2588-34f8-a7b267469038', 4, 'Friends stick together and look out for each other. By being a caring and supportive friend, we can create a positive and respectful community where everyone feels valued and included. Remember, friends don''t let friends be bullies.', 'amigos', '🤝');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('4df1260e-d93b-3375-7d9c-f2df492c47a7', 1, 'Dressing for work is a special part of getting ready to go to work. It’s important because it helps me look professional and feel confident when I am at my job.', 'trabajar', '💼'),
  ('4df1260e-d93b-3375-7d9c-f2df492c47a7', 2, 'When I dress for work, I try to choose clothes that are clean and neat. This means making sure there are no stains or wrinkles on my clothes. I also make sure my clothes fit well and are comfortable to wear all day long.', 'vestirse', '👕'),
  ('4df1260e-d93b-3375-7d9c-f2df492c47a7', 3, 'Some jobs have specific dress codes, which means they may require certain types of clothing like uniforms or business attire. I will ask someone at my workplace about the dress code so I can be sure to follow it.', 'algunos', '✨'),
  ('4df1260e-d93b-3375-7d9c-f2df492c47a7', 4, 'It’s important to remember that dressing for work is not just about looking good, but also about feeling good. When I feel good in what I’m wearing, it can help me do my best at work.', 'importante', '❗'),
  ('4df1260e-d93b-3375-7d9c-f2df492c47a7', 5, 'By dressing neatly and comfortably for work, I show respect for myself and others. I will try to take pride in how I dress for work and always aim to present myself in a positive and professional manner.', 'trabajar', '💼');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 1, 'The unexpected surprise', 'sorpresa', '😮'),
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 2, 'I know that sometimes things can change unexpectedly. It might feel strange or surprising, but it''s okay.', 'saber', '🧠'),
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 3, 'Change happens all the time. Sometimes plans change, and we have to do something different than what we thought. This is called an unexpected surprise. It could be a new activity at school, a change in our routine, or even a sudden change in the weather. When these surprises happen, it''s important to remember that they are just part of life.', 'cambio', '🔄'),
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 4, 'When there''s an unexpected surprise, I might feel a little unsure or worried. That''s normal. But my mom, dad, or teacher will help me understand what''s happening and how to handle it. They care about me and want to make sure I''m okay.', 'sorpresa', '😮'),
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 5, 'It''s good to try and stay calm when there''s an unexpected surprise. Taking deep breaths and talking about how I feel can help me feel better. And if I need some time to adjust, that''s okay too. Change can take a little getting used to, but I can handle it.', 'respirar', '🫁'),
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 6, 'The unexpected surprise', 'sorpresa', '😮'),
  ('de951874-2ccb-9bcb-6f8a-2732aec9b979', 7, 'Sometimes things change unexpectedly, and that''s okay. I can talk to someone I trust about how I feel, and they''ll help me through it. I can handle unexpected surprises.', 'a veces', '⏳');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('c3029b96-1ff0-ac1b-0ed5-01c5b806daf1', 1, 'Today is different, and that''s okay. Change happens sometimes, and it can be a little surprising or confusing.', 'hoy', '✨'),
  ('c3029b96-1ff0-ac1b-0ed5-01c5b806daf1', 2, 'Change can happen in many ways. Sometimes the weather changes, like when it rains unexpectedly. Other times, our routines change, like when we have a substitute teacher at school. Change can also happen at home, maybe someone rearranged the furniture or we are having something new for dinner.', 'cambio', '🔄'),
  ('c3029b96-1ff0-ac1b-0ed5-01c5b806daf1', 3, 'When things change, it might feel strange at first. It''s normal to feel unsure or even a bit worried. But remember, change can bring new opportunities and experiences too. Maybe we''ll discover something fun about the new routine or find a new favorite food.', 'cosas', '📦'),
  ('c3029b96-1ff0-ac1b-0ed5-01c5b806daf1', 4, 'It''s important to remember that change is a part of life. We can learn to adapt and adjust to new situations. Talking about how we feel with someone we trust can help us understand and cope with the changes better.', 'importante', '❗'),
  ('c3029b96-1ff0-ac1b-0ed5-01c5b806daf1', 5, 'Today is different, and that''s okay. Change can be an adventure, bringing new possibilities and discoveries. I will try my best to embrace the changes that come my way.', 'hoy', '✨');
INSERT INTO story_pages (story_id, page_number, text, keyword, emoji) VALUES
  ('e6b544af-081f-4347-f13f-10b109a2c4c4', 1, 'Finding my voice against bullies is about standing up for myself and others in a respectful way. It''s important to know that I have the right to feel safe and respected at all times.', 'respeto', '🙇'),
  ('e6b544af-081f-4347-f13f-10b109a2c4c4', 2, 'Bullying can happen when someone tries to hurt another person on purpose, either with words or actions. If I see someone being bullied, I can help by telling an adult I trust. I can also use strong and confident words like, "Stop it, I don''t like that," or "That''s not okay."', 'acoso', '🚫'),
  ('e6b544af-081f-4347-f13f-10b109a2c4c4', 3, 'It''s essential to remember that everyone deserves kindness and respect. When we treat each other with care and understanding, we create a positive environment where bullying has no place. By showing empathy and support to those who are being bullied, we can make a difference together.', 'recordar', '📝'),
  ('e6b544af-081f-4347-f13f-10b109a2c4c4', 4, 'Finding my voice against bullies means speaking up for what is right and standing together against unkind behavior. Remember, I deserve to be treated with respect, and by supporting each other, we can build a community based on kindness and acceptance.', 'correcto', '✅');
